import { t, type DeepSet } from "../types";

/** Level 2, Foundations of Faith: the Spirit-led teaching for each lesson. */
export const DEEP: DeepSet = {
  "who-jesus-is": {
    revelation: t(
      "Jesus is not one part of your life to fit in somewhere; He is the center that everything else was made to hold on to.",
      "Si Hesus ay hindi isang bahagi lang ng buhay mo na isisingit kung saan may puwang; Siya ang sentro na dapat kapitan ng lahat ng iba pa."
    ),
    mainTruth: t(
      "John says the Word who was with God and was God \"became flesh and dwelt among us\" (John 1:1, 14). Paul says all things were created through Him and for Him, and \"in Him all things hold together\" (Colossians 1:16-17). Then Philippians 2:5-11 shows the same Jesus emptying Himself, taking the form of a servant and dying on a cross, before God exalts Him to the name above every name. The Creator became a creature, the King became a servant, and the One who holds the universe let Himself be held by nails. He is fully God and fully man: our Savior to trust and our Lord to obey.",
      "Sabi ni Juan, ang Salitang kasama ng Diyos at Siya mismong Diyos ay \"nagkatawang-tao at nanirahang kasama natin\" (Juan 1:1, 14). Sabi ni Pablo, ang lahat ng bagay ay nilikha sa pamamagitan Niya at para sa Kanya, at \"sa Kanya, ang lahat ay nananatiling buo\" (Colosas 1:16-17). Pagkatapos, ipinakita ng Filipos 2:5-11 ang parehong Hesus na hinubad ang Sarili, nag-anyong alipin at namatay sa krus, bago Siya itinaas ng Diyos at binigyan ng pangalang higit sa lahat ng pangalan. Ang Manlilikha ay naging nilikha, ang Hari ay naging alipin, at ang Humahawak sa sansinukob ay nagpahawak sa mga pako. Siya ay ganap na Diyos at ganap na tao: ang Tagapagligtas na dapat pagtiwalaan at ang Panginoon na dapat sundin."
    ),
    insight: [
      t(
        "Many believers have a Jesus who is big on Sunday and small on Monday. In church He is \"King of kings\"; at the office, in the budget and in the family quarrel He is barely consulted. But Colossians says He holds ALL things together, not only the religious things. If He holds the stars in place, He is not too busy for your contract, your rent or your teenager. A Jesus who is Lord only in church is a Jesus we have shrunk to fit our comfort.",
        "Maraming mananampalataya ang may Hesus na malaki tuwing Linggo pero maliit tuwing Lunes. Sa simbahan, Siya ang \"Hari ng mga hari\"; sa opisina, sa budget at sa away ng pamilya, halos hindi Siya kinokonsulta. Pero sabi ng Colosas, hawak Niya ang LAHAT ng bagay, hindi lang ang mga bagay na pangrelihiyon. Kung hawak Niya ang mga bituin sa kinalalagyan nila, hindi Siya masyadong abala para sa kontrata mo, sa upa mo o sa anak mong tinedyer. Ang Hesus na Panginoon lang sa loob ng simbahan ay Hesus na pinaliit natin para sa sariling ginhawa."
      ),
      t(
        "Notice also that Paul does not give Philippians 2 as a theology lecture. He begins, \"Have this mind among yourselves\" (Philippians 2:5). The deepest doctrine about Christ was written to fix a church problem: selfishness and rivalry. Knowing who Jesus is was never meant to make us win debates; it was meant to make us kneel, and then to make us serve like Him.",
        "Pansinin din na hindi ibinigay ni Pablo ang Filipos 2 bilang leksiyon sa teolohiya. Nagsimula siya sa, \"Taglayin ninyo ang ganitong pag-iisip\" (Filipos 2:5). Ang pinakamalalim na katuruan tungkol kay Kristo ay isinulat para ayusin ang problema ng iglesya: pagkamakasarili at pagpapaligsahan. Ang pagkakilala kung sino si Hesus ay hindi para manalo tayo sa debate; para ito lumuhod tayo, at pagkatapos ay maglingkod gaya Niya."
      ),
    ],
    life: [
      t(
        "Picture a jeepney. It has colorful decorations, a loud sound system, a name painted on the side. But without the engine, it is just a very pretty parking ornament. Many lives are like that: career, family, church activities, all well decorated, but Jesus is a sticker on the windshield instead of the engine under the hood. He was never meant to be decoration. He is the power that moves the whole thing.",
        "Isipin ang isang dyip. Makulay ang palamuti, malakas ang sound system, may pangalang nakapinta sa gilid. Pero kung walang makina, isa lang itong napakagandang dekorasyon na nakaparada. Ganyan ang maraming buhay: karera, pamilya, gawain sa simbahan, lahat maganda ang ayos, pero si Hesus ay sticker lang sa windshield sa halip na makina sa ilalim ng hood. Hindi Siya kailanman ginawang palamuti. Siya ang kapangyarihang nagpapatakbo sa lahat."
      ),
      t(
        "An OFW in Dubai once said, \"I prayed for this job, but now that I have it, I handle it myself.\" Many of us invite Jesus into our crises and dismiss Him once the crisis passes. Who Jesus is should change how you spend your rest day, how you answer your boss, how you send money home and how you speak on the phone with your spouse. When He is Lord, every ordinary moment becomes a place to honor Him.",
        "May isang OFW sa Dubai na nagsabi, \"Ipinagdasal ko ang trabahong ito, pero ngayong nandito na ako, ako na ang bahala.\" Marami sa atin ang nag-iimbita kay Hesus sa gitna ng krisis at pinaaalis Siya kapag lumipas na ito. Ang pagkakilala kung sino si Hesus ay dapat magbago kung paano mo ginugugol ang day off mo, paano ka sumasagot sa amo mo, paano ka nagpapadala ng pera pauwi at paano ka nakikipag-usap sa telepono sa asawa mo. Kapag Siya ang Panginoon, bawat karaniwang sandali ay nagiging lugar para parangalan Siya."
      ),
    ],
    twist: t(
      "We expect the name above every name to be given to the one who climbed highest. But in Philippians 2, the word \"Therefore\" (v. 9) connects Jesus' exaltation to His descent. God lifted Him up BECAUSE He went down. In the Kingdom, the way up is down. The Jesus who holds all things together did not grab equality with God; He gave Himself away. If you want to be like Him, stop climbing over people and start kneeling beside them.",
      "Inaasahan natin na ang pangalang higit sa lahat ng pangalan ay ibibigay sa umakyat nang pinakamataas. Pero sa Filipos 2, ang salitang \"Kaya nga\" (t. 9) ay nagdudugtong sa pagkataas ni Hesus at sa Kanyang pagbaba. Itinaas Siya ng Diyos DAHIL bumaba Siya. Sa Kaharian, ang daan paakyat ay pababa. Ang Hesus na humahawak sa lahat ng bagay ay hindi kumapit sa pagkapantay sa Diyos; ibinigay Niya ang Sarili. Kung gusto mong maging tulad Niya, tumigil sa pag-akyat sa ibabaw ng ibang tao at magsimulang lumuhod sa tabi nila."
    ),
    confirm: [
      t("Hebrews 1:3: the Son is the radiance of God's glory and upholds the universe by His word.", "Hebreo 1:3: ang Anak ang ningning ng kaluwalhatian ng Diyos at inaalalayan ang sansinukob sa Kanyang salita."),
      t("Mark 4:41: the disciples ask, \"Who then is this, that even the wind and the sea obey Him?\"", "Marcos 4:41: nagtanong ang mga alagad, \"Sino ba Ito at maging ang hangin at dagat ay sumusunod sa Kanya?\""),
      t("John 13:3-5: knowing all authority was His, Jesus took a towel and washed feet.", "Juan 13:3-5: alam ni Hesus na nasa Kanya ang lahat ng kapangyarihan, kaya kumuha Siya ng tuwalya at naghugas ng mga paa."),
      t("Revelation 5:12: heaven sings, \"Worthy is the Lamb who was slain.\"", "Pahayag 5:12: umaawit ang langit, \"Karapat-dapat ang Korderong pinatay.\""),
    ],
    heart: [
      t(
        "Let Jesus move from the margin to the center. Stop asking, \"Where can I fit God into my schedule?\" and start asking, \"Lord, how do You want my schedule to fit You?\"",
        "Hayaang lumipat si Hesus mula sa gilid tungo sa gitna. Tumigil sa pagtatanong ng, \"Saan ko maisisingit ang Diyos sa schedule ko?\" at magsimulang magtanong ng, \"Panginoon, paano Mo gustong iakma ang schedule ko sa Iyo?\""
      ),
      t(
        "Let His humility confront your pride. The One with every right to be served chose to serve; the believer who knows Him will carry that same towel.",
        "Hayaang harapin ng Kanyang kababaang-loob ang iyong kayabangan. Ang may buong karapatang paglingkuran ay piniling maglingkod; ang mananampalatayang nakakikilala sa Kanya ay magdadala ng parehong tuwalya."
      ),
    ],
    questions: [
      t("In which area of your life is Jesus your Savior but not yet your Lord?", "Saang bahagi ng buhay mo si Hesus ay Tagapagligtas mo pero hindi pa Panginoon?"),
      t("Is Jesus the engine of your life or only a sticker on the windshield? What shows it?", "Si Hesus ba ang makina ng buhay mo o sticker lang sa windshield? Ano ang nagpapatunay nito?"),
      t("Which part of your week do you usually handle without Him?", "Aling bahagi ng linggo mo ang karaniwan mong hinaharap nang wala Siya?"),
      t("Where is God asking you to \"go down\" in humility like Christ this week?", "Saan ka hinihiling ng Diyos na \"bumaba\" sa kababaang-loob gaya ni Kristo ngayong linggo?"),
    ],
    actions: [
      t("Read John 1:1-14 aloud and list every title or description of Jesus you find. Worship Him with that list.", "Basahin nang malakas ang Juan 1:1-14 at ilista ang bawat titulo o paglalarawan kay Hesus na makikita mo. Sambahin Siya gamit ang listahang iyon."),
      t("Pick one area you have kept from Him (money, work, a relationship) and pray, \"Jesus, You are Lord here too.\"", "Pumili ng isang bahaging inilayo mo sa Kanya (pera, trabaho, relasyon) at manalangin, \"Hesus, Panginoon Ka rin dito.\""),
      t("Do one humble act of service this week for someone who cannot repay you.", "Gumawa ng isang mapagpakumbabang paglilingkod ngayong linggo para sa taong hindi makagaganti sa iyo."),
    ],
    prayer: t(
      "Lord Jesus, You are the Word made flesh, the One through whom all things were made and in whom all things hold together. Forgive me for keeping You at the edges of my life. Today I give You the center: my work, my money, my family, my future. You went down so I could be lifted up; teach me to walk the same humble road. Be my Savior and my Lord in every room of my life. In Your name, Amen.",
      "Panginoong Hesus, Ikaw ang Salitang nagkatawang-tao, ang Isa na sa pamamagitan Niya nilikha ang lahat at sa Kanya nananatiling buo ang lahat. Patawarin Mo ako sa paglalagay sa Iyo sa gilid ng aking buhay. Ngayon, ibinibigay ko sa Iyo ang gitna: ang trabaho ko, pera ko, pamilya ko, kinabukasan ko. Bumaba Ka upang ako ay maitaas; turuan Mo akong lumakad sa parehong mapagpakumbabang daan. Maging Tagapagligtas at Panginoon Kita sa bawat silid ng aking buhay. Sa Iyong pangalan, Amen."
    ),
  },

  "saved-by-grace": {
    revelation: t(
      "Grace did not only open the door for you to enter; it is also the strength that teaches you to walk once you are inside.",
      "Ang biyaya ay hindi lang nagbukas ng pinto para makapasok ka; ito rin ang lakas na nagtuturo sa iyong lumakad kapag nasa loob ka na."
    ),
    mainTruth: t(
      "Paul describes us as dead in sins, following the world and the devil, \"children of wrath\" (Ephesians 2:1-3). Then come two words that change everything: \"But God.\" Rich in mercy, He made us alive with Christ, \"for by grace you have been saved through faith... not a result of works\" (Ephesians 2:4-9). Yet grace does not stop at pardon. Titus 2:11-12 says the grace of God \"has appeared, bringing salvation,\" and it is \"training us to renounce ungodliness.\" Paul can say, \"I have been crucified with Christ... Christ lives in me\" (Galatians 2:20). We are saved by grace, and we live by the same grace.",
      "Inilarawan tayo ni Pablo bilang patay sa kasalanan, sumusunod sa sanlibutan at sa diyablo, \"mga anak ng poot\" (Efeso 2:1-3). Pagkatapos, may dalawang salitang bumago sa lahat: \"Ngunit ang Diyos.\" Mayaman sa awa, binuhay Niya tayo kasama ni Kristo, \"sapagkat dahil sa biyaya kayo ay naligtas sa pamamagitan ng pananampalataya... hindi dahil sa gawa\" (Efeso 2:4-9). Pero hindi humihinto ang biyaya sa kapatawaran. Sabi ng Tito 2:11-12, ang biyaya ng Diyos ay \"nahayag, nagdadala ng kaligtasan,\" at ito ay \"nagtuturo sa atin na talikuran ang kasamaan.\" Kaya masasabi ni Pablo, \"Ako ay napako sa krus kasama ni Kristo... si Kristo ang nabubuhay sa akin\" (Galacia 2:20). Naligtas tayo sa biyaya, at nabubuhay tayo sa parehong biyaya."
    ),
    insight: [
      t(
        "Many believers start with grace and then quietly switch to effort. They were saved as a gift, but now they try to stay accepted by performance: enough prayer, enough service, enough good days. When they fail, they hide from God until they feel \"clean enough\" to come back. Paul calls that a return to the law and warns that it \"nullifies the grace of God\" (Galatians 2:21). You did not earn your way in, and you do not earn your way to stay.",
        "Maraming mananampalataya ang nagsimula sa biyaya tapos tahimik na lumipat sa sariling pagsisikap. Naligtas sila bilang regalo, pero ngayon sinisikap nilang manatiling tanggap sa pamamagitan ng performance: sapat na dasal, sapat na paglilingkod, sapat na magandang araw. Kapag nagkamali sila, nagtatago sila sa Diyos hanggang pakiramdam nila ay \"malinis na sila\" para bumalik. Tinawag ito ni Pablo na pagbalik sa kautusan at nagbabala na ito ay \"nagpapawalang-saysay sa biyaya ng Diyos\" (Galacia 2:21). Hindi mo pinaghirapan ang pagpasok, at hindi mo rin pinaghihirapan ang pananatili."
      ),
      t(
        "The opposite mistake is just as common: \"I am saved by grace, so it does not matter how I live.\" But read the very next verse after the famous one: we are \"created in Christ Jesus for good works\" (Ephesians 2:10). Grace is not a permission slip to sin; it is a teacher that trains us to say no to it (Titus 2:12). Real grace never leaves a person the same.",
        "Kasingkaraniwan din ang kabaligtarang pagkakamali: \"Naligtas ako sa biyaya, kaya hindi na mahalaga kung paano ako mamuhay.\" Pero basahin ang kasunod na talata ng sikat na bersikulo: tayo ay \"nilikha kay Kristo Hesus para sa mabubuting gawa\" (Efeso 2:10). Ang biyaya ay hindi permiso para magkasala; ito ay gurong nagsasanay sa ating tumanggi rito (Tito 2:12). Ang tunay na biyaya ay hindi kailanman nag-iiwan sa tao na gaya ng dati."
      ),
    ],
    life: [
      t(
        "Many Filipinos grew up with utang na loob: when someone helps you, you owe them for life. So we treat God's grace the same way, as a debt we can never finish paying, and we serve Him out of pressure and guilt. But grace is not a loan; it is a gift. The right response to a gift is not repayment but gratitude, and gratitude serves with joy instead of fear.",
        "Maraming Pilipino ang lumaki sa utang na loob: kapag may tumulong sa iyo, may utang ka habambuhay. Kaya ganoon din ang turing natin sa biyaya ng Diyos, isang utang na hindi matatapos bayaran, at naglilingkod tayo sa Kanya dahil sa pressure at konsensya. Pero ang biyaya ay hindi pautang; ito ay regalo. Ang tamang tugon sa regalo ay hindi pagbabayad kundi pasasalamat, at ang pasasalamat ay naglilingkod nang may galak, hindi nang may takot."
      ),
      t(
        "A caregiver in Hong Kong shared that for years she felt she had to read three chapters a day or God would be disappointed in her. One night after a twelve-hour shift, she fell asleep without praying and woke up afraid. Then she read Ephesians 2:8 again and wept: \"It is the gift of God.\" Her devotions did not stop; they changed. She started meeting God like a daughter, not like an employee clocking in.",
        "May isang caregiver sa Hong Kong na nagkuwento na sa loob ng maraming taon, pakiramdam niya ay kailangan niyang magbasa ng tatlong kabanata araw-araw, kung hindi ay madidismaya ang Diyos sa kanya. Isang gabi, pagkatapos ng labindalawang oras na shift, nakatulog siya nang hindi nakapagdasal at nagising na takot. Binasa niya ulit ang Efeso 2:8 at umiyak: \"Ito ay kaloob ng Diyos.\" Hindi tumigil ang kanyang debosyon; nagbago ito. Nagsimula siyang lumapit sa Diyos bilang anak, hindi bilang empleyadong nagta-time in."
      ),
    ],
    twist: t(
      "We think grace is soft and law is strict. But Titus 2 says it is GRACE that trains us to renounce ungodliness. Rules can only tell you what to do; grace gives you a new heart that wants to do it. The law says, \"Do this and live.\" Grace says, \"Christ lives in you, now walk.\" Grace is actually more demanding than law, because it does not want only your behavior; it wants your whole heart, and it gives you the power to give it.",
      "Akala natin malambot ang biyaya at mahigpit ang kautusan. Pero sabi ng Tito 2, ang BIYAYA ang nagsasanay sa ating talikuran ang kasamaan. Ang mga patakaran ay nagsasabi lang kung ano ang gagawin; ang biyaya ay nagbibigay ng bagong pusong gustong gawin ito. Sabi ng kautusan, \"Gawin mo ito at mabubuhay ka.\" Sabi ng biyaya, \"Nabubuhay si Kristo sa iyo, ngayon lumakad ka.\" Mas malaki pa nga ang hinihingi ng biyaya kaysa sa kautusan, dahil hindi lang ang kilos mo ang gusto nito; ang buong puso mo, at binibigyan ka nito ng kapangyarihang ibigay iyon."
    ),
    confirm: [
      t("Luke 15:20-24: the father runs to the returning son before he can finish his speech.", "Lucas 15:20-24: tumakbo ang ama sa nagbabalik na anak bago pa nito matapos ang kanyang talumpati."),
      t("1 Corinthians 15:10: \"By the grace of God I am what I am,\" and grace made Paul work hard.", "1 Corinto 15:10: \"Dahil sa biyaya ng Diyos, ako ay kung ano ako,\" at ang biyaya ang nagpasipag kay Pablo."),
      t("Romans 6:1-2: shall we keep sinning so grace may increase? By no means!", "Roma 6:1-2: magpapatuloy ba tayo sa kasalanan para dumami ang biyaya? Hindi kailanman!"),
      t("John 1:16: from His fullness we have all received grace upon grace.", "Juan 1:16: mula sa Kanyang kapuspusan, tumanggap tayong lahat ng biyaya sa ibabaw ng biyaya."),
    ],
    heart: [
      t(
        "Trade fear for gratitude. Serve God because you are already loved, not to become loved.",
        "Ipagpalit ang takot sa pasasalamat. Paglingkuran ang Diyos dahil mahal ka na Niya, hindi para mahalin ka pa lang Niya."
      ),
      t(
        "Let grace become your teacher. When temptation comes, do not only grit your teeth; remember who lives in you and ask for His strength.",
        "Hayaang maging guro mo ang biyaya. Kapag dumating ang tukso, huwag lang tiisin nang nakakuyom ang ngipin; alalahanin kung Sino ang nabubuhay sa iyo at humingi ng Kanyang lakas."
      ),
    ],
    questions: [
      t("Do you relate to God more like a child receiving a gift or a worker earning wages?", "Mas lumalapit ka ba sa Diyos bilang anak na tumatanggap ng regalo o bilang trabahador na kumikita ng sahod?"),
      t("When you fail, do you run to God or hide from Him until you feel better?", "Kapag nagkamali ka, tumatakbo ka ba sa Diyos o nagtatago ka hanggang gumaan ang pakiramdam mo?"),
      t("Is there any sin you excuse by saying, \"Anyway, I am saved by grace\"?", "May kasalanan ba na pinalulusot mo sa pagsasabing, \"Ligtas naman ako sa biyaya\"?"),
      t("What good work has God prepared for you that you have been avoiding?", "Anong mabuting gawa ang inihanda ng Diyos para sa iyo na iniiwasan mo?"),
    ],
    actions: [
      t("Memorize Ephesians 2:8-10 together, all three verses, so you keep gift and good works side by side.", "Isaulo ang Efeso 2:8-10 nang buo, tatlong talata, para magkasama lagi sa isip mo ang regalo at ang mabubuting gawa."),
      t("The next time you fail, go to God within five minutes. Confess, receive, and get up.", "Sa susunod na magkamali ka, lumapit sa Diyos sa loob ng limang minuto. Magpahayag, tumanggap, at bumangon."),
      t("Do one good work this week simply out of thanks, and tell God, \"This is because You saved me.\"", "Gumawa ng isang mabuting gawa ngayong linggo dahil lang sa pasasalamat, at sabihin sa Diyos, \"Ito ay dahil iniligtas Mo ako.\""),
    ],
    prayer: t(
      "Father, I was dead in my sins, but You, rich in mercy, made me alive with Christ. I did not earn it and I cannot repay it; I can only receive it and thank You. Forgive me for trying to stay accepted by my own effort, and for the times I used grace as an excuse. Let Your grace train me to say no to sin and yes to You. Christ, live in me today. Amen.",
      "Ama, patay ako sa aking mga kasalanan, pero Ikaw, na mayaman sa awa, ay binuhay ako kasama ni Kristo. Hindi ko ito pinaghirapan at hindi ko ito kayang bayaran; tatanggapin ko lang at pasasalamatan Ka. Patawarin Mo ako sa pagsisikap na manatiling tanggap sa sarili kong lakas, at sa mga pagkakataong ginamit ko ang biyaya bilang palusot. Hayaan Mong sanayin ako ng Iyong biyaya na tumanggi sa kasalanan at tumanggap sa Iyo. Kristo, mabuhay Ka sa akin ngayong araw. Amen."
    ),
  },

  "identity-in-christ": {
    revelation: t(
      "Before you ever did anything for God, He already decided who you are in Christ, and no label from people can overrule His word.",
      "Bago ka pa gumawa ng anuman para sa Diyos, napagpasyahan na Niya kung sino ka kay Kristo, at walang tatak mula sa tao ang makapagpapawalang-bisa sa Kanyang salita."
    ),
    mainTruth: t(
      "Ephesians 1:3-8 piles up what God has already done \"in Christ\": He blessed us with every spiritual blessing, chose us before the foundation of the world, adopted us as sons and daughters, redeemed and forgave us. Peter tells scattered, mistreated believers, \"You are a chosen race, a royal priesthood, a holy nation, a people for His own possession\" (1 Peter 2:9-10). And Paul declares, \"In Christ Jesus you are all sons of God, through faith,\" where Jew and Greek, slave and free, male and female are one (Galatians 3:26-29). Your identity is not something you build; it is something you receive in Him.",
      "Sunod-sunod na inilista ng Efeso 1:3-8 ang nagawa na ng Diyos \"kay Kristo\": pinagpala tayo ng bawat espirituwal na pagpapala, pinili bago pa likhain ang sanlibutan, inampon bilang mga anak, tinubos at pinatawad. Sinabi ni Pedro sa mga mananampalatayang nakakalat at inaapi, \"Kayo ay lahing pinili, maharlikang pagkasaserdote, bansang banal, bayang pag-aari ng Diyos\" (1 Pedro 2:9-10). At ipinahayag ni Pablo, \"Kay Kristo Hesus, kayong lahat ay mga anak ng Diyos sa pamamagitan ng pananampalataya,\" kung saan ang Judio at Griyego, alipin at malaya, lalaki at babae ay iisa (Galacia 3:26-29). Ang pagkakakilanlan mo ay hindi bagay na itinatayo mo; ito ay tinatanggap mo sa Kanya."
    ),
    insight: [
      t(
        "Most of what we believe about ourselves was written by other voices: a parent who said \"wala kang kwenta,\" a teacher who laughed, a boss who treats you like a machine, an ex who left. Many believers know Ephesians 1 by heart and still live by the old labels. The battle is not only to believe in God, but to believe what God says about YOU.",
        "Karamihan ng pinaniniwalaan natin tungkol sa sarili ay isinulat ng ibang tinig: magulang na nagsabing \"wala kang kwenta,\" gurong tumawa, amo na ang turing sa iyo ay makina, dating karelasyong umalis. Maraming mananampalataya ang kabisado ang Efeso 1 pero nabubuhay pa rin sa mga lumang tatak. Ang laban ay hindi lang ang maniwala sa Diyos, kundi maniwala sa sinasabi ng Diyos tungkol sa IYO."
      ),
      t(
        "Notice that every blessing in Ephesians 1 is in the past tense: chose, blessed, adopted, redeemed. Identity comes before activity. The world says, \"Do well and you will become somebody.\" God says, \"You already are somebody in Christ; now live like it.\" When we reverse the order, ministry becomes a stage for proving ourselves instead of an overflow of being loved.",
        "Pansinin na ang bawat pagpapala sa Efeso 1 ay nasa nakaraang panahunan: pinili, pinagpala, inampon, tinubos. Nauuna ang pagkakakilanlan bago ang gawain. Sabi ng mundo, \"Galingan mo at magiging somebody ka.\" Sabi ng Diyos, \"Somebody ka na kay Kristo; ngayon, mamuhay ka ayon dito.\" Kapag binaliktad natin ang pagkakasunod, ang ministeryo ay nagiging entablado para patunayan ang sarili sa halip na pag-apaw ng pagiging minamahal."
      ),
    ],
    life: [
      t(
        "Abroad, many OFWs are known by a function: \"the nanny,\" \"the driver,\" \"the helper.\" Some employers do not even use your name. It is easy to start believing that this is all you are. But in God's eyes, the domestic worker who loves Jesus is a royal priest, a chosen daughter, a citizen of heaven. Your uniform tells what you do; Christ tells who you are.",
        "Sa abroad, maraming OFW ang kilala lang sa kanilang trabaho: \"ang yaya,\" \"ang driver,\" \"ang helper.\" May mga amo pa ngang hindi gumagamit ng pangalan mo. Madaling maniwala na iyon lang ang pagkatao mo. Pero sa paningin ng Diyos, ang kasambahay na umiibig kay Hesus ay maharlikang saserdote, piniling anak, mamamayan ng langit. Ang uniporme mo ay nagsasabi kung ano ang ginagawa mo; si Kristo ang nagsasabi kung sino ka."
      ),
      t(
        "A young man grew up hearing that he was \"the problem child\" of the family. Even after he came to Christ, he expected to fail, so he did. A mentor asked him to write Ephesians 1:3-8 and replace every \"us\" with his own name. He read it every morning for a month. Slowly he stopped introducing himself with an apology. What changed was not his past; it was the voice he chose to believe.",
        "May isang binatang lumaking naririnig na siya raw ang \"pasaway\" ng pamilya. Kahit nang lumapit na siya kay Kristo, inaasahan niyang mabibigo siya, kaya nabigo nga siya. Hiniling ng kanyang mentor na isulat niya ang Efeso 1:3-8 at palitan ang bawat \"tayo\" ng sarili niyang pangalan. Binasa niya ito tuwing umaga sa loob ng isang buwan. Unti-unti, tumigil siyang magpakilala nang may paumanhin. Hindi ang nakaraan niya ang nagbago; ang tinig na pinili niyang paniwalaan."
      ),
    ],
    twist: t(
      "Peter wrote \"chosen, royal, holy\" to people who were exiles, rejected by their society and suffering for their faith. God's word over you is not based on your circumstances; it often contradicts them. You may be poor, far from home and overlooked, and still be royalty. And here is the surprise: this royal identity exists so that you may \"proclaim the excellencies of Him who called you\" (1 Peter 2:9). Your identity is not a mirror to admire yourself; it is a window for others to see God.",
      "Isinulat ni Pedro ang \"pinili, maharlika, banal\" sa mga taong dayuhan, tinanggihan ng kanilang lipunan at nagdurusa dahil sa pananampalataya. Ang salita ng Diyos tungkol sa iyo ay hindi nakabatay sa kalagayan mo; madalas nga ay salungat pa ito roon. Maaaring mahirap ka, malayo sa bahay at hindi napapansin, pero maharlika ka pa rin. At heto ang sorpresa: ang maharlikang pagkakakilanlang ito ay para \"ipahayag mo ang kadakilaan ng tumawag sa iyo\" (1 Pedro 2:9). Ang pagkakakilanlan mo ay hindi salamin para hangaan ang sarili; ito ay bintana para makita ng iba ang Diyos."
    ),
    confirm: [
      t("Judges 6:12: God calls fearful Gideon \"mighty man of valor\" before he does anything brave.", "Hukom 6:12: tinawag ng Diyos ang takot na si Gideon na \"magiting na mandirigma\" bago pa siya gumawa ng anumang matapang."),
      t("Matthew 3:17: the Father says \"My beloved Son\" before Jesus begins His ministry.", "Mateo 3:17: sinabi ng Ama ang \"Minamahal kong Anak\" bago pa magsimula ang ministeryo ni Hesus."),
      t("Romans 8:15-16: we received the Spirit of adoption and cry, \"Abba! Father!\"", "Roma 8:15-16: tinanggap natin ang Espiritu ng pag-aampon at sumisigaw tayo, \"Abba! Ama!\""),
      t("2 Corinthians 5:17: if anyone is in Christ, he is a new creation.", "2 Corinto 5:17: kung ang sinuman ay nakay Kristo, siya ay bagong nilalang."),
    ],
    heart: [
      t(
        "Stop letting old labels have the last word. When the inner voice says \"failure,\" answer it with what God says: \"chosen, forgiven, adopted.\"",
        "Huwag nang hayaang ang mga lumang tatak ang may huling salita. Kapag sinabi ng tinig sa loob na \"talunan,\" sagutin ito ng sinasabi ng Diyos: \"pinili, pinatawad, inampon.\""
      ),
      t(
        "Let security replace striving. A child who knows he is loved does not need to compete for attention; he is free to serve others.",
        "Hayaang palitan ng kapanatagan ang pagpupumilit. Ang anak na alam na mahal siya ay hindi kailangang makipag-agawan sa atensyon; malaya siyang maglingkod sa iba."
      ),
    ],
    questions: [
      t("What labels from your past still speak the loudest in your mind?", "Anong mga tatak mula sa nakaraan mo ang pinakamalakas pa ring nagsasalita sa isip mo?"),
      t("Which truth from Ephesians 1:3-8 is hardest for you to believe about yourself?", "Aling katotohanan mula sa Efeso 1:3-8 ang pinakamahirap mong paniwalaan tungkol sa sarili mo?"),
      t("Do you serve God to be accepted, or because you are already accepted?", "Naglilingkod ka ba sa Diyos para matanggap, o dahil tanggap ka na?"),
      t("How would your week change if you truly believed you are a royal priest?", "Paano magbabago ang linggo mo kung tunay mong paniniwalaan na ikaw ay maharlikang saserdote?"),
    ],
    actions: [
      t("Write Ephesians 1:3-8 with your own name in it and read it aloud every morning this week.", "Isulat ang Efeso 1:3-8 na may sarili mong pangalan at basahin ito nang malakas tuwing umaga ngayong linggo."),
      t("List three lies you have believed about yourself, and beside each write the verse that answers it.", "Ilista ang tatlong kasinungalingang pinaniwalaan mo tungkol sa sarili, at sa tabi ng bawat isa, isulat ang talatang sumasagot dito."),
      t("Speak one identity-giving word to another believer this week: \"You are chosen and loved by God.\"", "Magsalita ng isang salitang nagbibigay ng pagkakakilanlan sa isang kapatid ngayong linggo: \"Pinili ka at mahal ka ng Diyos.\""),
    ],
    prayer: t(
      "Father, thank You for choosing me before the world began, for adopting me, forgiving me and blessing me in Christ. Many voices have told me who I am, but today I choose to believe Yours. Silence the old labels and write Your truth on my heart. Let me live as Your child, secure and free, and let my life proclaim Your goodness to the people around me. In Jesus' name, Amen.",
      "Ama, salamat sa pagpili Mo sa akin bago pa nagsimula ang mundo, sa pag-ampon, pagpapatawad at pagpapala sa akin kay Kristo. Maraming tinig ang nagsabi sa akin kung sino ako, pero ngayon pinipili kong paniwalaan ang sa Iyo. Patahimikin Mo ang mga lumang tatak at isulat Mo ang Iyong katotohanan sa aking puso. Hayaan Mo akong mamuhay bilang anak Mo, panatag at malaya, at hayaang ipahayag ng buhay ko ang Iyong kabutihan sa mga tao sa paligid ko. Sa pangalan ni Hesus, Amen."
    ),
  },

  "forgiven-and-forgiving": {
    revelation: t(
      "The size of the mercy you have received is the measure of the mercy you can give; unforgiveness is a sign that we have forgotten our own debt.",
      "Ang laki ng awang tinanggap mo ang sukatan ng awang kaya mong ibigay; ang hindi pagpapatawad ay tanda na nakalimutan na natin ang sarili nating utang."
    ),
    mainTruth: t(
      "Psalm 103 tells us the Lord is \"merciful and gracious, slow to anger,\" and \"as far as the east is from the west, so far does He remove our transgressions from us\" (Psalm 103:8-12). In Matthew 18:21-35, Peter offers to forgive seven times; Jesus answers with a story of a servant forgiven a debt he could never pay, who then chokes a fellow servant over a small amount. The master's verdict is sharp: \"Should not you have had mercy... as I had mercy on you?\" Paul turns it into a command: \"Be kind to one another, tenderhearted, forgiving one another, as God in Christ forgave you\" (Ephesians 4:31-32). The forgiven are called to become forgivers.",
      "Sinasabi ng Awit 103 na ang Panginoon ay \"mahabagin at mapagpala, hindi madaling magalit,\" at \"kung gaano kalayo ang silangan sa kanluran, gayon kalayo Niyang inilalayo sa atin ang ating mga pagsuway\" (Awit 103:8-12). Sa Mateo 18:21-35, nag-alok si Pedro na magpatawad nang pitong beses; sumagot si Hesus sa kuwento ng aliping pinatawad sa utang na hindi niya kailanman kayang bayaran, pero sinakal naman ang kapwa alipin dahil sa maliit na halaga. Matalas ang hatol ng amo: \"Hindi ba dapat naawa ka rin... gaya ng pagkaawa ko sa iyo?\" Ginawa itong utos ni Pablo: \"Maging mabait kayo sa isa't isa, mahabagin, nagpapatawaran, gaya ng pagpapatawad sa inyo ng Diyos kay Kristo\" (Efeso 4:31-32). Ang mga pinatawad ay tinatawag na maging mapagpatawad."
    ),
    insight: [
      t(
        "We usually think the problem with the unforgiving servant was that he was mean. Jesus shows a deeper problem: he never really let the master's mercy sink in. He walked out of the palace forgiven of millions and still thinking like a debtor who had to collect from everyone. When we cannot forgive, it often means we are still living as if we must protect ourselves, because we have not fully tasted how much we have been forgiven.",
        "Karaniwang iniisip natin na ang problema ng aliping hindi nagpatawad ay masama lang ang ugali niya. Mas malalim ang ipinakita ni Hesus: hindi niya talaga hinayaang tumagos sa puso niya ang awa ng amo. Lumabas siya ng palasyo na pinatawad sa milyun-milyon pero nag-iisip pa ring parang may utang na kailangang maningil sa lahat. Kapag hindi tayo makapagpatawad, madalas ay namumuhay pa rin tayo na parang kailangan nating ipagtanggol ang sarili, dahil hindi pa natin lubos na nalalasap kung gaano kalaki ang ipinatawad sa atin."
      ),
      t(
        "Forgiveness is also widely misunderstood. It is not saying the wrong was okay, it is not pretending you were not hurt, and it does not always mean trust is restored immediately. It means cancelling the debt: you stop demanding that the person pay, and you hand the case to the righteous Judge. Paul lists bitterness, wrath and slander first (Ephesians 4:31) because unforgiveness does not stay quiet; it leaks into the tongue and the home.",
        "Malawak din ang maling pagkakaunawa sa pagpapatawad. Hindi ito pagsasabing ayos lang ang mali, hindi ito pagkukunwaring hindi ka nasaktan, at hindi laging nangangahulugang babalik agad ang tiwala. Ito ay pagkansela ng utang: tumitigil kang humingi na magbayad ang tao, at ipinauubaya mo ang kaso sa matuwid na Hukom. Inuna ni Pablo ang sama ng loob, poot at paninirang-puri (Efeso 4:31) dahil ang hindi pagpapatawad ay hindi nananatiling tahimik; tumatagas ito sa dila at sa tahanan."
      ),
    ],
    life: [
      t(
        "Think of a sari-sari store owner with a notebook of \"lista\" debts. Every time she opens it, she remembers who owes her and feels the irritation again. Unforgiveness is a mental lista: we keep the record open and reread it at night. Forgiveness is taking a pen and writing \"bayad na\" across the page, not because they paid, but because Christ paid for you.",
        "Isipin ang may-ari ng sari-sari store na may kuwaderno ng mga utang na \"lista.\" Tuwing bubuksan niya ito, naaalala niya kung sino ang may utang at naiinis na naman siya. Ang hindi pagpapatawad ay isang listang nasa isip: bukas pa rin ang talaan at binabasa natin ulit tuwing gabi. Ang pagpapatawad ay ang pagkuha ng ballpen at pagsulat ng \"bayad na\" sa pahina, hindi dahil nakabayad sila, kundi dahil binayaran ni Kristo ang para sa iyo."
      ),
      t(
        "An OFW worked six years abroad and sent money home for a house, only to find that a relative had spent most of it. For two years she could not say his name without shaking. In a Bible study she finally prayed, \"Lord, I release him to You. I want my peace back.\" The money did not return, and she set wiser boundaries, but the bitterness that had been stealing her sleep began to leave. Forgiveness set the prisoner free, and she discovered the prisoner was herself.",
        "Anim na taong nagtrabaho sa abroad ang isang OFW at nagpadala ng pera pauwi para sa bahay, pero nalaman niyang ginastos ng isang kamag-anak ang karamihan nito. Dalawang taon siyang hindi makabanggit ng pangalan nito nang hindi nanginginig. Sa isang Bible study, sa wakas ay nanalangin siya, \"Panginoon, ipinauubaya ko siya sa Iyo. Gusto kong bumalik ang kapayapaan ko.\" Hindi bumalik ang pera, at naglagay siya ng mas matalinong hangganan, pero ang sama ng loob na nagnanakaw ng tulog niya ay unti-unting umalis. Pinalaya ng pagpapatawad ang bilanggo, at natuklasan niyang siya pala ang bilanggong iyon."
      ),
    ],
    twist: t(
      "Peter thought seven times was generous. Jesus said seventy-seven (or seventy times seven). He was not giving a bigger number to count; He was abolishing counting. The moment you are keeping score, you are no longer forgiving. And notice who is the hero of the parable: not the forgiven servant, but the king who absorbed the loss. Forgiveness always costs the one who forgives. That is exactly what God did at the cross: He absorbed the loss of our debt Himself.",
      "Akala ni Pedro, mapagbigay na ang pitong beses. Sabi ni Hesus, pitumpu't pito (o pitumpung ulit na pito). Hindi Siya nagbigay ng mas malaking bilang na bibilangin; inalis Niya ang pagbibilang. Sa sandaling nagbibilang ka, hindi ka na nagpapatawad. At pansinin kung sino ang bida sa talinghaga: hindi ang aliping pinatawad, kundi ang haring sumalo sa pagkalugi. Laging may halaga ang pagpapatawad para sa nagpapatawad. Iyan mismo ang ginawa ng Diyos sa krus: Siya mismo ang sumalo sa pagkalugi ng ating utang."
    ),
    confirm: [
      t("Genesis 50:19-21: Joseph tells his brothers, \"You meant evil, but God meant it for good.\"", "Genesis 50:19-21: sinabi ni Jose sa mga kapatid niya, \"Masama ang balak ninyo, pero ginawa itong mabuti ng Diyos.\""),
      t("Luke 23:34: from the cross Jesus prays, \"Father, forgive them.\"", "Lucas 23:34: mula sa krus nanalangin si Hesus, \"Ama, patawarin Mo sila.\""),
      t("Acts 7:60: Stephen, while being stoned, asks God not to hold the sin against them.", "Gawa 7:60: si Esteban, habang binabato, ay humiling sa Diyos na huwag ibilang sa kanila ang kasalanang iyon."),
      t("Colossians 3:13: as the Lord has forgiven you, so you also must forgive.", "Colosas 3:13: kung paanong pinatawad kayo ng Panginoon, gayon din kayo magpatawad."),
    ],
    heart: [
      t(
        "Let God's mercy to you become bigger in your eyes than the wrong done to you. Grudges shrink when grace grows.",
        "Hayaang lumaki sa paningin mo ang awa ng Diyos sa iyo nang higit sa kasalanang ginawa sa iyo. Lumiliit ang sama ng loob kapag lumalaki ang biyaya."
      ),
      t(
        "Choose tenderness over hardness. Forgiveness is often a decision you renew each time the memory returns, until the feelings follow.",
        "Piliin ang lambot ng puso kaysa katigasan. Ang pagpapatawad ay madalas na desisyong inuulit mo tuwing bumabalik ang alaala, hanggang sumunod ang damdamin."
      ),
    ],
    questions: [
      t("Whose name is still written in your mental lista of debts?", "Kaninong pangalan ang nakasulat pa rin sa lista ng utang sa isip mo?"),
      t("Do you find it harder to receive God's forgiveness or to give forgiveness to others? Why?", "Mas mahirap ba sa iyo ang tanggapin ang pagpapatawad ng Diyos o ang magpatawad sa iba? Bakit?"),
      t("Where is bitterness leaking out in your words or your home?", "Saan tumatagas ang sama ng loob sa mga salita mo o sa tahanan mo?"),
      t("What would it cost you to cancel that debt, and what is it costing you to keep it?", "Ano ang magiging kapalit kung kakanselahin mo ang utang na iyon, at ano ang nagiging kapalit ng pagpapanatili nito?"),
    ],
    actions: [
      t("Write the name of the person and the hurt on paper, pray over it, then write \"Paid by Jesus\" across it.", "Isulat sa papel ang pangalan ng tao at ang sakit, ipanalangin ito, tapos isulat sa ibabaw nito ang \"Binayaran na ni Hesus.\""),
      t("Pray a blessing over that person by name once a day this week, even if your feelings disagree.", "Ipanalangin ang pagpapala sa taong iyon sa kanyang pangalan isang beses bawat araw ngayong linggo, kahit hindi sang-ayon ang damdamin mo."),
      t("If you need help with reconciliation or boundaries, talk to your mentor or pastor this week.", "Kung kailangan mo ng tulong sa pakikipagkasundo o paglalagay ng hangganan, kausapin ang iyong mentor o pastor ngayong linggo."),
    ],
    prayer: t(
      "Merciful Father, You have removed my sins as far as the east is from the west. I owed You a debt I could never pay, and You cancelled it in Jesus. Forgive me for holding others to debts much smaller than mine. Today I release the people who hurt me into Your hands. Heal my heart, uproot all bitterness, and make me kind and tenderhearted, forgiving as I have been forgiven. In Jesus' name, Amen.",
      "Mahabaging Ama, inilayo Mo ang aking mga kasalanan kung gaano kalayo ang silangan sa kanluran. May utang ako sa Iyo na hindi ko kailanman kayang bayaran, at kinansela Mo ito kay Hesus. Patawarin Mo ako sa paniningil sa iba ng mga utang na mas maliit kaysa sa akin. Ngayon, ipinauubaya ko sa Iyong mga kamay ang mga taong nanakit sa akin. Pagalingin Mo ang aking puso, bunutin ang lahat ng sama ng loob, at gawin Mo akong mabait at mahabagin, nagpapatawad gaya ng pagpapatawad Mo sa akin. Sa pangalan ni Hesus, Amen."
    ),
  },

  "freedom-in-christ": {
    revelation: t(
      "Jesus did not merely give you extra protection; He defeated the powers you used to fear, so you no longer need any other source of safety or luck.",
      "Hindi lang dagdag na proteksyon ang ibinigay ni Hesus; tinalo Niya ang mga kapangyarihang dati mong kinatatakutan, kaya hindi mo na kailangan ng ibang mapagkukunan ng kaligtasan o suwerte."
    ),
    mainTruth: t(
      "At the cross God forgave all our trespasses, cancelled the record of debt against us, and \"disarmed the rulers and authorities and put them to open shame, by triumphing over them in Him\" (Colossians 2:13-15). That is why God forbids divination, sorcery, omens, charms and consulting the dead: they are \"an abomination to the Lord\" (Deuteronomy 18:10-13). In Ephesus, new believers came \"confessing and divulging their practices,\" and burned magic books worth fifty thousand pieces of silver, \"so the word of the Lord continued to increase and prevail mightily\" (Acts 19:18-20). Freedom comes by trusting Christ's victory and turning fully away from every rival power.",
      "Sa krus, pinatawad ng Diyos ang lahat ng ating pagsuway, kinansela ang talaan ng utang laban sa atin, at \"inalisan ng kapangyarihan ang mga pinuno at may kapamahalaan at hayagang inilantad sila sa kahihiyan, nagtagumpay sa kanila sa pamamagitan Niya\" (Colosas 2:13-15). Kaya ipinagbabawal ng Diyos ang panghuhula, pangkukulam, pamahiin sa mga palatandaan, anting-anting at pagsangguni sa patay: ang mga ito ay \"kasuklam-suklam sa Panginoon\" (Deuteronomio 18:10-13). Sa Efeso, ang mga bagong mananampalataya ay \"nagpahayag at nagsiwalat ng kanilang mga gawain,\" at sinunog ang mga aklat ng mahika na nagkakahalaga ng limampung libong pirasong pilak, \"kaya patuloy na lumaganap at lumakas ang salita ng Panginoon\" (Gawa 19:18-20). Dumarating ang kalayaan sa pagtitiwala sa tagumpay ni Kristo at ganap na pagtalikod sa bawat karibal na kapangyarihan."
    ),
    insight: [
      t(
        "Many Filipino believers would never visit a witch, but still keep \"just in case\" habits: a red string for the baby, an amulet in the wallet, consulting a horoscope, a feng shui charm for the business, a ritual before moving into a new house. We call them culture or harmless pamahiin. But the question is not \"Is this traditional?\" but \"Whom am I trusting for my safety?\" Anything we rely on besides Christ for protection or luck competes with Him for our heart.",
        "Maraming Pilipinong mananampalataya ang hindi kailanman pupunta sa mangkukulam, pero may mga gawi pa ring \"para sigurado\": pulang tali sa sanggol, anting-anting sa pitaka, pagbabasa ng horoscope, pampasuwerteng feng shui sa negosyo, ritwal bago lumipat sa bagong bahay. Tinatawag natin itong kultura o walang masamang pamahiin. Pero ang tanong ay hindi \"Tradisyon ba ito?\" kundi \"Kanino ako nagtitiwala para sa kaligtasan ko?\" Anumang inaasahan natin bukod kay Kristo para sa proteksyon o suwerte ay nakikipag-agawan sa Kanya sa ating puso."
      ),
      t(
        "Notice the order in Acts 19. These people had already believed (v. 18). Salvation came first, then a public, costly clean-up. Freedom is a gift received by faith, but it is walked out by confession and removal. Fifty thousand pieces of silver was a fortune; they did not sell the books, they burned them. Real repentance does not try to recover the investment from what God calls darkness.",
        "Pansinin ang pagkakasunod sa Gawa 19. Nanampalataya na ang mga taong ito (t. 18). Nauna ang kaligtasan, saka sumunod ang hayagan at magastos na paglilinis. Ang kalayaan ay regalong tinatanggap sa pananampalataya, pero isinasabuhay ito sa pamamagitan ng pagpapahayag at pag-aalis. Napakalaking halaga ang limampung libong pirasong pilak; hindi nila ibinenta ang mga aklat, sinunog nila. Ang tunay na pagsisisi ay hindi sinusubukang bawiin ang puhunan mula sa itinuturing ng Diyos na kadiliman."
      ),
    ],
    life: [
      t(
        "A family in the province consulted an albularyo whenever a child got sick, and the mother wore an amulet passed down from her grandmother. When she came to Christ, she felt uneasy but afraid to throw it away: \"What if something bad happens?\" Her pastor prayed with her, she confessed and renounced it, and they burned it together. She said later, \"For the first time, I was not afraid of the dark. I knew whose I was.\"",
        "May isang pamilya sa probinsya na kumukonsulta sa albularyo tuwing may anak na nagkakasakit, at ang nanay ay may suot na anting-anting na minana pa sa kanyang lola. Nang lumapit siya kay Kristo, nabagabag siya pero takot itapon ito: \"Paano kung may mangyaring masama?\" Ipinanalangin siya ng pastor niya, ipinahayag at tinalikuran niya ito, at sabay nilang sinunog. Sabi niya kalaunan, \"Unang beses na hindi ako natakot sa dilim. Alam ko na kung kanino ako.\""
      ),
      t(
        "Abroad, fear finds new forms: a coworker offers a \"lucky\" bracelet before your visa interview, or someone suggests a fortune teller to know if your contract will be renewed. When anxiety is high, shortcuts to certainty look attractive. But a believer does not need to know the future through forbidden means; he knows the One who holds the future. Take the anxiety to prayer, not to the hula.",
        "Sa abroad, may bagong anyo ang takot: may katrabahong nag-aalok ng \"suwerteng\" pulseras bago ang visa interview mo, o may nagmumungkahi ng manghuhula para malaman kung mare-renew ang kontrata mo. Kapag mataas ang pag-aalala, kaakit-akit ang mga shortcut sa katiyakan. Pero ang mananampalataya ay hindi kailangang malaman ang hinaharap sa pamamagitan ng ipinagbabawal na paraan; kilala niya ang Humahawak sa hinaharap. Dalhin ang pag-aalala sa panalangin, hindi sa hula."
      ),
    ],
    twist: t(
      "Colossians 2:15 uses the picture of a Roman triumph: a victorious general parading defeated enemies through the streets, disarmed and humiliated. The surprise is where this triumph happened: at the cross, the place that looked like Jesus' greatest defeat. The powers thought they were shaming Him; He was shaming them. So a believer does not fight FOR victory over darkness; he stands IN a victory already won. The enemy's only remaining weapon is a lie, and he loses the moment you believe the truth.",
      "Gumagamit ang Colosas 2:15 ng larawan ng Romanong pagdiriwang ng tagumpay: isang heneral na nagpaparada ng mga natalong kaaway sa mga lansangan, wala nang sandata at nakakahiya. Ang sorpresa ay kung saan nangyari ang tagumpay na ito: sa krus, ang lugar na mukhang pinakamalaking pagkatalo ni Hesus. Akala ng mga kapangyarihan, sila ang nagpapahiya sa Kanya; Siya pala ang nagpapahiya sa kanila. Kaya ang mananampalataya ay hindi nakikipaglaban PARA sa tagumpay laban sa kadiliman; nakatayo siya SA tagumpay na napanalunan na. Ang natitirang sandata ng kaaway ay kasinungalingan, at talo siya sa sandaling paniwalaan mo ang katotohanan."
    ),
    confirm: [
      t("1 John 3:8: the Son of God appeared to destroy the works of the devil.", "1 Juan 3:8: nahayag ang Anak ng Diyos upang wasakin ang mga gawa ng diyablo."),
      t("Genesis 35:2-4: Jacob's household buries their foreign gods before going up to Bethel.", "Genesis 35:2-4: ibinaon ng sambahayan ni Jacob ang kanilang mga diyus-diyosan bago umakyat sa Bethel."),
      t("Acts 16:16-18: Paul casts out a spirit of divination in Jesus' name.", "Gawa 16:16-18: pinalayas ni Pablo ang espiritu ng panghuhula sa pangalan ni Hesus."),
      t("Psalm 91:1-2: the one who dwells in the shelter of the Most High says, \"My refuge and my fortress.\"", "Awit 91:1-2: ang nananahan sa kanlungan ng Kataas-taasan ay nagsasabing, \"Kanlungan ko at tanggulan ko.\""),
    ],
    heart: [
      t(
        "Move from fear to faith. You do not need to be anxious about curses, spirits or bad luck when you belong to the One who conquered them.",
        "Lumipat mula sa takot tungo sa pananampalataya. Hindi mo kailangang mabahala sa sumpa, espiritu o malas kung pag-aari ka ng Isang tumalo sa kanila."
      ),
      t(
        "Choose wholehearted loyalty. Let Jesus be your only protection, your only guide to the future, your only source of blessing.",
        "Piliin ang buong-pusong katapatan. Hayaang si Hesus ang maging tanging proteksyon mo, tanging gabay sa hinaharap, at tanging pinagmumulan ng pagpapala."
      ),
    ],
    questions: [
      t("Have you or your family used hula, anting-anting, albularyo rituals or horoscopes? Which ones?", "Ikaw ba o ang pamilya mo ay gumamit ng hula, anting-anting, ritwal ng albularyo o horoscope? Alin sa mga ito?"),
      t("Are there objects in your home, bag or car that you keep \"just in case\"?", "May mga bagay ba sa bahay, bag o sasakyan mo na itinatago mo \"para sigurado\"?"),
      t("When you are afraid of the future, where does your heart run first?", "Kapag natatakot ka sa hinaharap, saan unang tumatakbo ang puso mo?"),
      t("What does it mean for your daily fears that Jesus has already triumphed?", "Ano ang kahulugan para sa araw-araw mong takot na nagtagumpay na si Hesus?"),
    ],
    actions: [
      t("Ask the Holy Spirit to show you any practice or object to renounce. Write each one down.", "Hilingin sa Banal na Espiritu na ipakita sa iyo ang anumang gawain o bagay na dapat talikuran. Isulat ang bawat isa."),
      t("With your pastor or mentor, confess and renounce each one by name, then remove and destroy any objects.", "Kasama ang iyong pastor o mentor, ipahayag at talikuran ang bawat isa sa pangalan nito, tapos alisin at sirain ang anumang bagay."),
      t("Memorize Colossians 2:15 and declare it aloud whenever fear returns.", "Isaulo ang Colosas 2:15 at ipahayag ito nang malakas tuwing bumabalik ang takot."),
    ],
    prayer: t(
      "Lord Jesus, thank You that at the cross You disarmed every power of darkness and triumphed over them. I confess every practice, charm and ritual I or my family trusted instead of You, and I renounce them all in Your name. I belong to You alone. Be my only refuge, my only guide and my only security. Fill every place in my life with Your light, and let Your word grow mightily in me and in my home. Amen.",
      "Panginoong Hesus, salamat dahil sa krus ay inalisan Mo ng kapangyarihan ang bawat puwersa ng kadiliman at nagtagumpay Ka laban sa kanila. Ipinapahayag ko ang bawat gawain, anting-anting at ritwal na pinagtiwalaan ko o ng pamilya ko sa halip na Ikaw, at tinatalikuran ko ang lahat ng ito sa Iyong pangalan. Sa Iyo lamang ako. Ikaw ang aking tanging kanlungan, tanging gabay at tanging kapanatagan. Punuin Mo ng Iyong liwanag ang bawat bahagi ng buhay ko, at hayaang lumago nang makapangyarihan ang Iyong salita sa akin at sa aking tahanan. Amen."
    ),
  },

  "new-family-in-christ": {
    revelation: t(
      "Your family history explains you, but it does not have to define you; in Christ, a new story can begin with you.",
      "Ipinaliliwanag ng kasaysayan ng pamilya mo kung bakit ka ganyan, pero hindi nito kailangang itakda kung sino ka; kay Kristo, maaaring magsimula sa iyo ang bagong kuwento."
    ),
    mainTruth: t(
      "\"If anyone is in Christ, he is a new creation. The old has passed away; behold, the new has come\" (2 Corinthians 5:17). Christ \"redeemed us from the curse of the law by becoming a curse for us,\" so that the blessing of Abraham might come to us and we might receive the promised Spirit (Galatians 3:13-14). Long before, God corrected Israel's saying that children are doomed by their parents' sins: \"The son shall not suffer for the iniquity of the father... the righteousness of the righteous shall be upon himself\" (Ezekiel 18:19-20). You are not chained to your family's past. In Christ you receive a new nature, a new Father and a new inheritance.",
      "\"Kung ang sinuman ay nakay Kristo, siya ay bagong nilalang. Lumipas na ang dati; narito, dumating na ang bago\" (2 Corinto 5:17). Si Kristo ay \"tumubos sa atin mula sa sumpa ng kautusan sa pamamagitan ng pagiging sumpa para sa atin,\" upang ang pagpapala kay Abraham ay dumating sa atin at matanggap natin ang ipinangakong Espiritu (Galacia 3:13-14). Matagal na bago iyon, itinuwid ng Diyos ang kasabihan ng Israel na ang mga anak ay tiyak na mapapahamak dahil sa kasalanan ng magulang: \"Ang anak ay hindi magdurusa dahil sa kasamaan ng ama... ang katuwiran ng matuwid ay sa kanya\" (Ezekiel 18:19-20). Hindi ka nakakadena sa nakaraan ng pamilya mo. Kay Kristo, tumatanggap ka ng bagong kalikasan, bagong Ama at bagong mana."
    ),
    insight: [
      t(
        "Many believers accept forgiveness for their own sins but quietly accept their family patterns as fate: \"Talagang mainitin ang ulo ng angkan namin.\" \"All the men in our family drink.\" \"Our family is always poor.\" They say it as a joke, but they live it as a prophecy. Ezekiel 18 confronts that fatalism. God holds each person responsible and offers each person a fresh start.",
        "Maraming mananampalataya ang tumatanggap ng kapatawaran sa sariling kasalanan pero tahimik na tinatanggap ang mga pattern ng pamilya bilang kapalaran: \"Talagang mainitin ang ulo ng angkan namin.\" \"Lahat ng lalaki sa pamilya namin, umiinom.\" \"Lagi kaming mahirap.\" Biro ang tunog, pero ipinamumuhay na parang propesiya. Hinaharap ng Ezekiel 18 ang ganitong pananaw na wala nang magagawa. Pinananagot ng Diyos ang bawat tao at nag-aalok sa bawat isa ng panibagong simula."
      ),
      t(
        "At the same time, being a new creation is not pretending the past did not happen. Patterns learned over years are often unlearned over time, with the Word, the Spirit and the help of the church. The new birth is instant; the new habits are trained. Do not be discouraged if old reactions show up; they are not your identity anymore, only leftovers you are learning to throw out.",
        "Kasabay nito, ang pagiging bagong nilalang ay hindi pagkukunwaring hindi nangyari ang nakaraan. Ang mga pattern na natutunan sa loob ng maraming taon ay madalas na inaalis din sa paglipas ng panahon, sa tulong ng Salita, ng Espiritu at ng iglesya. Ang bagong kapanganakan ay biglaan; ang bagong gawi ay sinasanay. Huwag panghinaan ng loob kung lumilitaw pa ang lumang reaksyon; hindi na iyon ang pagkakakilanlan mo, mga tira na lang na natututunan mong itapon."
      ),
    ],
    life: [
      t(
        "A father grew up with a dad who shouted and hit when drunk. He swore he would never be like that, but by his thirties he found himself yelling at his own kids. When he came to Christ, he wept: \"I thought this was just who we are.\" With a men's group, he learned to walk away and pray when anger rose, to apologize to his children, and to bless them at night. His son will grow up with a different story to tell.",
        "May isang ama na lumaki sa tatay na sumisigaw at nananakit kapag lasing. Nangako siyang hinding-hindi siya magiging ganoon, pero pagdating ng trenta, nakita niya ang sariling sinisigawan ang mga anak. Nang lumapit siya kay Kristo, umiyak siya: \"Akala ko ganito lang talaga kami.\" Kasama ang isang grupo ng kalalakihan, natutunan niyang lumayo at manalangin kapag umaakyat ang galit, humingi ng tawad sa mga anak, at basbasan sila tuwing gabi. Iba na ang kuwentong ikukuwento ng anak niya paglaki."
      ),
      t(
        "Many OFWs are the first in their family to break a cycle: the first to finish school, the first to own a house, the first to follow Jesus. That role is heavy, but it is holy. You may be the \"Abraham\" of your clan, the one through whom God starts a line of blessing that your grandchildren will thank Him for.",
        "Maraming OFW ang unang pumutol ng siklo sa kanilang pamilya: unang nakatapos ng pag-aaral, unang nagkabahay, unang sumunod kay Hesus. Mabigat ang papel na iyan, pero banal. Maaaring ikaw ang \"Abraham\" ng angkan ninyo, ang taong sa pamamagitan niya sisimulan ng Diyos ang lahi ng pagpapala na pasasalamatan Niya ng iyong mga apo."
      ),
    ],
    twist: t(
      "We often think breaking a family curse requires a dramatic ritual. Galatians 3:13 says the decisive act already happened: Christ BECAME the curse on the tree. The cross is where every inherited curse came to die. And here is the deeper surprise: the goal is not only to stop the bad inheritance but to receive a good one, \"the blessing of Abraham\" and the Spirit. God does not just end your old family story; He writes you into His family's story.",
      "Madalas iniisip natin na kailangan ng madramang ritwal para putulin ang sumpa ng pamilya. Sabi ng Galacia 3:13, nangyari na ang mapagpasyang gawa: si Kristo ay NAGING sumpa sa puno. Ang krus ang lugar kung saan namatay ang bawat minanang sumpa. At heto ang mas malalim na sorpresa: ang layunin ay hindi lang pigilan ang masamang mana kundi tanggapin ang mabuting mana, \"ang pagpapala kay Abraham\" at ang Espiritu. Hindi lang tinatapos ng Diyos ang lumang kuwento ng pamilya mo; isinusulat ka Niya sa kuwento ng Kanyang pamilya."
    ),
    confirm: [
      t("2 Kings 22:1-2: Josiah, son of wicked Amon, did what was right in God's eyes.", "2 Hari 22:1-2: si Josias, anak ng masamang si Amon, ay gumawa ng matuwid sa paningin ng Diyos."),
      t("Ruth 1:16: a Moabite woman chooses a new people and a new God, and enters Jesus' family line.", "Ruth 1:16: isang Moabita ang pumili ng bagong bayan at bagong Diyos, at napabilang sa angkan ni Hesus."),
      t("John 1:12-13: those who receive Him are born not of blood but of God.", "Juan 1:12-13: ang mga tumatanggap sa Kanya ay ipinanganak hindi sa dugo kundi sa Diyos."),
      t("Mark 3:34-35: whoever does God's will is Jesus' brother, sister and mother.", "Marcos 3:34-35: ang sinumang gumagawa ng kalooban ng Diyos ay kapatid at ina ni Hesus."),
    ],
    heart: [
      t(
        "Replace fatalism with hope. Stop saying \"this is just how we are\" and start saying \"this is who I am becoming in Christ.\"",
        "Palitan ng pag-asa ang pananaw na wala nang magagawa. Tumigil sa pagsasabing \"ganito lang talaga kami\" at magsimulang magsabing \"ito ang nagiging ako kay Kristo.\""
      ),
      t(
        "Honor your parents without carrying their sins. Thank God for the good, release the bad, and choose a new direction with gentleness, not contempt.",
        "Igalang ang mga magulang nang hindi binubuhat ang kanilang kasalanan. Pasalamatan ang Diyos sa mabuti, bitawan ang masama, at pumili ng bagong direksyon nang may kahinahunan, hindi pagmamaliit."
      ),
    ],
    questions: [
      t("Which family patterns do you see repeating in your own life?", "Aling mga pattern ng pamilya ang nakikita mong umuulit sa sarili mong buhay?"),
      t("What phrase like \"ganito talaga kami\" have you been speaking over yourself?", "Anong pananalitang tulad ng \"ganito talaga kami\" ang sinasabi mo tungkol sa sarili mo?"),
      t("What good things from your family do you want to keep and pass on?", "Anong mabubuting bagay mula sa pamilya mo ang gusto mong panatilihin at ipasa?"),
      t("What would a godly heritage look like for your children or nieces and nephews?", "Ano ang hitsura ng maka-Diyos na pamana para sa iyong mga anak o pamangkin?"),
    ],
    actions: [
      t("Write two lists: patterns to end and blessings to keep. Pray over both, thanking God and renouncing the bad.", "Gumawa ng dalawang listahan: mga pattern na tatapusin at mga pagpapalang pananatilihin. Ipanalangin ang dalawa, nagpapasalamat sa Diyos at tinatalikuran ang masama."),
      t("Choose one new habit that breaks a pattern (e.g. a calm word instead of shouting) and practice it this week.", "Pumili ng isang bagong gawi na pumuputol sa pattern (hal. mahinahong salita sa halip na sigaw) at isabuhay ito ngayong linggo."),
      t("Pray for one family member by name every day and do one kind act for them.", "Ipanalangin ang isang kapamilya sa kanyang pangalan araw-araw at gumawa ng isang kabutihan para sa kanya."),
    ],
    prayer: t(
      "Father, thank You for my family and for every good thing I received through them. Thank You that in Christ I am a new creation, and that Jesus became a curse so I could receive Your blessing. I renounce every ungodly pattern in my family line and declare that it ends with me. Teach me new ways by Your Spirit. Make me the beginning of a godly heritage for the generations after me. In Jesus' name, Amen.",
      "Ama, salamat sa aking pamilya at sa bawat mabuting bagay na tinanggap ko sa pamamagitan nila. Salamat dahil kay Kristo ako ay bagong nilalang, at naging sumpa si Hesus upang matanggap ko ang Iyong pagpapala. Tinatalikuran ko ang bawat hindi maka-Diyos na pattern sa aming angkan at ipinapahayag kong matatapos ito sa akin. Turuan Mo ako ng bagong mga daan sa pamamagitan ng Iyong Espiritu. Gawin Mo akong simula ng maka-Diyos na pamana para sa mga susunod na henerasyon. Sa pangalan ni Hesus, Amen."
    ),
  },

  "trusting-the-bible": {
    revelation: t(
      "The Bible is not a book you judge; it is the living word of God that judges, heals and guides you, and it will still be standing when everything else has faded.",
      "Ang Bibliya ay hindi aklat na hinuhusgahan mo; ito ang buhay na salita ng Diyos na humahatol, nagpapagaling at gumagabay sa iyo, at nakatayo pa rin ito kapag naglaho na ang lahat ng iba pa."
    ),
    mainTruth: t(
      "Peter, an eyewitness of Jesus' glory, says we have something even more sure: \"the prophetic word,\" like a lamp shining in a dark place. \"No prophecy was ever produced by the will of man, but men spoke from God as they were carried along by the Holy Spirit\" (2 Peter 1:19-21). Psalm 19 says God's law is perfect, reviving the soul; His testimony is sure, making wise the simple; His words are more desirable than gold and sweeter than honey (Psalm 19:7-11). And Isaiah declares, \"The grass withers, the flower fades, but the word of our God will stand forever\" (Isaiah 40:8). Scripture is trustworthy because its true Author is trustworthy.",
      "Si Pedro, saksi sa kaluwalhatian ni Hesus, ay nagsabing may mas tiyak pa tayo: \"ang salita ng propesiya,\" gaya ng ilawang nagliliwanag sa madilim na lugar. \"Walang propesiyang nagmula sa kalooban ng tao, kundi nagsalita ang mga tao mula sa Diyos habang sila ay kinikilos ng Banal na Espiritu\" (2 Pedro 1:19-21). Sabi ng Awit 19, ang kautusan ng Diyos ay ganap, nagpapanumbalik ng kaluluwa; ang Kanyang patotoo ay tiyak, nagpapadunong sa simple; ang Kanyang mga salita ay mas kanais-nais kaysa ginto at mas matamis kaysa pulot (Awit 19:7-11). At ipinahayag ni Isaias, \"Natutuyo ang damo, nalalanta ang bulaklak, ngunit ang salita ng ating Diyos ay mananatili magpakailanman\" (Isaias 40:8). Mapagkakatiwalaan ang Kasulatan dahil mapagkakatiwalaan ang tunay nitong May-akda."
    ),
    insight: [
      t(
        "Many believers defend the Bible but do not depend on it. They would argue that it is God's word, yet they make decisions based on feelings, viral posts and advice from friends, and open Scripture only on Sundays. The real test of whether you trust the Bible is not what you say about it in a debate but whether you obey it when it disagrees with you.",
        "Maraming mananampalataya ang nagtatanggol sa Bibliya pero hindi umaasa rito. Ipaglalaban nilang salita ito ng Diyos, pero nagpapasya sila batay sa damdamin, viral na post at payo ng kaibigan, at binubuksan lang ang Kasulatan tuwing Linggo. Ang tunay na pagsubok kung nagtitiwala ka sa Bibliya ay hindi kung ano ang sinasabi mo tungkol dito sa debate, kundi kung sinusunod mo ito kapag salungat ito sa gusto mo."
      ),
      t(
        "Peter's point is striking. He had seen Jesus transfigured and heard the Father's voice on the mountain, yet he pointed his readers to the written word as a lamp they must pay attention to. Experiences are precious, but they fade and can be misread. The Scripture stays the same and tests every experience. God's word is not less than a vision; it is the standard for every vision.",
        "Kapansin-pansin ang punto ni Pedro. Nakita niya si Hesus na nagbagong-anyo at narinig ang tinig ng Ama sa bundok, pero itinuro pa rin niya ang kanyang mga mambabasa sa nakasulat na salita bilang ilawang dapat nilang pakinggan. Mahalaga ang mga karanasan, pero kumukupas at maaaring mali ang pagkaintindi. Ang Kasulatan ay nananatiling pareho at sinusuri nito ang bawat karanasan. Ang salita ng Diyos ay hindi mas mababa sa pangitain; ito ang pamantayan ng bawat pangitain."
      ),
    ],
    life: [
      t(
        "A seafarer said that in the middle of the ocean at night, the crew does not steer by how the waves feel; they steer by the instruments and the charts. Feelings on a dark sea can kill you. In the same way, when life is stormy, our emotions will tell us many things: God has left you, you are worthless, just give up. The Bible is our chart. It does not change with the waves.",
        "Sabi ng isang seaman, sa gitna ng karagatan sa gabi, hindi umaasa ang crew sa pakiramdam ng alon; umaasa sila sa instrumento at mapa. Ang pakiramdam sa madilim na dagat ay maaaring ikamatay mo. Ganoon din, kapag mabagyo ang buhay, maraming sasabihin ang damdamin natin: iniwan ka na ng Diyos, wala kang halaga, sumuko ka na lang. Ang Bibliya ang ating mapa. Hindi ito nagbabago kasabay ng alon."
      ),
      t(
        "Think of the fake news that floods our phones: shocking claims, miracle cures, quick-rich schemes, all shared by people we love. Many get fooled because they have no standard to measure truth. A believer who knows Scripture well develops a kind of spiritual \"fact-check.\" The Word trains you to recognize lies, not only on the internet but in your own heart.",
        "Isipin ang fake news na bumabaha sa ating mga cellphone: nakagugulat na balita, himalang lunas, mabilisang pagyaman, lahat ibinabahagi ng mga mahal natin sa buhay. Marami ang naloloko dahil wala silang pamantayan para sukatin ang katotohanan. Ang mananampalatayang kilala ang Kasulatan ay nagkakaroon ng espirituwal na \"fact-check.\" Sinasanay ka ng Salita na makilala ang kasinungalingan, hindi lang sa internet kundi pati sa sarili mong puso."
      ),
    ],
    twist: t(
      "We often ask, \"Can I trust the Bible?\" as if we are the judge and the Bible is on trial. Psalm 19 turns that around. The more you live under God's word, the more it proves itself: it revives the soul, gives wisdom, rejoices the heart, enlightens the eyes. Trust in Scripture grows not only by arguments but by obedience. Like honey, you cannot fully know it is sweet until you taste it. Open it, obey it, and it will vindicate itself in your life.",
      "Madalas nating itanong, \"Mapagkakatiwalaan ko ba ang Bibliya?\" na para bang tayo ang hukom at ang Bibliya ang nililitis. Binaliktad iyan ng Awit 19. Habang mas nabubuhay ka sa ilalim ng salita ng Diyos, mas pinatutunayan nito ang sarili: pinanunumbalik ang kaluluwa, nagbibigay ng karunungan, nagpapagalak sa puso, nagbibigay-liwanag sa mata. Lumalago ang tiwala sa Kasulatan hindi lang sa mga argumento kundi sa pagsunod. Gaya ng pulot, hindi mo lubos na malalaman na matamis ito hangga't hindi mo natitikman. Buksan mo, sundin mo, at patutunayan nito ang sarili sa buhay mo."
    ),
    confirm: [
      t("2 Timothy 3:16-17: all Scripture is breathed out by God and equips us for every good work.", "2 Timoteo 3:16-17: ang lahat ng Kasulatan ay hiningahan ng Diyos at nagsasangkap sa atin para sa bawat mabuting gawa."),
      t("Matthew 4:4: Jesus defeats temptation with \"It is written.\"", "Mateo 4:4: tinalo ni Hesus ang tukso sa pamamagitan ng \"Nasusulat.\""),
      t("Matthew 5:18: not one dot will pass from the law until all is accomplished.", "Mateo 5:18: wala kahit isang tuldok ang mawawala sa kautusan hanggang matupad ang lahat."),
      t("Acts 17:11: the Bereans examined the Scriptures daily to see if these things were so.", "Gawa 17:11: sinuri ng mga taga-Berea ang Kasulatan araw-araw upang malaman kung totoo ang mga ito."),
    ],
    heart: [
      t(
        "Move from admiring the Bible to submitting to it. Let God's word have the final say, even over your feelings and plans.",
        "Lumipat mula sa paghanga sa Bibliya tungo sa pagpapasakop dito. Hayaang ang salita ng Diyos ang may huling salita, kahit sa damdamin at plano mo."
      ),
      t(
        "Develop a hunger for Scripture. Treat it as gold to treasure and honey to enjoy, not medicine to swallow quickly.",
        "Magkaroon ng gutom sa Kasulatan. Ituring itong gintong iniingatan at pulot na tinatamasa, hindi gamot na mabilisang nilulunok."
      ),
    ],
    questions: [
      t("When the Bible disagrees with what you want, which usually wins?", "Kapag salungat ang Bibliya sa gusto mo, alin ang karaniwang nananalo?"),
      t("Do you read Scripture more as a duty or as food for your soul?", "Mas binabasa mo ba ang Kasulatan bilang obligasyon o bilang pagkain ng kaluluwa mo?"),
      t("What voices (social media, friends, feelings) shape your decisions more than God's word?", "Anong mga tinig (social media, kaibigan, damdamin) ang mas humuhubog sa mga desisyon mo kaysa sa salita ng Diyos?"),
      t("When has a verse proved itself true in your life?", "Kailan napatunayang totoo ang isang talata sa buhay mo?"),
    ],
    actions: [
      t("Set a daily time and place for reading the Bible, even 15 minutes, and protect it this week.", "Magtakda ng oras at lugar araw-araw para magbasa ng Bibliya, kahit 15 minuto, at ingatan ito ngayong linggo."),
      t("Read Psalm 19 slowly and list everything God's word does for us. Thank God for each one.", "Basahin nang dahan-dahan ang Awit 19 at ilista ang lahat ng ginagawa ng salita ng Diyos para sa atin. Pasalamatan ang Diyos sa bawat isa."),
      t("Choose one clear command you read this week and obey it before the week ends.", "Pumili ng isang malinaw na utos na nabasa mo ngayong linggo at sundin ito bago matapos ang linggo."),
    ],
    prayer: t(
      "Lord, Your word is perfect, sure, right and pure. The grass withers and the flower fades, but Your word stands forever. Forgive me for treating it lightly and for trusting other voices more than Yours. Give me a hunger for Scripture, eyes to understand it and a heart to obey it. Let it be a lamp in my dark places and the final word over my life. In Jesus' name, Amen.",
      "Panginoon, ang Iyong salita ay ganap, tiyak, matuwid at dalisay. Natutuyo ang damo at nalalanta ang bulaklak, pero ang salita Mo ay mananatili magpakailanman. Patawarin Mo ako sa pagbabalewala rito at sa mas pagtitiwala sa ibang tinig kaysa sa Iyo. Bigyan Mo ako ng gutom sa Kasulatan, mga matang nakauunawa at pusong sumusunod. Maging ilawan nawa ito sa mga madilim kong lugar at ang huling salita sa aking buhay. Sa pangalan ni Hesus, Amen."
    ),
  },

  "god-the-creator": {
    revelation: t(
      "You are not an accident in a random universe; you were made on purpose by a good Creator, in His image, for Him.",
      "Hindi ka aksidente sa isang sansinukob na nagkataon lang; sinadya kang likhain ng mabuting Manlilikha, ayon sa Kanyang larawan, para sa Kanya."
    ),
    mainTruth: t(
      "The Bible's first sentence settles the deepest question: \"In the beginning, God created the heavens and the earth\" (Genesis 1:1). Then God makes humanity \"in His own image,\" male and female, blesses them, gives them work and care over creation, and looks at everything He made: \"it was very good\" (Genesis 1:26-31). David looks at the night sky and asks, \"What is man that You are mindful of him?\" and answers that God made us \"a little lower than the heavenly beings\" and crowned us with glory and honor (Psalm 8:1-9). God is the Creator; everything belongs to Him, and every human carries His image and dignity.",
      "Sinasagot ng unang pangungusap ng Bibliya ang pinakamalalim na tanong: \"Nang pasimula, nilikha ng Diyos ang langit at ang lupa\" (Genesis 1:1). Pagkatapos, nilikha ng Diyos ang tao \"ayon sa Kanyang larawan,\" lalaki at babae, pinagpala sila, binigyan ng gawain at pangangalaga sa nilikha, at tiningnan ang lahat ng ginawa Niya: \"napakabuti\" (Genesis 1:26-31). Tumingala si David sa langit sa gabi at nagtanong, \"Ano ang tao upang alalahanin Mo siya?\" at sumagot na ginawa tayo ng Diyos \"na halos kapantay ng mga nilalang sa langit\" at pinutungan ng kaluwalhatian at karangalan (Awit 8:1-9). Ang Diyos ang Manlilikha; Kanya ang lahat, at bawat tao ay may dalang larawan at dangal Niya."
    ),
    insight: [
      t(
        "Many believers confess God as Creator but live as if they own their lives. If God made it, God owns it: your body, your time, your talents, your money, even the earth you walk on. The doctrine of creation is not only about the past; it is a claim of ownership over the present. We are stewards, not owners.",
        "Maraming mananampalataya ang nagpapahayag na ang Diyos ang Manlilikha pero namumuhay na parang sila ang may-ari ng buhay nila. Kung ang Diyos ang gumawa, ang Diyos ang may-ari: ang katawan mo, ang oras mo, ang talento mo, ang pera mo, pati ang lupang nilalakaran mo. Ang katuruan tungkol sa paglikha ay hindi lang tungkol sa nakaraan; ito ay pag-angkin ng pagmamay-ari sa kasalukuyan. Tayo ay katiwala, hindi may-ari."
      ),
      t(
        "We also overlook the dignity of others. If every person bears God's image, then the employer who mistreats a helper, the child who mocks a classmate, the online troll who insults strangers, all are attacking something God made sacred. And the believer who sees himself as \"walang kwenta\" is insulting God's handiwork too. The image of God sets the value of every human life, including yours.",
        "Nakaliligtaan din natin ang dangal ng iba. Kung bawat tao ay may larawan ng Diyos, ang amo na nagmamaltrato sa kasambahay, ang batang nanunukso ng kaklase, ang online troll na nang-iinsulto sa estranghero, lahat sila ay umaatake sa bagay na itinuring ng Diyos na banal. At ang mananampalatayang tumitingin sa sarili bilang \"walang kwenta\" ay nang-iinsulto rin sa gawa ng Diyos. Ang larawan ng Diyos ang nagtatakda ng halaga ng bawat buhay, kasama ang sa iyo."
      ),
    ],
    life: [
      t(
        "An OFW in Saudi Arabia, working in a hot construction site, once said he felt like \"just a pair of hands.\" One night in the desert he looked up at a sky full of stars and remembered Psalm 8. He realized the God who placed those stars also knew his name. He said, \"I went back to work the next day the same worker, but not the same man.\" Seeing God as Creator restored his sense of worth.",
        "May isang OFW sa Saudi Arabia na nagtatrabaho sa mainit na construction site na nagsabing pakiramdam niya ay \"isang pares lang ng kamay\" siya. Isang gabi sa disyerto, tumingala siya sa langit na puno ng bituin at naalala ang Awit 8. Naunawaan niya na ang Diyos na naglagay sa mga bituing iyon ay kilala rin ang pangalan niya. Sabi niya, \"Bumalik ako sa trabaho kinabukasan na parehong trabahador, pero hindi na parehong tao.\" Ang pagkakilala sa Diyos bilang Manlilikha ang nagbalik ng pakiramdam niya ng halaga."
      ),
      t(
        "Genesis 1 also gives work dignity. Before sin entered the world, God gave humans work to do: fill, subdue, rule, care. Your job as a cleaner, nurse, engineer, farmer or vendor is not a curse; it is part of reflecting the Creator who works. Do it with excellence, honesty and gratitude, as someone made in His image.",
        "Binibigyan din ng Genesis 1 ng dangal ang trabaho. Bago pa pumasok ang kasalanan sa mundo, binigyan na ng Diyos ng gawain ang tao: punuin, pamahalaan, pangalagaan. Ang trabaho mo bilang tagalinis, nars, inhinyero, magsasaka o tindero ay hindi sumpa; bahagi ito ng pagpapakita ng Manlilikhang gumagawa. Gawin ito nang mahusay, tapat at may pasasalamat, bilang taong nilikha ayon sa Kanyang larawan."
      ),
    ],
    twist: t(
      "Psalm 8 begins and ends with the same line: \"O Lord, our Lord, how majestic is Your name in all the earth!\" Humanity's glory is sandwiched inside God's glory. We are crowned, but the crown is borrowed. The more we understand our dignity, the more we should worship, not swell with pride. And surprisingly, Hebrews 2:6-9 applies Psalm 8 to Jesus: the true Man who perfectly bears God's image. To recover what it means to be human, look at Christ.",
      "Nagsisimula at nagtatapos ang Awit 8 sa parehong linya: \"O Panginoon, aming Panginoon, kay dakila ng Iyong pangalan sa buong lupa!\" Ang kaluwalhatian ng tao ay nakapaloob sa kaluwalhatian ng Diyos. May korona tayo, pero hiram ang korona. Habang mas nauunawaan natin ang ating dangal, dapat mas sumasamba tayo, hindi mas yumayabang. At nakagugulat, inilapat ng Hebreo 2:6-9 ang Awit 8 kay Hesus: ang tunay na Taong ganap na nagdadala ng larawan ng Diyos. Para maibalik ang kahulugan ng pagiging tao, tumingin kay Kristo."
    ),
    confirm: [
      t("Psalm 139:13-14: You knit me together in my mother's womb; I am fearfully and wonderfully made.", "Awit 139:13-14: Hinabi Mo ako sa sinapupunan ng aking ina; kamangha-mangha ang pagkakalikha sa akin."),
      t("Colossians 1:16: all things were created through Christ and for Him.", "Colosas 1:16: ang lahat ng bagay ay nilikha sa pamamagitan ni Kristo at para sa Kanya."),
      t("Acts 17:24-28: the God who made the world gives life and breath to all.", "Gawa 17:24-28: ang Diyos na lumikha ng mundo ang nagbibigay ng buhay at hininga sa lahat."),
      t("James 3:9: we should not curse people who are made in the likeness of God.", "Santiago 3:9: hindi natin dapat sumpain ang mga taong nilikha ayon sa wangis ng Diyos."),
    ],
    heart: [
      t(
        "Move from ownership to stewardship. Hold your time, body and money as things entrusted to you by their real Owner.",
        "Lumipat mula sa pagiging may-ari tungo sa pagiging katiwala. Hawakan ang oras, katawan at pera mo bilang mga bagay na ipinagkatiwala sa iyo ng tunay na May-ari."
      ),
      t(
        "Honor God's image in every person. Speak to the guard, the cleaner, the child and the difficult boss with the respect due to God's handiwork.",
        "Igalang ang larawan ng Diyos sa bawat tao. Kausapin ang guwardiya, ang tagalinis, ang bata at ang mahirap pakisamahang amo nang may paggalang na nararapat sa gawa ng Diyos."
      ),
    ],
    questions: [
      t("Which part of your life do you treat as if you own it instead of God?", "Aling bahagi ng buhay mo ang tinatrato mo na parang ikaw ang may-ari sa halip na ang Diyos?"),
      t("Do you believe you are \"very good\" as God's creation, or do you despise yourself?", "Naniniwala ka bang \"napakabuti\" ka bilang nilikha ng Diyos, o minamaliit mo ang sarili mo?"),
      t("Whom do you find hardest to treat as an image-bearer of God?", "Sino ang pinakamahirap mong tratuhin bilang may larawan ng Diyos?"),
      t("How can your daily work reflect the Creator this week?", "Paano maipapakita ng araw-araw mong trabaho ang Manlilikha ngayong linggo?"),
    ],
    actions: [
      t("Spend ten minutes outside looking at the sky or nature, then pray Psalm 8 aloud.", "Gumugol ng sampung minuto sa labas na tumitingin sa langit o kalikasan, tapos ipanalangin nang malakas ang Awit 8."),
      t("Show intentional respect to someone usually overlooked: learn their name and thank them.", "Magpakita ng sinadyang paggalang sa taong kadalasang hindi napapansin: alamin ang pangalan niya at pasalamatan siya."),
      t("Offer your work to God each morning this week: \"Lord, I do this as Your image-bearer.\"", "Ialay sa Diyos ang trabaho mo tuwing umaga ngayong linggo: \"Panginoon, ginagawa ko ito bilang may dala ng Iyong larawan.\""),
    ],
    prayer: t(
      "O Lord, our Lord, how majestic is Your name in all the earth! You made the heavens, the earth and me. Thank You for forming me in Your image and crowning me with dignity. Forgive me for living as if I own what is Yours and for despising what You called very good, in myself and in others. Teach me to steward my life well and to honor every person You made. Amen.",
      "O Panginoon, aming Panginoon, kay dakila ng Iyong pangalan sa buong lupa! Ikaw ang lumikha ng langit, ng lupa at ng aking sarili. Salamat sa paghubog Mo sa akin ayon sa Iyong larawan at sa pagputong sa akin ng dangal. Patawarin Mo ako sa pamumuhay na parang ako ang may-ari ng Iyo at sa pagmamaliit sa tinawag Mong napakabuti, sa akin man o sa iba. Turuan Mo akong maging mabuting katiwala ng aking buhay at igalang ang bawat taong nilikha Mo. Amen."
    ),
  },

  "the-trinity": {
    revelation: t(
      "God is not lonely and never was; the Father, Son and Spirit have always lived in perfect love, and through Jesus they invite you into that fellowship.",
      "Ang Diyos ay hindi nag-iisa at hindi kailanman naging malungkot na nag-iisa; ang Ama, Anak at Espiritu ay laging namumuhay sa ganap na pag-ibig, at sa pamamagitan ni Hesus ay inaanyayahan ka nila sa pakikisamang iyon."
    ),
    mainTruth: t(
      "At Jesus' baptism, the Son comes up from the water, the Spirit descends like a dove, and the Father speaks from heaven: \"This is My beloved Son, with whom I am well pleased\" (Matthew 3:16-17). Jesus sends His disciples to baptize \"in the name (singular) of the Father and of the Son and of the Holy Spirit\" (Matthew 28:19). Paul blesses the church with \"the grace of the Lord Jesus Christ and the love of God and the fellowship of the Holy Spirit\" (2 Corinthians 13:14). The Bible insists there is only one God (Deuteronomy 6:4), and it also shows the Father, the Son and the Spirit as distinct Persons, each fully God. One God, three Persons: not three gods, and not one Person wearing three masks.",
      "Sa bautismo ni Hesus, umahon ang Anak mula sa tubig, bumaba ang Espiritu na parang kalapati, at nagsalita ang Ama mula sa langit: \"Ito ang minamahal kong Anak, na lubos Kong kinalulugdan\" (Mateo 3:16-17). Isinugo ni Hesus ang mga alagad na magbautismo \"sa pangalan (iisa) ng Ama, ng Anak at ng Espiritu Santo\" (Mateo 28:19). Pinagpala ni Pablo ang iglesya ng \"biyaya ng Panginoong Hesu-Kristo, pag-ibig ng Diyos at pakikisama ng Banal na Espiritu\" (2 Corinto 13:14). Iginigiit ng Bibliya na iisa lang ang Diyos (Deuteronomio 6:4), at ipinapakita rin nito ang Ama, Anak at Espiritu bilang magkakaibang Persona, bawat isa ay ganap na Diyos. Iisang Diyos, tatlong Persona: hindi tatlong diyos, at hindi iisang Persona na nagpapalit ng tatlong maskara."
    ),
    insight: [
      t(
        "Many believers treat the Trinity as a puzzle for theologians, something to accept and then ignore. But the Trinity is not a math problem; it is the shape of God's love. Before creation, before angels or humans, God was already love, because the Father loved the Son in the Spirit (John 17:24). God did not create us because He was lonely and needed someone. He created us out of overflowing love.",
        "Maraming mananampalataya ang tinatrato ang Trinidad bilang palaisipan para sa mga teologo, isang bagay na tatanggapin tapos babalewalain. Pero ang Trinidad ay hindi problema sa math; ito ang hugis ng pag-ibig ng Diyos. Bago ang paglikha, bago ang mga anghel o tao, pag-ibig na ang Diyos, dahil minamahal ng Ama ang Anak sa Espiritu (Juan 17:24). Hindi tayo nilikha ng Diyos dahil nalulungkot Siya at kailangan Niya ng kasama. Nilikha Niya tayo mula sa umaapaw na pag-ibig."
      ),
      t(
        "Notice also how the Trinity shapes prayer and the Christian life. We pray to the Father, through the Son, by the Spirit (Ephesians 2:18). Many believers relate to only one Person: some only to \"God up there,\" some only to Jesus, some only to the Spirit's power. A healthy faith enjoys the Father's love, trusts the Son's grace and walks in the Spirit's fellowship, as Paul's blessing says.",
        "Pansinin din kung paano hinuhubog ng Trinidad ang panalangin at ang buhay-Kristiyano. Nananalangin tayo sa Ama, sa pamamagitan ng Anak, sa tulong ng Espiritu (Efeso 2:18). Maraming mananampalataya ang nakikitungo sa iisang Persona lang: ang ilan sa \"Diyos sa itaas\" lang, ang ilan kay Hesus lang, ang ilan sa kapangyarihan ng Espiritu lang. Ang malusog na pananampalataya ay tinatamasa ang pag-ibig ng Ama, nagtitiwala sa biyaya ng Anak at lumalakad sa pakikisama ng Espiritu, gaya ng sinasabi ng basbas ni Pablo."
      ),
    ],
    life: [
      t(
        "Every illustration of the Trinity eventually breaks: water, ice and steam; an egg's shell, white and yolk; a man who is father, son and husband. They help a little but can mislead. Perhaps the best picture is not an object but a family meal on a Sunday where love flows freely around the table, everyone giving and receiving honor. God is not a lonely ruler; He is an eternal communion of love, and the church is meant to reflect that table.",
        "Bawat paglalarawan sa Trinidad ay nagkukulang sa huli: tubig, yelo at singaw; balat, puti at pula ng itlog; isang lalaking ama, anak at asawa. Nakatutulong nang kaunti pero maaaring makalito. Marahil ang pinakamagandang larawan ay hindi isang bagay kundi isang hapag-kainan ng pamilya tuwing Linggo, kung saan malayang dumadaloy ang pagmamahal sa paligid ng mesa, lahat nagbibigay at tumatanggap ng paggalang. Ang Diyos ay hindi malungkot na pinunong nag-iisa; Siya ay walang hanggang pakikisama ng pag-ibig, at ang iglesya ay dapat sumasalamin sa hapag na iyon."
      ),
      t(
        "For an OFW who lives alone in a bedspace far from family, this truth is comfort. You were made by a relational God, for relationship. Loneliness is real, but it is not your destiny. The Father calls you His child, the Son calls you His friend, and the Spirit lives inside you. And He places you in a church family so you can taste on earth the fellowship that God has always enjoyed.",
        "Para sa OFW na nakatira mag-isa sa bedspace, malayo sa pamilya, ang katotohanang ito ay kaaliwan. Nilikha ka ng Diyos na may ugnayan, para sa ugnayan. Totoo ang kalungkutan, pero hindi ito ang tadhana mo. Tinatawag kang anak ng Ama, tinatawag kang kaibigan ng Anak, at nananahan sa loob mo ang Espiritu. At inilalagay ka Niya sa pamilya ng iglesya para matikman mo rito sa lupa ang pakikisamang laging tinatamasa ng Diyos."
      ),
    ],
    twist: t(
      "At the baptism, before Jesus had preached one sermon or done one miracle, the Father said, \"I am well pleased.\" Within the Trinity, love is not earned by performance; it is given and enjoyed. And here is the wonder: because you are in Christ, the Father's words over the Son now apply to you too. You are baptized into the same name. The love that has flowed between Father, Son and Spirit forever is the love that now surrounds you.",
      "Sa bautismo, bago pa nangaral si Hesus ng isang sermon o gumawa ng isang himala, sinabi ng Ama, \"Lubos Kong kinalulugdan.\" Sa loob ng Trinidad, ang pag-ibig ay hindi pinaghihirapan sa performance; ibinibigay at tinatamasa ito. At heto ang kamangha-mangha: dahil ikaw ay nakay Kristo, ang mga salita ng Ama sa Anak ay para na rin sa iyo. Binautismuhan ka sa parehong pangalan. Ang pag-ibig na walang hanggang dumadaloy sa pagitan ng Ama, Anak at Espiritu ang pag-ibig na pumapalibot na ngayon sa iyo."
    ),
    confirm: [
      t("Genesis 1:26: \"Let US make man in OUR image.\"", "Genesis 1:26: \"Lalangin NATIN ang tao ayon sa ATING larawan.\""),
      t("John 14:16-17: the Son asks the Father, and the Father gives another Helper, the Spirit.", "Juan 14:16-17: humiling ang Anak sa Ama, at nagbigay ang Ama ng isa pang Katulong, ang Espiritu."),
      t("John 17:24: the Father loved the Son before the foundation of the world.", "Juan 17:24: minahal ng Ama ang Anak bago pa likhain ang sanlibutan."),
      t("Ephesians 2:18: through Christ we both have access in one Spirit to the Father.", "Efeso 2:18: sa pamamagitan ni Kristo, may daan tayo sa iisang Espiritu patungo sa Ama."),
    ],
    heart: [
      t(
        "Let worship replace confusion. You do not need to fully explain God to fully adore Him; mystery is a reason to kneel, not to walk away.",
        "Hayaang palitan ng pagsamba ang kalituhan. Hindi mo kailangang lubos na maipaliwanag ang Diyos para lubos Siyang sambahin; ang hiwaga ay dahilan para lumuhod, hindi para lumayo."
      ),
      t(
        "Become a person of communion. A God of love calls you out of isolation into honest, giving relationships in His family.",
        "Maging taong marunong makisama. Tinatawag ka ng Diyos ng pag-ibig mula sa pag-iisa tungo sa tapat at mapagbigay na ugnayan sa Kanyang pamilya."
      ),
    ],
    questions: [
      t("Which Person of the Trinity do you relate to most, and which least?", "Aling Persona ng Trinidad ang pinakamalapit sa iyo, at alin ang pinakamalayo?"),
      t("Do you believe God loves you without needing you to perform first?", "Naniniwala ka bang mahal ka ng Diyos nang hindi mo kailangang mag-perform muna?"),
      t("How does it change your loneliness to know you were made by and for a relational God?", "Paano binabago ang kalungkutan mo ng kaalamang nilikha ka ng at para sa Diyos na may ugnayan?"),
      t("How can your relationships reflect the giving love of the Trinity?", "Paano maipapakita ng iyong mga relasyon ang mapagbigay na pag-ibig ng Trinidad?"),
    ],
    actions: [
      t("Pray using 2 Corinthians 13:14 this week: thank the Father for His love, Jesus for His grace and the Spirit for His fellowship.", "Manalangin gamit ang 2 Corinto 13:14 ngayong linggo: pasalamatan ang Ama sa pag-ibig, si Hesus sa biyaya at ang Espiritu sa pakikisama."),
      t("Read Matthew 3:13-17 and hear the Father's words as spoken over you in Christ.", "Basahin ang Mateo 3:13-17 at pakinggan ang mga salita ng Ama na parang sinasabi sa iyo kay Kristo."),
      t("Reach out to one believer who is isolated and invite them to a meal or a call.", "Lapitan ang isang kapatid na nag-iisa at imbitahan siya sa salu-salo o tawag."),
    ],
    prayer: t(
      "Father, Son and Holy Spirit, one God forever, I worship You. Thank You, Father, for Your love that chose me. Thank You, Lord Jesus, for Your grace that saved me. Thank You, Holy Spirit, for Your fellowship that never leaves me. I do not understand all that You are, but I bow before You. Draw me deeper into Your love, and make my life and my church a reflection of the communion You have always enjoyed. Amen.",
      "Ama, Anak at Espiritu Santo, iisang Diyos magpakailanman, sinasamba Kita. Salamat, Ama, sa Iyong pag-ibig na pumili sa akin. Salamat, Panginoong Hesus, sa Iyong biyaya na nagligtas sa akin. Salamat, Banal na Espiritu, sa Iyong pakikisama na hindi kailanman lumilisan. Hindi ko lubos na nauunawaan ang lahat ng Ikaw, pero lumuluhod ako sa harap Mo. Ilapit Mo pa ako sa Iyong pag-ibig, at gawing salamin ang aking buhay at iglesya ng pakikisamang lagi Mong tinatamasa. Amen."
    ),
  },

  "what-went-wrong-sin": {
    revelation: t(
      "Sin is not just breaking rules; it is a broken trust that hides from God, and God's first response to it is to come looking for us.",
      "Ang kasalanan ay hindi lang paglabag sa patakaran; ito ay sirang pagtitiwala na nagtatago sa Diyos, at ang unang tugon ng Diyos dito ay ang hanapin tayo."
    ),
    mainTruth: t(
      "In Genesis 3:1-13, the serpent begins with a question that twists God's word: \"Did God actually say...?\" Then a direct lie: \"You will not surely die.\" Eve and Adam doubt God's goodness, take what He forbade, and immediately feel shame, hide and blame each other. Since then, \"all have sinned and fall short of the glory of God\" (Romans 3:23), and \"the wages of sin is death, but the free gift of God is eternal life in Christ Jesus our Lord\" (Romans 6:23). Sin is universal, it is deadly, and it is not the end of the story, because God has provided a gift.",
      "Sa Genesis 3:1-13, nagsimula ang ahas sa isang tanong na binabaluktot ang salita ng Diyos: \"Talaga bang sinabi ng Diyos...?\" Sumunod ang tahasang kasinungalingan: \"Hindi kayo tiyak na mamamatay.\" Nagduda sina Eva at Adan sa kabutihan ng Diyos, kinuha ang ipinagbawal Niya, at agad na nakaramdam ng hiya, nagtago at nagsisihan. Mula noon, \"ang lahat ay nagkasala at hindi umabot sa kaluwalhatian ng Diyos\" (Roma 3:23), at \"ang kabayaran ng kasalanan ay kamatayan, ngunit ang walang bayad na kaloob ng Diyos ay buhay na walang hanggan kay Kristo Hesus na ating Panginoon\" (Roma 6:23). Pangkalahatan ang kasalanan, nakamamatay ito, at hindi ito ang katapusan ng kuwento, dahil naglaan ang Diyos ng kaloob."
    ),
    insight: [
      t(
        "The first sin did not start with the fruit; it started with a suspicion: \"Maybe God is holding out on me.\" Every sin since then carries that same lie: that God's commands keep us from good things, and that we know better how to be happy. Before we take the forbidden fruit with our hands, we have already doubted His goodness in our hearts.",
        "Hindi nagsimula sa prutas ang unang kasalanan; nagsimula ito sa hinala: \"Baka may ipinagkakait sa akin ang Diyos.\" Bawat kasalanan mula noon ay may parehong kasinungalingan: na pinipigilan tayo ng mga utos ng Diyos sa mabubuting bagay, at mas alam natin kung paano maging masaya. Bago pa natin hawakan ng kamay ang bawal na prutas, nagduda na tayo sa Kanyang kabutihan sa ating puso."
      ),
      t(
        "We also overlook how sin spreads into relationships. Adam blamed Eve and even God (\"the woman whom You gave\"), and Eve blamed the serpent. Shame made them cover up and hide. Today, sin still shows up as hiding, excuses and blame: in marriages, offices and churches. Recognizing sin honestly is not depressing; it is the first step to healing.",
        "Nakaliligtaan din natin kung paano kumakalat ang kasalanan sa mga relasyon. Sinisi ni Adan si Eva at maging ang Diyos (\"ang babaeng ibinigay Mo\"), at sinisi ni Eva ang ahas. Pinagtakip at pinagtago sila ng hiya. Ngayon, lumilitaw pa rin ang kasalanan bilang pagtatago, palusot at paninisi: sa pag-aasawa, opisina at iglesya. Ang tapat na pagkilala sa kasalanan ay hindi nakapanlulumo; ito ang unang hakbang sa paggaling."
      ),
    ],
    life: [
      t(
        "A young worker started taking small amounts from the store's cash: just fifty pesos, \"utang lang, babayaran ko.\" Then a hundred, then more. When the owner noticed, he blamed a coworker. Sin rarely announces itself as a big crime. It starts with a little compromise and a whisper of \"no one will know,\" and it ends with hiding and blaming. That is Genesis 3 replayed in a sari-sari store.",
        "May isang batang manggagawa na nagsimulang kumuha ng maliit na halaga sa kaha ng tindahan: limampung piso lang, \"utang lang, babayaran ko.\" Tapos isandaan, tapos mas marami pa. Nang mapansin ng may-ari, sinisi niya ang katrabaho. Bihirang magpakilala ang kasalanan bilang malaking krimen. Nagsisimula ito sa maliit na kompromiso at bulong na \"walang makaaalam,\" at nagtatapos sa pagtatago at paninisi. Iyan ang Genesis 3 na inuulit sa isang sari-sari store."
      ),
      t(
        "Many people compare themselves with others and feel fine: \"At least I am not a murderer or a drug lord.\" But Romans 3:23 does not measure us against other people; it measures us against \"the glory of God.\" Like jumping from Manila to Palawan, the strong swimmer may go farther than the weak one, but both still fall short. That is why everyone needs the same Savior.",
        "Maraming tao ang inihahambing ang sarili sa iba at panatag na: \"Hindi naman ako mamamatay-tao o drug lord.\" Pero hindi tayo sinusukat ng Roma 3:23 laban sa ibang tao; sinusukat tayo laban sa \"kaluwalhatian ng Diyos.\" Parang paglangoy mula Maynila hanggang Palawan: mas malayo ang mararating ng magaling lumangoy kaysa sa mahina, pero parehong hindi aabot. Kaya lahat ay nangangailangan ng iisang Tagapagligtas."
      ),
    ],
    twist: t(
      "After the first sin, the first words of God are not a sentence of judgment but a question: \"Where are you?\" (Genesis 3:9). God knew where they were; He was inviting them out of hiding. The story of sin begins with humans running from God, and the story of salvation begins with God running after humans. Even in Genesis 3:15 and 3:21, God promises a Deliverer and covers their shame with garments made by His own hands. The bad news of sin is the dark background that makes the gift of grace shine.",
      "Pagkatapos ng unang kasalanan, ang unang salita ng Diyos ay hindi hatol kundi tanong: \"Nasaan ka?\" (Genesis 3:9). Alam ng Diyos kung nasaan sila; inaanyayahan Niya silang lumabas mula sa pagtatago. Ang kuwento ng kasalanan ay nagsisimula sa taong tumatakbo palayo sa Diyos, at ang kuwento ng kaligtasan ay nagsisimula sa Diyos na humahabol sa tao. Kahit sa Genesis 3:15 at 3:21, nangako ang Diyos ng Tagapagligtas at tinakpan ang kanilang hiya ng damit na gawa ng sarili Niyang mga kamay. Ang masamang balita ng kasalanan ang madilim na background na nagpapaningning sa kaloob ng biyaya."
    ),
    confirm: [
      t("Isaiah 53:6: all we like sheep have gone astray, and the Lord laid on Him our iniquity.", "Isaias 53:6: lahat tayo, gaya ng tupa, ay naligaw, at iniatang ng Panginoon sa Kanya ang ating kasamaan."),
      t("Psalm 51:3-4: David confesses, \"Against You, You only, have I sinned.\"", "Awit 51:3-4: nagpahayag si David, \"Laban sa Iyo, sa Iyo lamang, ako nagkasala.\""),
      t("Luke 19:10: the Son of Man came to seek and to save the lost.", "Lucas 19:10: dumating ang Anak ng Tao upang hanapin at iligtas ang naliligaw."),
      t("1 John 1:9: if we confess our sins, He is faithful and just to forgive.", "1 Juan 1:9: kung ipahahayag natin ang ating mga kasalanan, Siya ay tapat at matuwid na magpapatawad."),
    ],
    heart: [
      t(
        "Stop hiding and blaming. Come out into the light with honest confession; God already knows, and He is calling you, not to shame you, but to restore you.",
        "Tumigil sa pagtatago at paninisi. Lumabas sa liwanag nang may tapat na pagpapahayag; alam na ng Diyos, at tinatawag ka Niya, hindi para ipahiya ka, kundi para ibalik ka."
      ),
      t(
        "Trust God's goodness when His commands feel restrictive. Every \"no\" from a good Father protects a bigger \"yes.\"",
        "Magtiwala sa kabutihan ng Diyos kapag pakiramdam mo ay mahigpit ang Kanyang mga utos. Bawat \"hindi\" mula sa mabuting Ama ay nag-iingat ng mas malaking \"oo.\""
      ),
    ],
    questions: [
      t("Where are you tempted to believe that God is holding out on you?", "Saan ka natutuksong maniwala na may ipinagkakait sa iyo ang Diyos?"),
      t("Is there any sin you are currently hiding, excusing or blaming on someone else?", "May kasalanan ka bang kasalukuyang itinatago, pinalulusot o isinisisi sa iba?"),
      t("Do you measure yourself against other people or against God's glory?", "Sinusukat mo ba ang sarili mo laban sa ibang tao o laban sa kaluwalhatian ng Diyos?"),
      t("How do you hear God's question \"Where are you?\" in your life today?", "Paano mo naririnig ang tanong ng Diyos na \"Nasaan ka?\" sa buhay mo ngayon?"),
    ],
    actions: [
      t("Answer God's question in writing: \"Lord, here is where I am...\" Be completely honest.", "Sagutin nang nakasulat ang tanong ng Diyos: \"Panginoon, narito ako...\" Maging lubos na tapat."),
      t("Confess one specific sin to God today, and if needed, to a trusted mentor (James 5:16).", "Ipahayag ang isang tiyak na kasalanan sa Diyos ngayon, at kung kailangan, sa isang mapagkakatiwalaang mentor (Santiago 5:16)."),
      t("Memorize Romans 6:23 and share it with one person this week, both the bad news and the gift.", "Isaulo ang Roma 6:23 at ibahagi ito sa isang tao ngayong linggo, ang masamang balita at ang kaloob."),
    ],
    prayer: t(
      "Holy God, I confess that I have sinned and fallen short of Your glory. Like Adam and Eve, I have doubted Your goodness, hidden from You and blamed others. Thank You that You still come looking for me, asking, \"Where are you?\" Here I am, Lord. I receive the free gift of eternal life in Christ Jesus. Cover my shame, cleanse my heart, and teach me to trust Your goodness. Amen.",
      "Banal na Diyos, ipinapahayag ko na ako ay nagkasala at hindi umabot sa Iyong kaluwalhatian. Gaya nina Adan at Eva, nagduda ako sa Iyong kabutihan, nagtago sa Iyo at nanisi ng iba. Salamat dahil hinahanap Mo pa rin ako, nagtatanong, \"Nasaan ka?\" Narito ako, Panginoon. Tinatanggap ko ang walang bayad na kaloob na buhay na walang hanggan kay Kristo Hesus. Takpan Mo ang aking hiya, linisin ang aking puso, at turuan akong magtiwala sa Iyong kabutihan. Amen."
    ),
  },
  "declared-righteous": {
    revelation: t(
      "God does not wait for you to become good before He calls you righteous; at the cross, He placed your sin on Jesus and Christ's righteousness on you.",
      "Hindi naghihintay ang Diyos na maging mabuti ka muna bago ka ituring na matuwid; sa krus, inilagay Niya ang kasalanan mo kay Hesus at ang katuwiran ni Cristo sa iyo."
    ),
    mainTruth: t(
      "\"For all have sinned and fall short of the glory of God, and all are justified freely by his grace through the redemption that came by Christ Jesus\" (Romans 3:23-24). To be justified means God declares us righteous, as a judge announces \"not guilty,\" not because we earned it but because Jesus took our penalty. \"God made him who had no sin to be sin for us, so that in him we might become the righteousness of God\" (2 Corinthians 5:21). The result is peace: \"Since we have been justified through faith, we have peace with God\" (Romans 5:1).",
      "\"Sapagkat ang lahat ay nagkasala at hindi nakaabot sa kaluwalhatian ng Diyos, at ang lahat ay inaaring-ganap nang walang bayad sa pamamagitan ng Kanyang biyaya, sa pamamagitan ng katubusang kay Cristo Hesus\" (Roma 3:23-24). Ang pag-aaring-ganap ay ang pagpapahayag ng Diyos na tayo ay matuwid, gaya ng hukom na nagsasabing \"walang sala,\" hindi dahil kinita natin kundi dahil pinasan ni Hesus ang parusa. \"Ang hindi nagkasala ay ginawa Niyang kasalanan dahil sa atin, upang tayo ay maging katuwiran ng Diyos sa Kanya\" (2 Corinto 5:21). Ang bunga ay kapayapaan: \"Yamang inaring-ganap tayo sa pamamagitan ng pananampalataya, may kapayapaan tayo sa Diyos\" (Roma 5:1)."
    ),
    insight: [
      t(
        "Many believers live like defendants still waiting for the verdict. They sin, feel guilty and assume they must start over, trying to be good enough to be accepted again. But justification is a finished verdict, not a daily performance review. God did not overlook sin; Romans 3:25-26 says He is both \"just and the one who justifies,\" because the penalty was fully paid in Christ's blood. Mercy never cancelled justice; it was satisfied by it.",
        "Maraming mananampalataya ang namumuhay na parang nasasakdal na naghihintay pa ng hatol. Nagkakasala sila, nakokonsensya at inaakalang kailangang magsimulang muli, sinusubukang maging sapat na mabuti para tanggapin ulit. Pero ang pag-aaring-ganap ay tapos nang hatol, hindi araw-araw na performance review. Hindi nagkibit-balikat ang Diyos sa kasalanan; sabi ng Roma 3:25-26, Siya ay \"makatarungan at tagapag-aring-ganap,\" dahil lubusan nang nabayaran ang parusa sa dugo ni Cristo. Hindi pinawalang-bisa ng awa ang katarungan; natupad ito."
      ),
      t(
        "Notice also the great exchange in 2 Corinthians 5:21: Jesus took what is ours (sin) and gave what is His (righteousness). It is not that God pretends we are righteous; in Christ we truly are, because we are joined to Him. That means your standing before God does not rise and fall with your best or worst day. It rests on Christ's record, not yours.",
        "Pansinin din ang dakilang palitan sa 2 Corinto 5:21: kinuha ni Hesus ang sa atin (kasalanan) at ibinigay ang sa Kanya (katuwiran). Hindi nagkukunwari ang Diyos na matuwid tayo; kay Cristo, tunay tayong matuwid dahil nakaugnay tayo sa Kanya. Ibig sabihin, ang katayuan mo sa harap ng Diyos ay hindi tumataas o bumababa ayon sa pinakamagandang o pinakamasama mong araw. Nakasalalay ito sa talaan ni Cristo, hindi sa iyo."
      ),
    ],
    life: [
      t(
        "Danilo, an OFW electrician, grew up believing that God kept a ledger. After a bad night of drinking with coworkers, he avoided prayer for two weeks, convinced God was angry. A friend showed him Romans 5:1. \"Peace with God is not what I feel,\" Danilo said later. \"It is what Jesus did.\" He confessed, received forgiveness and walked back in without hiding. Guilt told him to stay away; grace invited him home.",
        "Si Danilo, OFW na electrician, lumaki sa paniniwalang may talaan ng kasalanan ang Diyos. Matapos ang masamang gabi ng inuman kasama ang mga katrabaho, dalawang linggo siyang umiwas sa panalangin, sigurado siyang galit ang Diyos. Ipinakita ng kaibigan niya ang Roma 5:1. \"Ang kapayapaan sa Diyos ay hindi ang nararamdaman ko,\" sabi niya pagkatapos. \"Iyon ang ginawa ni Hesus.\" Nagtapat siya, tumanggap ng kapatawaran at bumalik nang hindi nagtatago. Sinabi ng konsensya na lumayo; inanyayahan siya ng biyaya pauwi."
      ),
      t(
        "When accusing thoughts come, \"You are a hypocrite, God is done with you,\" answer with the verdict: \"There is now no condemnation for those who are in Christ Jesus\" (Romans 8:1). Then live from acceptance, not for acceptance.",
        "Kapag dumating ang mga paratang, \"Pakitang-tao ka, tapos na sa iyo ang Diyos,\" sagutin ng hatol: \"Wala nang hatol na parusa sa mga nakay Cristo Hesus\" (Roma 8:1). Pagkatapos, mamuhay mula sa pagtanggap, hindi para matanggap."
      ),
    ],
    twist: t(
      "We think righteousness is something we climb toward. In the Kingdom it is a gift we receive on our knees. The more you try to earn it, the less you can enjoy it; the more you receive it, the more it changes you. People who know they are forgiven much, love much (Luke 7:47). Grace does not produce lazy believers; it produces grateful ones.",
      "Akala natin ang katuwiran ay inaakyat natin. Sa Kaharian, regalo itong tinatanggap nang nakaluhod. Habang pilit mo itong kinikita, lalong hindi mo ito nasisiyahan; habang tinatanggap mo, lalo kang nababago. Ang mga nakakaalam na marami silang pinatawad ay umiibig nang marami (Lucas 7:47). Hindi nagbubunga ng tamad na mananampalataya ang biyaya; nagbubunga ito ng mapagpasalamat."
    ),
    confirm: [
      t("Genesis 15:6: Abraham believed God, and it was credited to him as righteousness.", "Genesis 15:6: sumampalataya si Abraham sa Diyos at ibinilang itong katuwiran sa kanya."),
      t("Galatians 2:16: a person is not justified by works of the law but through faith in Christ.", "Galacia 2:16: ang tao ay hindi inaaring-ganap sa gawa ng kautusan kundi sa pananampalataya kay Cristo."),
      t("Isaiah 61:10: He has clothed me with garments of salvation and a robe of righteousness.", "Isaias 61:10: dinamitan Niya ako ng damit ng kaligtasan at balabal ng katuwiran."),
      t("Romans 8:33-34: who will bring a charge against God's elect? It is God who justifies.", "Roma 8:33-34: sino ang magsasakdal sa mga hinirang ng Diyos? Ang Diyos ang nag-aaring-ganap."),
    ],
    heart: [
      t(
        "Stop trying to win God's approval. Receive it. Thank Him that the verdict is already in, and let that peace quiet your fear of failure.",
        "Itigil ang pagsusumikap na makuha ang pagsang-ayon ng Diyos. Tanggapin ito. Pasalamatan Siya na nakalabas na ang hatol, at hayaang patahimikin ng kapayapaang iyon ang takot mo sa pagkabigo."
      ),
      t(
        "Extend the same grace to others. A person who knows they have been declared righteous has no reason to look down on the failing.",
        "Ibigay rin sa iba ang parehong biyaya. Ang taong alam na inaring-ganap siya ay walang dahilan para hamakin ang nadadapa."
      ),
    ],
    questions: [
      t("Do I treat God as a judge still deciding, or as a Father who has already declared me His child?", "Itinuturing ko ba ang Diyos na hukom na nagpapasya pa, o Ama na nagpahayag nang anak Niya ako?"),
      t("Where am I still trying to earn what Jesus already paid for?", "Saan ko pa sinusubukang kitain ang binayaran na ni Hesus?"),
      t("What accusations do I believe that Romans 8:1 answers?", "Anong paratang ang pinaniniwalaan ko na sinasagot ng Roma 8:1?"),
      t("How does being forgiven change how I treat others?", "Paano binabago ng pagiging pinatawad ang pakikitungo ko sa iba?"),
    ],
    actions: [
      t("Read Romans 5:1-2 aloud and thank God for each blessing it names.", "Basahin nang malakas ang Roma 5:1-2 at pasalamatan ang Diyos sa bawat pagpapalang nabanggit."),
      t("Next time guilt comes, answer it with Romans 8:1 before you do anything else.", "Sa susunod na dumating ang guilt, sagutin ito ng Roma 8:1 bago gumawa ng iba."),
      t("Forgive one person who has been on your list of grudges.", "Patawarin ang isang taong nasa listahan mo ng tampo."),
    ],
    prayer: t(
      "Father, thank You that You have declared me righteous, not because of my works but because of Jesus. Forgive my attempts to earn what You freely give. When guilt and accusation speak, remind me of Your verdict: no condemnation. Let me walk in peace with You and show that same grace to others. I rest in the finished work of Christ, my Savior. In His name, Amen.",
      "Ama, salamat po na idineklara Mo akong matuwid, hindi dahil sa gawa ko kundi dahil kay Hesus. Patawarin Mo ako sa pagsubok kong kitain ang ibinibigay Mo nang libre. Kapag nagsalita ang guilt at paratang, ipaalala Mo ang Iyong hatol: walang hatol na parusa. Hayaan Mo akong lumakad sa kapayapaan sa Iyo at ibahagi ang parehong biyaya sa iba. Nagpapahinga ako sa natapos na gawa ni Cristo, aking Tagapagligtas. Sa Kanyang pangalan, Amen."
    ),
  },
  "growing-holy": {
    revelation: t(
      "Holiness is not you trying harder to be good; it is God at work in you, and your part is to cooperate with Him.",
      "Ang kabanalan ay hindi pagsusumikap mong maging mabuti; ito ay gawain ng Diyos sa iyo, at ang bahagi mo ay makipagtulungan sa Kanya."
    ),
    mainTruth: t(
      "\"It is God's will that you should be sanctified\" (1 Thessalonians 4:3). The same God who justified us now shapes us. Paul says, \"Work out your salvation with fear and trembling, for it is God who works in you to will and to act in order to fulfill his good purpose\" (Philippians 2:12-13). And as we gaze at Jesus, \"we are being transformed into his image with ever-increasing glory, which comes from the Lord, who is the Spirit\" (2 Corinthians 3:18). Holiness is a lifelong, Spirit-powered becoming.",
      "\"Ito ang kalooban ng Diyos, ang inyong pagpapakabanal\" (1 Tesalonica 4:3). Ang Diyos na nag-aaring-ganap sa atin ay Siya ring humuhubog sa atin ngayon. Sabi ni Pablo, \"Pagsikapan ninyong tamuhin ang inyong kaligtasan nang may takot at panginginig, sapagkat ang Diyos ang gumagawa sa inyo ng pagnanais at paggawa ayon sa Kanyang mabuting layunin\" (Filipos 2:12-13). At habang nakatitig tayo kay Hesus, \"binabago tayo tungo sa Kanyang wangis nang may patuloy na paglaki ng kaluwalhatian, na mula sa Panginoon, ang Espiritu\" (2 Corinto 3:18). Ang kabanalan ay habambuhay na pagiging-bago na pinapagana ng Espiritu."
    ),
    insight: [
      t(
        "Notice the two halves of Philippians 2:12-13: \"work out\" and \"God works in.\" Many believers fall into one of two ditches: passivity (\"God will do everything, I just wait\") or self-effort (\"I must fix myself\"). Biblical holiness is partnership: He supplies the desire and power; we supply the yes. The word \"holy\" means set apart for God, and it shows up in real choices, including what we do with our bodies, our relationships and our words (1 Thessalonians 4:3-8).",
        "Pansinin ang dalawang bahagi ng Filipos 2:12-13: \"pagsikapan\" at \"ang Diyos ang gumagawa sa inyo.\" Maraming mananampalataya ang nahuhulog sa isa sa dalawang kanal: pagiging pasibo (\"Ang Diyos ang gagawa ng lahat, maghihintay lang ako\") o pagsisikap sa sarili (\"Ako ang dapat mag-ayos sa sarili ko\"). Ang kabanalan ayon sa Biblia ay pakikipagtulungan: Siya ang nagbibigay ng pagnanais at lakas; tayo ang nagbibigay ng oo. Ang \"banal\" ay itinalaga para sa Diyos, at lumilitaw ito sa tunay na mga pasya, kasama ang ginagawa natin sa katawan, relasyon at salita (1 Tesalonica 4:3-8)."
      ),
      t(
        "The secret in 2 Corinthians 3:18 is that transformation comes through beholding. We become like what we gaze at. Holiness is not mostly about staring at your sin and fighting it; it is about looking at Jesus until His beauty makes sin look small and cheap.",
        "Ang lihim sa 2 Corinto 3:18 ay ang pagbabago ay dumarating sa pagtitig. Nagiging katulad tayo ng tinititigan natin. Ang kabanalan ay hindi lang pagtitig sa kasalanan at paglaban dito; ito ay pagtingin kay Hesus hanggang sa Kanyang kagandahan ang magpaliit at magpamura sa kasalanan."
      ),
    ],
    life: [
      t(
        "Carla struggled with a quick temper. Every promise to \"do better\" failed by the weekend. Her mentor suggested she stop only fighting the anger and start daily gazing at Jesus: reading one Gospel story each morning, asking, \"What is He like?\" and then asking the Spirit for His patience for that day. After months, the change was not dramatic but steady. Her sister said, \"Hindi ka na basta sumasabog.\" Holiness grew like a plant, quietly but really.",
        "Mainitin ang ulo ni Carla. Bawat pangakong \"magbabago na ako\" ay nabibigo pagdating ng weekend. Iminungkahi ng mentor niya na huwag lang labanan ang galit kundi simulan ang araw-araw na pagtitig kay Hesus: magbasa ng isang kuwento sa Ebanghelyo tuwing umaga, itanong, \"Anong uri ng Panginoon Siya?\" at hilingin sa Espiritu ang Kanyang pasensya para sa araw na iyon. Pagkalipas ng ilang buwan, hindi biglaan pero tuloy-tuloy ang pagbabago. Sabi ng kapatid niya, \"Hindi ka na basta sumasabog.\" Lumago ang kabanalan na parang halaman, tahimik pero totoo."
      ),
      t(
        "Practical holiness: say yes to the Spirit's prompting, flee what feeds sin, stay in fellowship, confess quickly and keep going after a fall. A fall does not cancel your sonship; it calls you back.",
        "Praktikal na kabanalan: sumunod sa udyok ng Espiritu, lumayo sa nagpapakain ng kasalanan, manatili sa pakikipagkaisa, magtapat agad at magpatuloy matapos madapa. Hindi pinapawalang-bisa ng pagkadapa ang pagiging anak mo; tinatawag ka nitong bumalik."
      ),
    ],
    twist: t(
      "We imagine that holy people are the ones who sin less out of sheer willpower. The Kingdom twist is that holy people are often the ones who admit weakness fastest and depend on God most. Paul boasts in his weakness because \"when I am weak, then I am strong\" (2 Corinthians 12:10). Holiness grows in the soil of dependence, not self-confidence.",
      "Akala natin ang mga banal ay yaong mas kaunti ang kasalanan dahil sa lakas ng loob. Ang Kaharian twist: ang mga banal ay madalas ang pinakamabilis umamin ng kahinaan at pinakaasa sa Diyos. Ipinagmamalaki ni Pablo ang kanyang kahinaan dahil \"kapag mahina ako, saka ako malakas\" (2 Corinto 12:10). Lumalago ang kabanalan sa lupa ng pag-asa sa Diyos, hindi sa tiwala sa sarili."
    ),
    confirm: [
      t("1 Peter 1:15-16: be holy in all you do, for He who called you is holy.", "1 Pedro 1:15-16: maging banal sa lahat ng ginagawa, sapagkat banal ang tumawag sa inyo."),
      t("Hebrews 12:14: pursue holiness; without it no one will see the Lord.", "Hebreo 12:14: hangarin ang kabanalan; kung wala nito, walang makakakita sa Panginoon."),
      t("Galatians 5:22-23: the Spirit produces love, joy, peace, patience and self-control.", "Galacia 5:22-23: ang Espiritu ay nagbubunga ng pag-ibig, galak, kapayapaan, pasensya at pagpipigil sa sarili."),
      t("Romans 6:11-13: count yourselves dead to sin and alive to God.", "Roma 6:11-13: ibilang ang sarili na patay sa kasalanan at buhay sa Diyos."),
    ],
    heart: [
      t(
        "Choose today one area to surrender to God, not as a burden but as an invitation: \"Lord, work here.\" Replace shame with trust that He finishes what He starts.",
        "Pumili ngayon ng isang bahagi na isusuko sa Diyos, hindi bilang pasanin kundi paanyaya: \"Panginoon, gumawa Ka rito.\" Palitan ang hiya ng tiwalang tinatapos Niya ang sinimulan Niya."
      ),
      t(
        "Pursue holiness with joy, not fear of punishment. Holiness is not less life but more of the life God designed.",
        "Hangarin ang kabanalan nang may galak, hindi takot sa parusa. Ang kabanalan ay hindi kakulangan ng buhay kundi mas buong buhay na dinisenyo ng Diyos."
      ),
    ],
    questions: [
      t("Am I leaning toward passivity or self-effort in my spiritual growth?", "Mas nakahilig ba ako sa pagiging pasibo o sa pagsisikap sa sarili sa paglago ko?"),
      t("What am I gazing at most each day, and what is it shaping in me?", "Ano ang pinakamadalas kong tinititigan araw-araw, at ano ang hinuhubog nito sa akin?"),
      t("What habit or setting feeds the sin I want to leave?", "Anong gawi o lugar ang nagpapakain sa kasalanang gusto kong iwan?"),
      t("Do I get up quickly after I fall, or do I hide?", "Mabilis ba akong bumabangon pagkatapos madapa, o nagtatago ako?"),
    ],
    actions: [
      t("Spend ten minutes daily this week gazing at Jesus in a Gospel passage.", "Maglaan ng sampung minuto araw-araw ngayong linggo para titigan si Hesus sa isang talata ng Ebanghelyo."),
      t("Identify one trigger of sin and remove or limit it this week.", "Tukuyin ang isang sanhi ng kasalanan at alisin o bawasan ito ngayong linggo."),
      t("Tell a trusted believer about one struggle and ask them to pray and check in.", "Sabihin sa pinagkakatiwalaang kapatid ang isang pinaglalabanan mo at hilingin ang panalangin at pangungumusta niya."),
    ],
    prayer: t(
      "Holy Father, thank You that You are at work in me. Forgive me for relying on my own strength or for waiting passively. Give me both the desire and the power to obey. Turn my eyes to Jesus until I look more like Him. Help me flee what harms my soul and run toward what honors You. When I fall, lift me quickly. Finish the good work You began in me. In Jesus' name, Amen.",
      "Amang Banal, salamat po na gumagawa Ka sa akin. Patawarin Mo ako sa pag-asa sa sarili kong lakas o sa pasibong paghihintay. Bigyan Mo ako ng pagnanais at kapangyarihang sumunod. Ibaling Mo ang mga mata ko kay Hesus hanggang magmukha akong higit na katulad Niya. Tulungan Mo akong lumayo sa nakasasama sa kaluluwa ko at tumakbo tungo sa nagpaparangal sa Iyo. Kapag nadapa ako, agad Mo akong itayo. Tapusin Mo ang mabuting gawang sinimulan Mo sa akin. Sa pangalan ni Hesus, Amen."
    ),
  },
  "the-spirits-work": {
    revelation: t(
      "Jesus said it was better for Him to go, because the Holy Spirit does in every believer what Jesus could do only beside a few.",
      "Sinabi ni Hesus na mas mabuti para sa atin ang Kanyang pag-alis, dahil ginagawa ng Banal na Espiritu sa bawat mananampalataya ang magagawa lang ni Hesus sa tabi ng iilan."
    ),
    mainTruth: t(
      "\"It is for your good that I am going away. Unless I go away, the Advocate will not come to you; but if I go, I will send him to you\" (John 16:7). The Spirit convicts the world about sin, righteousness and judgment, guides us into all truth, and glorifies Jesus (John 16:8-15). He also empowers: \"You will receive power when the Holy Spirit comes on you; and you will be my witnesses\" (Acts 1:8). At Pentecost, the promise arrived (Acts 2:1-4). The Spirit is not a force but a Person, God Himself living in His people.",
      "\"Para sa inyong ikabubuti ang Aking pag-alis. Sapagkat kung hindi Ako aalis, hindi darating sa inyo ang Katulong; ngunit kung aalis Ako, susuguin Ko Siya sa inyo\" (Juan 16:7). Kinukumbinsi ng Espiritu ang sanlibutan tungkol sa kasalanan, katuwiran at paghuhukom, ginagabayan tayo sa buong katotohanan at niluluwalhati si Hesus (Juan 16:8-15). Pinalalakas din Niya tayo: \"Tatanggap kayo ng kapangyarihan kapag dumating sa inyo ang Banal na Espiritu, at kayo'y magiging Aking mga saksi\" (Gawa 1:8). Sa Pentecostes, dumating ang pangako (Gawa 2:1-4). Ang Espiritu ay hindi puwersa kundi Persona, ang Diyos mismo na naninirahan sa Kanyang bayan."
    ),
    insight: [
      t(
        "Many believers know the Father and the Son but treat the Spirit as a mysterious extra. Yet the Spirit is the One who makes Jesus real. He convicts without crushing: His conviction leads to Jesus, not despair. The enemy accuses and condemns; the Spirit convicts and draws us home. If your sense of sin leaves you hiding from God, it is accusation; if it leads you to repentance and hope, it is the Spirit.",
        "Maraming mananampalataya ang nakakakilala sa Ama at sa Anak pero itinuturing na misteryosong dagdag ang Espiritu. Gayunman, Siya ang nagpaparamdam kay Hesus bilang totoo. Nagkukumbinsi Siya nang hindi dumudurog: ang Kanyang pagkumbinsi ay humahantong kay Hesus, hindi sa kawalang-pag-asa. Ang kaaway ay nagpaparatang at humahatol; ang Espiritu ay nagkukumbinsi at umaakay pauwi. Kung ang pakiramdam mo ng kasalanan ay nagtatago sa iyo mula sa Diyos, paratang iyon; kung humahantong ito sa pagsisisi at pag-asa, iyon ang Espiritu."
      ),
      t(
        "The Spirit also guides and glorifies. He does not draw attention to Himself but to Christ. Any teaching, experience or ministry that lifts a person above Jesus, or contradicts Scripture, is not from Him. Believers across traditions differ in how they describe His gifts and the timing of Spirit baptism, but all agree that He lives in every believer, makes us more like Jesus and empowers our witness.",
        "Ginagabayan at niluluwalhati rin ng Espiritu. Hindi Niya inililipat ang atensyon sa Sarili kundi kay Cristo. Anumang turo, karanasan o ministeryo na nagtataas sa tao higit kay Hesus, o sumasalungat sa Kasulatan, ay hindi mula sa Kanya. Magkakaiba ang paglalarawan ng mga mananampalataya sa iba't ibang tradisyon tungkol sa Kanyang mga kaloob at oras ng bautismo sa Espiritu, pero lahat ay sumasang-ayon na naninirahan Siya sa bawat mananampalataya, ginagawa tayong higit na katulad ni Hesus at pinapalakas ang ating patotoo."
      ),
    ],
    life: [
      t(
        "Remember the first time you felt moved to pray for a stranger, or a verse suddenly made sense, or you felt a deep sorrow over a sin you used to enjoy. That was the Spirit at work. An OFW in a crowded bunkhouse said, \"I feel alone, but when I sit in a quiet corner and talk to God, I sense that He is with me.\" That is the Comforter, the Helper, who never leaves.",
        "Alalahanin ang unang beses na nagkaroon ka ng udyok na ipanalangin ang isang estranghero, o biglang luminaw ang isang talata, o nalungkot ka nang malalim sa kasalanang dati mong kinagigiliwan. Gawa iyon ng Espiritu. Sabi ng isang OFW sa siksikang bunkhouse, \"Pakiramdam ko mag-isa ako, pero kapag umupo ako sa tahimik na sulok at kinausap ang Diyos, nararamdaman kong kasama ko Siya.\" Siya ang Mang-aaliw, ang Katulong, na hindi umaalis."
      ),
      t(
        "Make room for Him daily: invite Him in the morning, listen in Scripture, respond quickly to His promptings and ask for His power before you speak, work or serve. A believer who ignores the Spirit lives on borrowed strength; a believer who depends on Him lives on supply.",
        "Bigyan Siya ng puwang araw-araw: anyayahan Siya sa umaga, makinig sa Kasulatan, sumunod agad sa Kanyang udyok at humingi ng Kanyang kapangyarihan bago magsalita, magtrabaho o maglingkod. Ang mananampalatayang hindi pinapansin ang Espiritu ay umaasa sa hiram na lakas; ang umaasa sa Kanya ay nabubuhay sa panustos."
      ),
    ],
    twist: t(
      "It sounds strange that it is better to have Jesus leave. But a Jesus in one body can be in one place; the Spirit brings Jesus to every place at once, including the dormitory in Jeddah and the kitchen in Manila. The Kingdom twist: you are not behind the first disciples; in one sense you are better off, because what they had beside them, you have within you.",
      "Kakaiba ang tunog na mas mabuting umalis si Hesus. Pero ang Hesus na may isang katawan ay nasa isang lugar lang; dinadala ng Espiritu si Hesus sa lahat ng lugar nang sabay, kasama ang dormitoryo sa Jeddah at kusina sa Maynila. Ang Kaharian twist: hindi ka nahuhuli sa mga unang alagad; sa isang paraan, mas mabuti ang kalagayan mo, dahil ang kasama nilang nasa tabi ay nasa loob mo na."
    ),
    confirm: [
      t("Romans 8:9-11: the Spirit of Christ lives in every believer.", "Roma 8:9-11: ang Espiritu ni Cristo ay nananahan sa bawat mananampalataya."),
      t("Romans 8:26: the Spirit helps us in our weakness and prays for us.", "Roma 8:26: tinutulungan tayo ng Espiritu sa ating kahinaan at namamagitan para sa atin."),
      t("Ephesians 1:13-14: the Spirit is a seal and a guarantee of our inheritance.", "Efeso 1:13-14: ang Espiritu ay tatak at garantiya ng ating mana."),
      t("John 14:16-17: the Spirit of truth will be with you forever.", "Juan 14:16-17: ang Espiritu ng katotohanan ay sasainyo magpakailanman."),
    ],
    heart: [
      t(
        "Welcome the Spirit as a Person, not just a power. Greet Him, thank Him and listen for Him. Do not grieve Him with unrepented sin or ignore Him in your decisions.",
        "Tanggapin ang Espiritu bilang Persona, hindi lamang kapangyarihan. Batiin Siya, pasalamatan at pakinggan. Huwag Siyang paghinagpisin ng hindi pinagsisihang kasalanan o balewalain sa mga desisyon mo."
      ),
      t(
        "Depend on Him for what you cannot do: courage, wisdom, love for difficult people and words to share Christ.",
        "Umasa sa Kanya sa hindi mo kayang gawin: tapang, karunungan, pag-ibig sa mahihirap mahalin at salita para ibahagi si Cristo."
      ),
    ],
    questions: [
      t("Do I relate to the Spirit as a Person who lives in me?", "Ugnayan ko ba ang Espiritu bilang Persona na nananahan sa akin?"),
      t("Does my sense of conviction lead me toward Jesus or away from Him?", "Ang pagkumbinsi ba sa akin ay humahantong kay Hesus o palayo sa Kanya?"),
      t("In what area am I trying to live by my own strength?", "Sa anong bahagi ako nabubuhay sa sarili kong lakas?"),
      t("When did I last sense the Spirit prompting me, and how did I respond?", "Kailan ko huling naramdaman ang udyok ng Espiritu, at paano ako tumugon?"),
    ],
    actions: [
      t("Begin each day this week with a short prayer: \"Holy Spirit, lead me today.\"", "Simulan ang bawat araw ngayong linggo sa maikling panalangin: \"Banal na Espiritu, gabayan Mo ako ngayon.\""),
      t("Read John 14-16 and underline everything the Spirit does.", "Basahin ang Juan 14-16 at salungguhitan ang lahat ng ginagawa ng Espiritu."),
      t("Obey one prompting this week: encourage someone, pray for someone or share your faith.", "Sundin ang isang udyok ngayong linggo: palakasin ang loob ng isang tao, ipanalangin siya o ibahagi ang pananampalataya."),
    ],
    prayer: t(
      "Holy Spirit, thank You for living in me. Forgive me for ignoring You and for living on my own strength. Convict me gently, guide me into truth and glorify Jesus in my life. Give me power to be a witness at home, at work and wherever You send me. Teach me to hear Your voice and obey. Be my Helper, my Comforter and my guide. I welcome You today. In the name of Jesus, Amen.",
      "Banal na Espiritu, salamat po na nananahan Ka sa akin. Patawarin Mo ako sa pagpapabaya sa Iyo at pamumuhay sa sarili kong lakas. Kumbinsihin Mo ako nang magiliw, gabayan Mo ako sa katotohanan at luwalhatiin Mo si Hesus sa buhay ko. Bigyan Mo ako ng kapangyarihang maging saksi sa bahay, trabaho at saan Mo man ako suguin. Turuan Mo akong marinig ang Iyong tinig at sumunod. Ikaw ang aking Katulong, Mang-aaliw at gabay. Tinatanggap Kita ngayon. Sa pangalan ni Hesus, Amen."
    ),
  },
  "filled-with-the-spirit": {
    revelation: t(
      "Being filled with the Spirit is not a one-time spiritual high but a daily surrender that lets Him fill every room of your life.",
      "Ang pagiging puspos ng Espiritu ay hindi minsanang espirituwal na kasiglahan kundi araw-araw na pagsuko na hinahayaan Siyang punuin ang bawat silid ng buhay mo."
    ),
    mainTruth: t(
      "\"Do not get drunk on wine, which leads to debauchery. Instead, be filled with the Spirit, speaking to one another with psalms, hymns and songs from the Spirit\" (Ephesians 5:18-19). The command is present and continuous: keep on being filled. In Acts 4:31, after the believers prayed, \"they were all filled with the Holy Spirit and spoke the word of God boldly.\" And Paul concludes, \"Since we live by the Spirit, let us keep in step with the Spirit\" (Galatians 5:25). Fullness shows up as worship, thankfulness, submission, courage and character.",
      "\"Huwag kayong malasing sa alak, na nagdadala sa kasamaan. Sa halip, mapuspos kayo ng Espiritu, na nagsasalita sa isa't isa ng mga awit, himno at awiting espirituwal\" (Efeso 5:18-19). Ang utos ay nasa kasalukuyan at tuloy-tuloy: patuloy na mapuspos. Sa Gawa 4:31, pagkatapos manalangin ng mga mananampalataya, \"silang lahat ay napuspos ng Banal na Espiritu at buong tapang na nagsalita ng salita ng Diyos.\" At ang wika ni Pablo, \"Yamang nabubuhay tayo sa Espiritu, lumakad din tayo ayon sa Espiritu\" (Galacia 5:25). Lumilitaw ang kapuspusan bilang pagsamba, pasasalamat, pagpapasakop, tapang at karakter."
    ),
    insight: [
      t(
        "The comparison with wine is revealing. Wine controls a person from the inside, changing speech and behavior. Paul says: let the Spirit be the One who controls you instead. The point is not an emotional peak but who is in charge. Many believers have the Spirit, since every believer is sealed with Him, but are not filled, because other things are in control: worry, anger, busyness, bitterness.",
        "Nagbubunyag ang paghahambing sa alak. Kinokontrol ng alak ang tao mula sa loob at binabago ang salita at kilos. Sabi ni Pablo: hayaang ang Espiritu ang kumontrol sa iyo. Hindi ang punto ang emosyonal na rurok kundi kung sino ang may hawak. Maraming mananampalataya ang may Espiritu, dahil bawat mananampalataya ay tinatakan Niya, pero hindi puspos, dahil ibang bagay ang may kontrol: pag-aalala, galit, pagiging abala, hinanakit."
      ),
      t(
        "Notice what fullness looks like in Acts 4: not a private feeling but boldness for the mission, with threats around them. Fullness is for witness. And Galatians 5:25 gives the practical rhythm: keep in step, one step at a time. Believers differ on whether fullness is a distinct experience or a continual yielding; all agree that we need Him daily, and that His fruit, not just His gifts, proves His fullness.",
        "Pansinin kung paano ang kapuspusan sa Gawa 4: hindi pribadong damdamin kundi tapang para sa misyon, kahit may banta sa paligid. Ang kapuspusan ay para sa pagsaksi. At ibinibigay ng Galacia 5:25 ang praktikal na ritmo: sumabay, isang hakbang bawat panahon. Magkaiba ang paniniwala ng mga mananampalataya kung ang kapuspusan ay hiwalay na karanasan o patuloy na pagsuko; lahat ay sumasang-ayon na kailangan natin Siya araw-araw, at ang Kanyang bunga, hindi lang ang kaloob, ang patunay ng Kanyang kapuspusan."
      ),
    ],
    life: [
      t(
        "Picture a tricycle driver in the morning rush, tired and angry at the traffic. Before he starts, he whispers, \"Spirit, fill me. I give You my temper and my tongue.\" He does not become perfect, but he notices himself speaking to the passenger with kindness, and humming a worship song. A filled life sounds like gratitude and looks like gentleness, even in traffic.",
        "Isipin ang tricycle driver sa rush hour ng umaga, pagod at galit sa trapiko. Bago magsimula, bumubulong siya, \"Espiritu, punuin Mo ako. Ibinibigay ko sa Iyo ang init ng ulo at dila ko.\" Hindi siya nagiging perpekto, pero napapansin niyang mabait siyang nakikipag-usap sa pasahero at humuhuni ng awit ng pagsamba. Ang buhay na puspos ay may tunog ng pasasalamat at hitsura ng kahinahunan, kahit sa trapiko."
      ),
      t(
        "Practice fullness: confess what is in control, yield it, ask in faith, then walk in the next step of obedience. Pray as the early believers did: \"Enable your servants to speak your word with great boldness\" (Acts 4:29).",
        "Sanayin ang kapuspusan: ipagtapat kung ano ang may kontrol, isuko ito, humingi nang may pananampalataya, at lumakad sa susunod na hakbang ng pagsunod. Manalangin gaya ng mga unang mananampalataya: \"Bigyan Mo ang Iyong mga lingkod na maipahayag ang Iyong salita nang buong tapang\" (Gawa 4:29)."
      ),
    ],
    twist: t(
      "We imagine that being filled means getting more of the Spirit. In truth, He is a Person, so you cannot get a bigger portion of Him; the question is whether He gets more of you. Fullness is not Him filling a small container; it is you opening every door in the house. The Kingdom twist: the way up is down. The more you empty yourself, the more He can fill.",
      "Akala natin ang kapuspusan ay pagkuha ng mas maraming Espiritu. Sa totoo, Persona Siya, kaya hindi ka makakakuha ng mas malaking bahagi Niya; ang tanong ay kung makukuha Niya ang mas marami sa iyo. Hindi Siya pumupuno ng maliit na lalagyan; ikaw ang nagbubukas ng bawat pinto ng bahay. Ang Kaharian twist: pababa ang daan paitaas. Kapag mas inalis mo ang sarili, mapupunan ka Niya."
    ),
    confirm: [
      t("Acts 2:4: all were filled with the Holy Spirit and began to speak.", "Gawa 2:4: silang lahat ay napuspos ng Banal na Espiritu at nagsimulang magsalita."),
      t("Luke 11:13: the Father gives the Holy Spirit to those who ask.", "Lucas 11:13: ibinibigay ng Ama ang Banal na Espiritu sa mga humihingi."),
      t("Galatians 5:22-23: the fruit of the Spirit grows where He is in control.", "Galacia 5:22-23: lumalago ang bunga ng Espiritu kung nasaan Siya ang may kontrol."),
      t("Acts 6:3: the first deacons were men full of the Spirit and wisdom.", "Gawa 6:3: ang mga unang diakono ay mga taong puspos ng Espiritu at karunungan."),
    ],
    heart: [
      t(
        "Ask yourself honestly: what is controlling my reactions, my emotions and my schedule? Confess and surrender it, and ask for a fresh filling today.",
        "Tanungin ang sarili nang tapat: ano ang kumokontrol sa reaksyon, emosyon at iskedyul ko? Ipagtapat at isuko ito, at humingi ng bagong pagpuno ngayon."
      ),
      t(
        "Seek the Giver more than the gifts. Welcome the Spirit's fruit of love and self-control, and the boldness to witness, as proof of His presence.",
        "Hanapin ang Nagbibigay kaysa sa mga kaloob. Tanggapin ang bunga ng Espiritu na pag-ibig at pagpipigil sa sarili, at ang tapang magsaksi, bilang patunay ng Kanyang presensya."
      ),
    ],
    questions: [
      t("What is really in control of me right now: worry, anger, busyness or the Spirit?", "Ano ang talagang may kontrol sa akin ngayon: pag-aalala, galit, pagiging abala o ang Espiritu?"),
      t("Is there a room in my life I have kept locked from Him?", "May silid ba sa buhay ko na ikinandado ko mula sa Kanya?"),
      t("Do I see more of the Spirit's fruit in my life this year than last?", "Mas marami ba akong nakikitang bunga ng Espiritu sa buhay ko ngayong taon kaysa noong nakaraan?"),
      t("Do I ask for His filling in faith, or only when I am in trouble?", "Humihingi ba ako ng Kanyang pagpuno nang may pananampalataya, o kapag may problema lang?"),
    ],
    actions: [
      t("Pray Luke 11:13 and Ephesians 5:18 each morning this week.", "Ipanalangin ang Lucas 11:13 at Efeso 5:18 tuwing umaga ngayong linggo."),
      t("Replace one complaint or worry session with a worship song or thanksgiving.", "Palitan ang isang oras ng reklamo o alala ng awit ng pagsamba o pasasalamat."),
      t("Ask for boldness (Acts 4:29) and take one step to share Christ or encourage someone.", "Humingi ng tapang (Gawa 4:29) at gumawa ng isang hakbang para ibahagi si Cristo o palakasin ang loob ng isang tao."),
    ],
    prayer: t(
      "Holy Spirit, I open every room of my life to You. Forgive me for the things I let rule me: worry, anger, pride and busyness. Fill me afresh today. Control my tongue, my thoughts and my choices. Give me a heart full of worship and thanks, courage to witness and the fruit of Christ's character. Teach me to walk in step with You. I want more of You and less of me. In Jesus' name, Amen.",
      "Banal na Espiritu, binubuksan ko ang bawat silid ng buhay ko sa Iyo. Patawarin Mo ako sa mga bagay na hinayaan kong mamuno sa akin: pag-aalala, galit, kayabangan at pagiging abala. Punuin Mo ako ng bago ngayon. Kontrolin Mo ang dila, isip at pasya ko. Bigyan Mo ako ng pusong puno ng pagsamba at pasasalamat, tapang magsaksi at bunga ng karakter ni Cristo. Turuan Mo akong lumakad nang kasabay Mo. Mas gusto ko ang Ikaw at mas kaunti ako. Sa pangalan ni Hesus, Amen."
    ),
  },
  "what-is-the-church": {
    revelation: t(
      "The Church is not a building you attend; it is a family of living stones, and Jesus Himself is building it, with you in it.",
      "Ang Simbahan ay hindi gusaling pinupuntahan mo; ito ay pamilya ng mga buhay na bato, at si Hesus mismo ang nagtatayo nito, kasama ka."
    ),
    mainTruth: t(
      "When Peter confessed, \"You are the Messiah, the Son of the living God,\" Jesus replied, \"I will build my church, and the gates of Hades will not overcome it\" (Matthew 16:16-18). The Church belongs to Christ and is built on the truth about Him. Paul says believers are \"no longer foreigners and strangers, but fellow citizens with God's people and also members of his household,\" with Christ Jesus as the cornerstone (Ephesians 2:19-22). And Peter calls us \"living stones... being built into a spiritual house\" (1 Peter 2:4-5).",
      "Nang ipahayag ni Pedro, \"Ikaw ang Cristo, ang Anak ng buhay na Diyos,\" sumagot si Hesus, \"Itatayo Ko ang Aking iglesia, at hindi ito mananaig ng mga pintuan ng Hades\" (Mateo 16:16-18). Ang Iglesia ay kay Cristo at itinatayo sa katotohanan tungkol sa Kanya. Sabi ni Pablo, ang mga mananampalataya ay \"hindi na mga dayuhan at banyaga, kundi kapwa mamamayan ng bayan ng Diyos at mga kasapi ng Kanyang sambahayan,\" at si Cristo Hesus ang batong panulukan (Efeso 2:19-22). At tinatawag tayo ni Pedro na \"mga buhay na bato... na itinatayo bilang espirituwal na bahay\" (1 Pedro 2:4-5)."
    ),
    insight: [
      t(
        "The Greek word for church, ekklesia, means \"called-out assembly\": people, not property. Many believers say \"I go to church\" as if it were a location. But the New Testament says \"you are the church.\" A building can burn down and the Church remains. The Church is also not a club of the perfect; it is a hospital of the forgiven, where ex-fishermen, ex-tax collectors and ex-persecutors sit side by side.",
        "Ang salitang Griyego para sa iglesia, ekklesia, ay \"pulong ng mga tinawag\": tao, hindi ari-arian. Maraming mananampalataya ang nagsasabing \"nagsisimba ako\" na parang lugar ito. Pero sinasabi ng Bagong Tipan na \"kayo ang iglesia.\" Puwedeng masunog ang gusali at mananatili ang Iglesia. Hindi rin ito samahan ng mga perpekto; ito ay ospital ng mga pinatawad, kung saan magkatabi ang dating mangingisda, dating maniningil ng buwis at dating mang-uusig."
      ),
      t(
        "A stone alone is not a house. A living stone needs to be placed next to others, held together by the cornerstone. That is why the Christian life was never designed to be lived alone. The Spirit-gifted body needs every part (1 Corinthians 12), and your absence leaves a gap that nobody else can fill exactly. Where Christians are connected, they are strengthened; where they isolate, they drift.",
        "Ang bato lang ay hindi bahay. Ang buhay na bato ay kailangang ilagay sa tabi ng iba, pinagbubuklod ng batong panulukan. Kaya hindi dinisenyo ang buhay-Kristiyano para mag-isa. Kailangan ng katawang may kaloob ng Espiritu ang bawat bahagi (1 Corinto 12), at ang pagkawala mo ay nag-iiwan ng puwang na hindi eksaktong mapupunan ng iba. Kung saan nakaugnay ang mga Kristiyano, lumalakas sila; kung saan nag-iisa, naaanod."
      ),
    ],
    life: [
      t(
        "For an OFW far from home, the church is often the first family. Maribel arrived in Abu Dhabi knowing no one. A coworker invited her to a small fellowship in a rented room. That first Friday, someone brought food, someone prayed for her mother's surgery and someone asked, \"Kumusta ka talaga?\" She said later, \"The church found me before I found my way.\" The family of God is not limited by borders.",
        "Para sa OFW na malayo sa tahanan, ang simbahan ay madalas na unang pamilya. Dumating si Maribel sa Abu Dhabi na walang kakilala. Inanyayahan siya ng katrabaho sa maliit na pagtitipon sa inuupahang kuwarto. Sa unang Biyernes na iyon, may nagdala ng pagkain, may nanalangin para sa operasyon ng nanay niya at may nagtanong, \"Kumusta ka talaga?\" Sabi niya pagkatapos, \"Nahanap ako ng simbahan bago ko natagpuan ang daan ko.\" Hindi nalilimitahan ng hangganan ang pamilya ng Diyos."
      ),
      t(
        "Commit to a local fellowship: worship, give, serve and be known. Do not wait for a perfect church; be a living stone in an imperfect one. And when you are hurt by Christians, remember that Jesus is still the Head, and He is patient with all of us.",
        "Mag-commit sa lokal na pagtitipon: sumamba, magbigay, maglingkod at makilala. Huwag maghintay ng perpektong simbahan; maging buhay na bato sa di-perpektong simbahan. At kapag nasaktan ka ng mga Kristiyano, tandaan na si Hesus pa rin ang Ulo, at matiyaga Siya sa ating lahat."
      ),
    ],
    twist: t(
      "We often ask, \"What can the church give me?\" The Kingdom turns it around: you are part of what the church gives to the world. And the gates of Hades, the powers of death and darkness, are not attacking a fortress; they are the ones on defense. The Church advances, and nothing can stop what Jesus builds, not persecution, scattering or our own weaknesses.",
      "Madalas nating itanong, \"Ano ang maibibigay ng simbahan sa akin?\" Binabaligtad ito ng Kaharian: ikaw ay bahagi ng ibinibigay ng simbahan sa mundo. At ang mga pintuan ng Hades, ang kapangyarihan ng kamatayan at kadiliman, ay hindi umaatake sa kuta; sila ang nasa depensa. Sumusulong ang Iglesia, at walang makakapigil sa itinatayo ni Hesus, hindi pag-uusig, pagkakawatak-watak o ang sarili nating kahinaan."
    ),
    confirm: [
      t("Acts 2:42-47: the first church devoted itself to teaching, fellowship, bread and prayer.", "Gawa 2:42-47: ang unang iglesia ay nagtalaga sa turo, pakikisama, paghahati ng tinapay at panalangin."),
      t("1 Corinthians 12:12-27: one body, many parts, each needed.", "1 Corinto 12:12-27: isang katawan, maraming bahagi, kailangan ang bawat isa."),
      t("Hebrews 10:24-25: do not give up meeting together; encourage one another.", "Hebreo 10:24-25: huwag tigilan ang pagtitipon; magpalakasan ng loob."),
      t("Ephesians 4:11-16: Christ gave leaders to equip His people to grow together.", "Efeso 4:11-16: nagbigay si Cristo ng mga lider upang ihanda ang Kanyang bayan na lumago nang sama-sama."),
    ],
    heart: [
      t(
        "Let go of consumer thinking about church. Ask not only \"Did I enjoy it?\" but \"Whom did I serve and encourage?\" Repent of isolation and of criticizing from the outside.",
        "Bitawan ang pag-iisip na parang kustomer sa simbahan. Itanong hindi lang \"Nasiyahan ba ako?\" kundi \"Sino ang pinaglingkuran at pinalakas ko ang loob?\" Magsisi sa pag-iisa at pamumuna mula sa labas."
      ),
      t(
        "Love the people God put near you, even the difficult ones. Their rough edges are tools in His hand to shape you.",
        "Mahalin ang mga taong inilagay ng Diyos malapit sa iyo, kahit ang mahirap pakisamahan. Ang magaspang nilang gilid ay kasangkapan sa kamay Niya para hubugin ka."
      ),
    ],
    questions: [
      t("Do I see church as a place I attend or a family I belong to?", "Tinitingnan ko ba ang simbahan bilang lugar na pinupuntahan o pamilyang kinabibilangan?"),
      t("Where am I connected, serving and known?", "Saan ako konektado, naglilingkod at kilala?"),
      t("Is there someone in my church I need to forgive or reach out to?", "May tao ba sa simbahan na kailangan kong patawarin o lapitan?"),
      t("What gift has God given me for the benefit of the body?", "Anong kaloob ang ibinigay sa akin ng Diyos para sa kapakinabangan ng katawan?"),
    ],
    actions: [
      t("Attend a local fellowship or small group this week and stay afterward to talk to someone new.", "Dumalo sa lokal na pagtitipon o maliit na grupo ngayong linggo at manatili pagkatapos para kausapin ang bago."),
      t("Offer to serve in one practical way: welcome, set up, prayer or meals.", "Mag-alok na maglingkod sa isang praktikal na paraan: pagsalubong, pag-aayos, panalangin o pagkain."),
      t("Pray for your pastor and leaders by name, and encourage one of them.", "Ipanalangin ang pastor at mga lider sa pangalan, at palakasin ang loob ng isa sa kanila."),
    ],
    prayer: t(
      "Lord Jesus, thank You for building Your Church and for placing me in it. Forgive me for treating it like a service to attend and not a family to love. Connect me to a fellowship where I can give, grow and be known. Heal the hurts I have carried from people and make me a living stone that supports others. Build Your Church in my city and nation, and let the gates of hell never prevail. In Your name, Amen.",
      "Panginoong Hesus, salamat po sa pagtatayo Mo ng Iyong Iglesia at paglalagay sa akin dito. Patawarin Mo ako sa pagturing dito na serbisyo lang na dinadaluhan at hindi pamilyang iniibig. Ikonekta Mo ako sa pagtitipon kung saan maaari akong magbigay, lumago at makilala. Pagalingin Mo ang mga sugat na dala ko mula sa tao at gawin akong buhay na batong sumusuporta sa iba. Itayo Mo ang Iyong Iglesia sa lungsod at bansa ko, at huwag manaig ang mga pintuan ng impiyerno. Sa Iyong pangalan, Amen."
    ),
  },
  "loving-means-obeying": {
    revelation: t(
      "Love for Jesus is proved not by how loudly you sing but by how quickly you obey, and obedience is where He reveals Himself to you.",
      "Ang pag-ibig kay Hesus ay napapatunayan hindi sa lakas ng awit kundi sa bilis ng pagsunod, at sa pagsunod Niya ipinakikilala ang Sarili Niya sa iyo."
    ),
    mainTruth: t(
      "\"Whoever has my commands and keeps them is the one who loves me. The one who loves me will be loved by my Father, and I too will love them and show myself to them\" (John 14:21). John adds, \"Whoever claims to live in him must live as Jesus did\" (1 John 2:6). And Jesus warns, \"Why do you call me, 'Lord, Lord,' and do not do what I say?\" (Luke 6:46). Obedience is not the price of His love; it is the fruit and proof of ours.",
      "\"Ang may mga utos Ko at tumutupad ng mga ito, siya ang umiibig sa Akin. At ang umiibig sa Akin ay iibigin ng Aking Ama, at iibigin Ko rin siya at ipakikilala Ko ang Aking Sarili sa kanya\" (Juan 14:21). Dagdag ni Juan, \"Ang sinumang nagsasabing nananatili sa Kanya ay dapat lumakad gaya ng paglakad Niya\" (1 Juan 2:6). At nagbabala si Hesus, \"Bakit ninyo Ako tinatawag na 'Panginoon, Panginoon,' ngunit hindi ninyo ginagawa ang sinasabi Ko?\" (Lucas 6:46). Ang pagsunod ay hindi bayad para sa Kanyang pag-ibig; ito ang bunga at patunay ng ating pag-ibig."
    ),
    insight: [
      t(
        "We sometimes set love and obedience against each other, as if love is the warm feeling and obedience is cold duty. Jesus joins them. In the upper room He says it again and again: if you love Me, keep My commands (John 14:15, 21, 23). Notice the reward: the one who obeys experiences deeper intimacy, because Jesus \"will show himself\" to them. Disobedience dulls our sense of His presence; obedience clears the glass.",
        "Minsan pinaglalaban natin ang pag-ibig at pagsunod, na parang ang pag-ibig ay mainit na damdamin at ang pagsunod ay malamig na tungkulin. Pinagsasama ito ni Hesus. Sa silid sa itaas, paulit-ulit Niyang sinasabi: kung iniibig ninyo Ako, sundin ninyo ang Aking mga utos (Juan 14:15, 21, 23). Pansinin ang gantimpala: ang sumusunod ay nakararanas ng mas malalim na pagiging malapit, dahil \"ipakikilala\" ni Hesus ang Sarili sa kanya. Pinapalabo ng pagsuway ang pakiramdam natin sa Kanyang presensya; nililinis ng pagsunod ang salamin."
      ),
      t(
        "The parable of the two builders (Luke 6:47-49) is not about two kinds of hearers but about hearing and doing. Both builders heard; only one put it into practice. Both houses faced the storm; one stood. Many believers fill notebooks with sermon notes and wonder why their lives collapse under pressure. The foundation is not knowledge but obedience.",
        "Ang talinghaga tungkol sa dalawang magtatayo (Lucas 6:47-49) ay hindi tungkol sa dalawang uri ng nakikinig kundi sa pakikinig at paggawa. Parehong nakinig; isa lang ang nagsabuhay. Parehong hinarap ng dalawang bahay ang bagyo; isa ang nanatili. Maraming mananampalataya ang pinupuno ang notebook ng tala sa sermon at nagtataka kung bakit bumabagsak ang buhay nila sa presyon. Ang pundasyon ay hindi kaalaman kundi pagsunod."
      ),
    ],
    life: [
      t(
        "Erwin, a seafarer, prayed for months for God to give him a clear sign about whether to forgive his brother who had cheated him. One night, reading John 14, he realized he already knew what Jesus said: forgive. He had been waiting for a feeling while heaven was waiting for a yes. He sent a message that night. \"I felt closer to God than I had in years,\" he said. Obedience, not a feeling, opened the door.",
        "Si Erwin, isang seafarer, ay ilang buwang nanalangin na bigyan siya ng Diyos ng malinaw na tanda kung patatawarin ang kapatid niyang nandaya sa kanya. Isang gabi, habang nagbabasa ng Juan 14, napagtanto niyang alam na niya ang sinabi ni Hesus: magpatawad. Naghihintay siya ng damdamin habang naghihintay ang langit ng oo. Nagpadala siya ng mensahe nang gabing iyon. \"Mas malapit ako sa Diyos kaysa sa mga nakaraang taon,\" sabi niya. Ang pagsunod, hindi ang damdamin, ang nagbukas ng pinto."
      ),
      t(
        "Ask: what is the last thing God clearly told me that I have not done? Often it is small: apologize, give, stop a habit, speak to someone. Start there, and do it today, not next week.",
        "Itanong: ano ang huling malinaw na sinabi ng Diyos na hindi ko pa ginagawa? Madalas maliit lang: humingi ng tawad, magbigay, itigil ang gawi, kausapin ang isang tao. Magsimula roon, at gawin ngayon, hindi sa susunod na linggo."
      ),
    ],
    twist: t(
      "We think obedience makes us slaves. Jesus says it makes us friends: \"You are my friends if you do what I command\" (John 15:14). In the Kingdom, the people closest to the King are not those who shout the most but those who do what He asks. And His commands are not heavy (1 John 5:3); the heavy load is living apart from them.",
      "Akala natin ang pagsunod ay ginagawa tayong alipin. Sabi ni Hesus, ginagawa tayong kaibigan: \"Kayo ay Aking mga kaibigan kung ginagawa ninyo ang iniuutos Ko\" (Juan 15:14). Sa Kaharian, ang pinakamalapit sa Hari ay hindi yaong pinakamalakas sumigaw kundi yaong gumagawa ng hinihiling Niya. At hindi mabigat ang Kanyang mga utos (1 Juan 5:3); ang mabigat ay ang pamumuhay na hiwalay sa mga ito."
    ),
    confirm: [
      t("John 15:10: if you keep my commands, you will remain in my love.", "Juan 15:10: kung susundin ninyo ang Aking mga utos, mananatili kayo sa Aking pag-ibig."),
      t("James 1:22: do not merely listen to the word; do what it says.", "Santiago 1:22: huwag lang makinig sa salita; gawin ang sinasabi nito."),
      t("1 Samuel 15:22: to obey is better than sacrifice.", "1 Samuel 15:22: ang pagsunod ay higit na mabuti kaysa hain."),
      t("Matthew 7:21: only those who do the will of my Father will enter the kingdom.", "Mateo 7:21: ang gumagawa lamang ng kalooban ng Aking Ama ang papasok sa kaharian."),
    ],
    heart: [
      t(
        "Repent of the gap between your worship and your walk. Do not defend it; bring it to Jesus and ask Him for a soft heart that says yes quickly.",
        "Magsisi sa agwat ng pagsamba at paglakad mo. Huwag itong ipagtanggol; dalhin kay Hesus at humingi ng malambot na pusong mabilis magsabi ng oo."
      ),
      t(
        "Obey out of love, not fear. Remember that the Spirit gives the power to obey, and that grace lifts you up after you stumble.",
        "Sumunod dahil sa pag-ibig, hindi takot. Tandaan na ang Espiritu ang nagbibigay ng kapangyarihang sumunod, at ibinabangon ka ng biyaya pagkatapos madapa."
      ),
    ],
    questions: [
      t("What has Jesus clearly told me that I have not yet done?", "Ano ang malinaw na sinabi sa akin ni Hesus na hindi ko pa nagagawa?"),
      t("Do I treat obedience as a burden or as the way to His presence?", "Itinuturing ko ba ang pagsunod na pasanin o daan tungo sa Kanyang presensya?"),
      t("Am I more of a hearer or a doer of the word?", "Mas tagapakinig ba ako o tagagawa ng salita?"),
      t("What delayed obedience is dulling my sense of God's nearness?", "Anong ipinagpapaliban kong pagsunod ang nagpapalabo sa pakiramdam ko ng kalapitan ng Diyos?"),
    ],
    actions: [
      t("Write down the one thing God has told you to do and do it within 24 hours.", "Isulat ang isang bagay na sinabi ng Diyos na gawin at gawin ito sa loob ng 24 oras."),
      t("Read the Sermon on the Mount (Matthew 5-7) and choose one command to practice this week.", "Basahin ang Sermon sa Bundok (Mateo 5-7) at pumili ng isang utos na isasabuhay ngayong linggo."),
      t("Ask a friend to check in on your obedience.", "Hilingin sa kaibigan na kumustahin ang pagsunod mo."),
    ],
    prayer: t(
      "Lord Jesus, I say that I love You. Forgive me for the times my life says something different. Soften my heart and show me where I have delayed obeying You. By Your Spirit, give me the strength to do what You ask, quickly and joyfully. I want to know You, to see You and to walk as You walked. Make me a doer of Your word and not only a hearer. In Your name I pray, Amen.",
      "Panginoong Hesus, sinasabi kong iniibig Kita. Patawarin Mo ako sa mga panahong iba ang sinasabi ng buhay ko. Palambutin Mo ang puso ko at ipakita kung saan ako nagpaliban ng pagsunod sa Iyo. Sa pamamagitan ng Iyong Espiritu, bigyan Mo ako ng lakas na gawin ang hinihiling Mo, nang mabilis at masaya. Nais Kitang makilala, makita at lumakad gaya ng paglakad Mo. Gawin Mo akong tagagawa ng Iyong salita at hindi lang tagapakinig. Sa Iyong pangalan, Amen."
    ),
  },

  "persistent-prayer": {
    revelation: t(
      "Delay is not denial; God often uses the waiting to build the one who is praying before He answers the prayer.",
      "Ang pagkaantala ay hindi pagtanggi; madalas, ang paghihintay ang ginagamit ng Diyos para hubugin ang nananalangin bago Niya sagutin ang panalangin."
    ),
    mainTruth: t(
      "Jesus told the parable of the persistent widow \"to show them that they should always pray and not give up\" (Luke 18:1). If a judge who neither feared God nor cared about people finally gave justice to a woman who kept coming, how much more will our loving Father respond to His own children (Luke 18:6-8; 11:9-13). The point is not that God is reluctant; it is that He is good, and that faith keeps knocking until the door opens. \"Devote yourselves to prayer, being watchful and thankful\" (Colossians 4:2).",
      "Isinalaysay ni Hesus ang talinghaga ng matiyagang balo \"upang ipakita na dapat silang laging manalangin at huwag manghinawa\" (Lucas 18:1). Kung ang hukom na hindi natatakot sa Diyos at walang malasakit sa tao ay nagbigay rin ng katarungan sa babaeng paulit-ulit na lumalapit, gaano pa kaya ang mapagmahal nating Ama sa Kanyang mga anak (Lucas 18:6-8; 11:9-13). Hindi ang punto na atubili ang Diyos; ang punto ay mabuti Siya, at ang pananampalataya ay patuloy na kumakatok hanggang bumukas ang pinto. \"Magpakatatag kayo sa pananalangin, na may pagbabantay at pasasalamat\" (Colosas 4:2)."
    ),
    insight: [
      t(
        "Notice what Jesus contrasts. He is not comparing God to the unjust judge; He is contrasting them. The judge had to be worn down. God does not. Our persistence is not meant to change God's mind but to deepen our hearts. Many believers pray once or twice, feel nothing, and quietly conclude, \"Maybe it is not His will.\" Sometimes that is wisdom; very often it is just tiredness wearing the clothes of humility.",
        "Pansinin kung ano ang pinaghahambing ni Hesus. Hindi Niya inihahalintulad ang Diyos sa di-makatarungang hukom; ipinagkokontra Niya sila. Ang hukom ay kailangang pagurin. Ang Diyos ay hindi. Ang ating pagtitiyaga ay hindi para baguhin ang isip ng Diyos kundi para palalimin ang ating puso. Maraming mananampalataya ang nananalangin nang minsan o makalawa, walang nararamdaman, at tahimik na nagsasabi, \"Siguro hindi iyon ang kalooban Niya.\" Minsan karunungan iyon; madalas, pagod lang na nakadamit ng kababaang-loob."
      ),
      t(
        "Look at the friend at midnight in Luke 11. He gets bread not because of friendship alone but because of his bold, shameless asking. Heaven honors holy boldness. And Paul adds two guards to persistence: watchfulness and thankfulness. Watchfulness keeps us alert to how God is already moving; thankfulness keeps our hearts soft while we wait, so persistence does not turn into complaining.",
        "Tingnan ang kaibigan sa hatinggabi sa Lucas 11. Nakakuha siya ng tinapay hindi dahil sa pagkakaibigan lang kundi dahil sa kanyang matapang at walang-hiyang paghingi. Pinararangalan ng langit ang banal na katapangan. At dalawang bantay ang idinagdag ni Pablo sa pagtitiyaga: pagbabantay at pasasalamat. Ang pagbabantay ay nagpapaalerto sa atin kung paano na kumikilos ang Diyos; ang pasasalamat ay nagpapalambot ng puso habang naghihintay, para ang pagtitiyaga ay hindi maging reklamo."
      ),
    ],
    life: [
      t(
        "Aling Nena, a domestic worker in Kuwait, has prayed for eleven years that her husband back home would come to Christ. Some nights she wanted to stop. But she kept a small notebook: \"Asked. Thank You for his job. Asked again.\" One Christmas video call, her husband said quietly, \"Can you pray for me?\" She did not get a thunderclap; she got a door opening that eleven years of knocking had been leaning on.",
        "Si Aling Nena, kasambahay sa Kuwait, ay labing-isang taon nang nananalangin na lumapit kay Cristo ang asawa niya sa Pilipinas. May mga gabing gusto na niyang tumigil. Pero may maliit siyang notebook: \"Humingi. Salamat sa trabaho niya. Humingi ulit.\" Isang Pasko, sa video call, mahinang sinabi ng asawa niya, \"Ipagdasal mo naman ako.\" Hindi kulog ang dumating; isang pintong bumukas na matagal nang sinasandalan ng labing-isang taong pagkatok."
      ),
      t(
        "Think of the jeepney driver who keeps tapping the horn and inching forward in heavy traffic on EDSA. He is not angry; he simply knows the road eventually opens. Prayer needs that kind of stubborn hope. Are you still in the lane, or have you parked and gone home?",
        "Isipin ang tsuper ng jeepney na patuloy na bumubusina at umuusad nang kaunti-kaunti sa mabigat na trapiko sa EDSA. Hindi siya galit; alam lang niyang magbubukas din ang daan. Ganyang matigas na pag-asa ang kailangan ng panalangin. Nasa linya ka pa ba, o nag-park ka na at umuwi?"
      ),
    ],
    twist: t(
      "The Kingdom twist: the widow had no power, no money and no status, and yet she is the hero of the story. In God's Kingdom, weakness that keeps coming is stronger than strength that gives up. Your helplessness is not a disqualification; it is the very posture heaven responds to. Jesus ends with a question, \"When the Son of Man comes, will He find faith on the earth?\" (Luke 18:8). Persistent prayer is how faith stays alive.",
      "Ang twist ng Kaharian: ang balo ay walang kapangyarihan, pera o katayuan, pero siya ang bayani ng kuwento. Sa Kaharian ng Diyos, mas malakas ang kahinaang patuloy na lumalapit kaysa lakas na sumusuko. Ang kawalan mo ng magagawa ay hindi diskwalipikasyon; iyon mismo ang tindig na tinutugon ng langit. Nagtapos si Hesus sa tanong, \"Pagbalik ng Anak ng Tao, makakatagpo kaya Siya ng pananampalataya sa lupa?\" (Lucas 18:8). Ang matiyagang panalangin ang nagpapanatiling buhay sa pananampalataya."
    ),
    confirm: [
      t("Genesis 32:26: Jacob wrestles and says, \"I will not let You go unless You bless me.\"", "Genesis 32:26: nakipagbuno si Jacob at sinabi, \"Hindi Kita pakakawalan hangga't hindi Mo ako pinagpapala.\""),
      t("1 Samuel 1:10-20: Hannah pours out her heart year after year and Samuel is born.", "1 Samuel 1:10-20: ibinuhos ni Ana ang puso niya taon-taon at isinilang si Samuel."),
      t("Acts 12:5-12: the church prays earnestly and Peter walks out of prison.", "Gawa 12:5-12: taimtim na nanalangin ang iglesia at lumabas si Pedro sa bilangguan."),
      t("James 5:16-18: the prayer of a righteous person is powerful; Elijah prayed again and again for rain.", "Santiago 5:16-18: makapangyarihan ang panalangin ng matuwid; paulit-ulit na nanalangin si Elias para sa ulan."),
    ],
    heart: [
      t(
        "Trade the question \"Why is God slow?\" for \"What is God doing in me while I wait?\" Let patience grow where complaint used to live.",
        "Palitan ang tanong na \"Bakit mabagal ang Diyos?\" ng \"Ano ang ginagawa ng Diyos sa akin habang naghihintay ako?\" Hayaang tumubo ang pasensya kung saan dating nakatira ang reklamo."
      ),
      t(
        "Become a person of prayer, not only a person with prayer requests. Keep coming, keep thanking, keep watching, and trust the Father's timing and goodness.",
        "Maging taong mapanalangin, hindi lang taong may listahan ng hiling. Patuloy na lumapit, magpasalamat, magbantay, at magtiwala sa panahon at kabutihan ng Ama."
      ),
    ],
    questions: [
      t("What prayer have you quietly stopped praying, and why?", "Anong panalangin ang tahimik mong itinigil, at bakit?"),
      t("Do you tend to give up because of doubt about God's goodness or because of tiredness?", "Sumusuko ka ba dahil sa pagdududa sa kabutihan ng Diyos o dahil sa pagod?"),
      t("What are you thankful for right now that could carry you through the waiting?", "Ano ang pinasasalamatan mo ngayon na maaaring magdala sa iyo sa paghihintay?"),
      t("Who could pray with you so you are not waiting alone?", "Sino ang maaaring manalangin kasama mo para hindi ka mag-isang naghihintay?"),
    ],
    actions: [
      t("Write down one prayer you gave up on and pray it again today.", "Isulat ang isang panalanging sinukuan mo at ipanalangin itong muli ngayon."),
      t("Start a simple prayer notebook with the date asked and space for the date answered.", "Magsimula ng simpleng prayer notebook na may petsa ng paghingi at espasyo para sa petsa ng sagot."),
      t("Ask a friend or your AG to agree with you in prayer for that need every week.", "Hilingin sa isang kaibigan o sa iyong AG na makiisa sa iyo sa panalangin para sa pangangailangang iyon bawat linggo."),
    ],
    prayer: t(
      "Father, You are not like the unjust judge; You are good, and You hear me. Forgive me for the prayers I abandoned when answers were slow. Teach me to keep asking, seeking and knocking with a watchful and thankful heart. While I wait, shape my character and keep my faith alive until Jesus returns. I bring You again the request I let go of, and I trust Your love and Your timing. In Jesus' name, Amen.",
      "Ama, hindi Ka tulad ng di-makatarungang hukom; mabuti Ka, at dinirinig Mo ako. Patawarin Mo ako sa mga panalangin kong iniwan nang mabagal ang sagot. Turuan Mo akong patuloy na humingi, humanap at kumatok nang may pagbabantay at pasasalamat. Habang naghihintay ako, hubugin Mo ang aking pagkatao at panatilihing buhay ang aking pananampalataya hanggang sa pagbabalik ni Hesus. Muli kong dinadala sa Iyo ang hiling na binitawan ko, at nagtitiwala ako sa Iyong pag-ibig at panahon. Sa pangalan ni Hesus, Amen."
    ),
  },

  "what-is-faith": {
    revelation: t(
      "Faith is not believing harder; it is trusting Someone good enough to obey before you can see.",
      "Ang pananampalataya ay hindi ang mas matinding paniniwala; ito ay pagtitiwala sa Isang sapat na mabuti para sundin mo bago mo pa makita."
    ),
    mainTruth: t(
      "\"Now faith is confidence in what we hope for and assurance about what we do not see\" (Hebrews 11:1). Abraham \"obeyed and went, even though he did not know where he was going\" (Hebrews 11:8). Faith always has an object: it is anchored in the character of the God who calls. And it has a source: \"Faith comes from hearing the message, and the message is heard through the word about Christ\" (Romans 10:17).",
      "\"Ang pananampalataya ay ang katiyakan sa mga bagay na inaasahan, ang pagkakatiyak sa mga bagay na hindi nakikita\" (Hebreo 11:1). Si Abraham \"ay sumunod at umalis, kahit hindi niya alam kung saan siya pupunta\" (Hebreo 11:8). Ang pananampalataya ay laging may pinagtitiwalaan: nakaangkla ito sa katangian ng Diyos na tumatawag. At may pinanggagalingan ito: \"Ang pananampalataya ay nanggagaling sa pakikinig, at ang pakikinig ay sa pamamagitan ng salita tungkol kay Cristo\" (Roma 10:17)."
    ),
    insight: [
      t(
        "Many people think faith is a feeling of certainty or the power to talk yourself into an outcome. Scripture never describes it that way. Faith is a response. God speaks, and faith answers with trust that shows up as action. Abraham did not feel confident about the map; he was confident about the One who handed him the journey.",
        "Iniisip ng maraming tao na ang pananampalataya ay pakiramdam ng katiyakan o kakayahang kumbinsihin ang sarili sa isang resulta. Hindi ganyan inilalarawan ng Kasulatan. Ang pananampalataya ay pagtugon. Nagsasalita ang Diyos, at sumasagot ang pananampalataya ng pagtitiwalang lumilitaw bilang kilos. Hindi tiwala si Abraham sa mapa; tiwala siya sa Isang nag-abot sa kanya ng paglalakbay."
      ),
      t(
        "This is why small faith can move great things. Jesus said faith the size of a mustard seed is enough, because the power was never in the seed; it is in the One it is planted toward. And since faith comes by hearing, a believer who is starved of the Word will find faith shrinking, however many times they say they believe.",
        "Kaya ang maliit na pananampalataya ay kayang gumalaw ng malalaking bagay. Sinabi ni Hesus na sapat na ang pananampalatayang kasinliit ng buto ng mustasa, dahil ang kapangyarihan ay wala sa buto kundi sa Isang pinagtitiwalaan nito. At dahil ang pananampalataya ay nanggagaling sa pakikinig, ang mananampalatayang nagugutom sa Salita ay makikitang lumiliit ang pananampalataya, gaano man niya kadalas sabihing naniniwala siya."
      ),
    ],
    life: [
      t(
        "Consider a young Filipino nurse accepting a job offer in Dubai. She has never been there, she is leaving her family, and she cannot see the future. She boards the plane because she trusts the agency, the contract and the people who vouched for it. Now think: God has a far better record than any agency. When He says, \"Go,\" His contract never fails.",
        "Isipin ang batang Pilipinang nars na tumatanggap ng trabaho sa Dubai. Hindi pa siya nakararating doon, iiwan niya ang pamilya, at hindi niya nakikita ang hinaharap. Sumasakay siya ng eroplano dahil nagtitiwala siya sa ahensya, sa kontrata at sa mga taong nagpatunay rito. Ngayon, isipin: mas maganda ang rekord ng Diyos kaysa sa anumang ahensya. Kapag sinabi Niyang, \"Humayo ka,\" hindi kailanman pumapalya ang Kanyang kontrata."
      ),
      t(
        "Faith in daily life is smaller than people think: paying tithes when the budget is tight, forgiving someone who has not said sorry, telling your coworker about Jesus, staying honest when cutting corners would be easier. Each is a small \"going out\" toward an unseen promise.",
        "Mas maliit sa akala ng iba ang pananampalataya sa araw-araw: pagbibigay ng ikapu kahit masikip ang budget, pagpapatawad sa taong hindi pa humihingi ng tawad, pagsasabi kay Hesus sa katrabaho, pananatiling tapat kahit mas madaling mandaya. Bawat isa ay maliit na \"paglabas\" tungo sa pangakong hindi pa nakikita."
      ),
    ],
    twist: t(
      "We usually say, \"I will believe when I see.\" The Kingdom reverses it: \"You will see when you believe.\" Hebrews 11:3 says, \"By faith we understand that the universe was formed at God's command.\" Even understanding starts with trust. Seeing follows obeying, and it often follows the first step, not the last.",
      "Madalas nating sabihin, \"Maniniwala ako kapag nakita ko.\" Binabaligtad ito ng Kaharian: \"Makikita mo kapag naniwala ka.\" Sabi ng Hebreo 11:3, \"Sa pananampalataya, nauunawaan nating ang sansinukob ay nabuo sa utos ng Diyos.\" Maging ang pag-unawa ay nagsisimula sa pagtitiwala. Ang pagkakita ay kasunod ng pagsunod, at madalas ay kasunod ng unang hakbang, hindi ng huli."
    ),
    confirm: [
      t("Hebrews 11:6: without faith it is impossible to please God; he who comes must believe that He exists and rewards those who seek Him.", "Hebreo 11:6: kung walang pananampalataya ay imposibleng bigyang-lugod ang Diyos; ang lumalapit ay dapat maniwalang may Diyos at ginagantimpalaan Niya ang naghahanap."),
      t("Romans 4:20-21: Abraham was fully persuaded that God had power to do what He promised.", "Roma 4:20-21: lubos na nakatiyak si Abraham na may kapangyarihan ang Diyos na gawin ang Kanyang ipinangako."),
      t("Mark 9:24: \"I do believe; help my unbelief!\" Honest, small faith is welcome.", "Marcos 9:24: \"Naniniwala ako; tulungan Mo ang aking kakulangan ng pananampalataya!\" Tinatanggap ang tapat at maliit na pananampalataya."),
      t("James 2:17: faith without works is dead; real faith shows itself in obedience.", "Santiago 2:17: patay ang pananampalatayang walang gawa; ang tunay na pananampalataya ay nakikita sa pagsunod."),
    ],
    heart: [
      t(
        "Stop measuring your faith by how you feel and start measuring it by whom you trust. Fix your eyes on the character of God, not the size of the problem.",
        "Itigil ang pagsukat ng pananampalataya mo sa nararamdaman mo at simulang sukatin ito sa kung sino ang pinagtitiwalaan mo. Ituon ang mata sa katangian ng Diyos, hindi sa laki ng problema."
      ),
      t(
        "Feed your faith daily with the Word, and let it become action. Choose one concrete step of obedience instead of waiting for perfect certainty.",
        "Pakainin ang pananampalataya mo araw-araw ng Salita, at hayaang maging kilos ito. Pumili ng isang tiyak na hakbang ng pagsunod sa halip na maghintay ng perpektong katiyakan."
      ),
    ],
    questions: [
      t("Where is God asking you to step out before you see the whole road?", "Saan ka hinihiling ng Diyos na humakbang bago mo makita ang buong daan?"),
      t("Do you tend to define faith as a feeling? How does Hebrews 11 correct that?", "Madalas mo bang ituring na pakiramdam ang pananampalataya? Paano ito itinatama ng Hebreo 11?"),
      t("How much time in God's Word is feeding your faith each week?", "Gaano karaming oras sa Salita ng Diyos ang nagpapakain sa pananampalataya mo bawat linggo?"),
      t("What promise of God do you need to trust more than your circumstances?", "Anong pangako ng Diyos ang kailangan mong pagtiwalaan nang higit sa iyong kalagayan?"),
    ],
    actions: [
      t("Identify one step of obedience you have been postponing and take it this week.", "Tukuyin ang isang hakbang ng pagsunod na pinapaliban mo at gawin ito ngayong linggo."),
      t("Read Hebrews 11 slowly and underline every \"by faith\" that applies to your life.", "Basahin nang dahan-dahan ang Hebreo 11 at salungguhitan ang bawat \"sa pananampalataya\" na akma sa buhay mo."),
      t("Share your step with someone in your AG so they can pray and cheer you on.", "Ibahagi ang hakbang mo sa isang tao sa iyong AG para maipanalangin ka nila at palakasin ang loob mo."),
    ],
    prayer: t(
      "Lord, I confess that my faith is small, and often it is more about my feelings than about You. Help my unbelief. Grow my faith through Your Word, and fix my eyes on who You are rather than on what I cannot see. Give me courage to obey You, like Abraham, even when I do not have the whole map. I trust You with my family, my work and my future. Lead me one step at a time. In Jesus' name, Amen.",
      "Panginoon, inaamin kong maliit ang pananampalataya ko, at madalas ay nakabatay ito sa damdamin ko kaysa sa Iyo. Tulungan Mo ang aking kakulangan ng pananampalataya. Palaguin Mo ito sa pamamagitan ng Iyong Salita, at ituon Mo ang aking mata sa kung sino Ka kaysa sa hindi ko nakikita. Bigyan Mo ako ng lakas ng loob na sumunod sa Iyo, tulad ni Abraham, kahit wala akong buong mapa. Ipinagkakatiwala ko sa Iyo ang aking pamilya, trabaho at kinabukasan. Akayin Mo ako, isang hakbang sa bawat pagkakataon. Sa pangalan ni Hesus, Amen."
    ),
  },

  "the-kingdom-of-god": {
    revelation: t(
      "The Kingdom is not a place you go to someday; it is a King you submit to today, and everything else is rearranged around Him.",
      "Ang Kaharian ay hindi lugar na pupuntahan mo balang araw; ito ay Haring pinasusukuan mo ngayon, at ang lahat ay nag-aayos muli sa palibot Niya."
    ),
    mainTruth: t(
      "Jesus opened His ministry with one message: \"The time has come. The kingdom of God has come near. Repent and believe the good news!\" (Mark 1:15). The Kingdom is God's rule and reign breaking into the world through Jesus. It begins small like a mustard seed and works quietly like yeast (Matthew 13:31-33), and it is so precious that a person joyfully sells everything to possess it (Matthew 13:44-46).",
      "Sinimulan ni Hesus ang Kanyang ministeryo sa iisang mensahe: \"Dumating na ang takdang panahon. Malapit na ang kaharian ng Diyos. Magsisi kayo at sumampalataya sa mabuting balita!\" (Marcos 1:15). Ang Kaharian ay ang paghahari ng Diyos na pumapasok sa mundo sa pamamagitan ni Hesus. Nagsisimula itong maliit gaya ng buto ng mustasa at tahimik na kumikilos gaya ng lebadura (Mateo 13:31-33), at napakahalaga nito kaya masayang ipinagbibili ng isang tao ang lahat para angkinin ito (Mateo 13:44-46)."
    ),
    insight: [
      t(
        "Many believers think of the Kingdom only as heaven after death. Jesus said it has already come near. It is both \"already\" and \"not yet\": already, because the King is here and His power heals, forgives and sets people free; not yet, because evil and death still remain until He returns. Living between the two means we neither despair at what is broken nor pretend everything is finished.",
        "Iniisip ng maraming mananampalataya na ang Kaharian ay langit lang pagkamatay. Sinabi ni Hesus na malapit na ito. Ito ay \"narito na\" at \"hindi pa ganap\": narito na, dahil narito ang Hari at ang Kanyang kapangyarihan ay nagpapagaling, nagpapatawad at nagpapalaya; hindi pa ganap, dahil nananatili pa ang kasamaan at kamatayan hanggang sa Kanyang pagbabalik. Ang pamumuhay sa pagitan nito ay nangangahulugang hindi tayo nawawalan ng pag-asa sa sira, at hindi rin nagkukunwaring tapos na ang lahat."
      ),
      t(
        "Notice the first word of the message: repent. You cannot enter a new kingdom while still living by the old one's rules. Repentance is not just feeling sorry; it is changing allegiance, turning from being king of your own life to being a citizen under the King. And the two parables of the treasure and the pearl show that this surrender is not a loss but the best bargain ever made.",
        "Pansinin ang unang salita ng mensahe: magsisi. Hindi ka makapapasok sa bagong kaharian habang nabubuhay pa sa batas ng luma. Ang pagsisisi ay hindi lang pagsisisi sa damdamin; ito ay pagbabago ng pagsunod, paglayo sa pagiging hari ng sarili mong buhay tungo sa pagiging mamamayan sa ilalim ng Hari. At ipinakikita ng dalawang talinghaga ng kayamanan at perlas na ang pagsukong ito ay hindi pagkawala kundi ang pinakamagandang kalakal kailanman."
      ),
    ],
    life: [
      t(
        "A small sari-sari store owner in Batangas begins to give credit to neighbors who cannot pay, and quietly refuses to sell cigarettes to children. She never preaches; she simply lets the King run her store. Over time, neighbors begin to ask why. A mustard seed has grown into a tree that gives shade to the whole street.",
        "Isang maliit na may-ari ng sari-sari store sa Batangas ang nagsimulang magpautang sa mga kapitbahay na walang pambayad, at tahimik na tumangging magbenta ng sigarilyo sa mga bata. Hindi siya nangangaral; hinahayaan lang niyang ang Hari ang magpatakbo ng tindahan niya. Sa paglipas ng panahon, nagsimulang magtanong ang mga kapitbahay kung bakit. Ang buto ng mustasa ay naging punong nagbibigay-lilim sa buong kalye."
      ),
      t(
        "For an OFW far from home, the Kingdom is not an abstract idea. Your cramped room, your shift and your video calls are all territory where the King can rule. You may feel unseen, but yeast works hidden in the dough. Your honesty, kindness and prayer are small things the King is multiplying.",
        "Para sa isang OFW na malayo sa tahanan, ang Kaharian ay hindi abstraktong ideya. Ang masikip mong kuwarto, ang iyong shift at ang iyong mga video call ay lahat teritoryo kung saan puwedeng maghari ang Hari. Maaaring pakiramdam mo hindi ka nakikita, pero ang lebadura ay kumikilos nang nakatago sa masa. Ang iyong katapatan, kabaitan at panalangin ay maliliit na bagay na pinararami ng Hari."
      ),
    ],
    twist: t(
      "We expect a kingdom to arrive with armies and noise. Jesus said it arrives like seed and yeast, quiet, slow and hidden, yet unstoppable. The biggest things in God's Kingdom usually begin as things the world would overlook: a baby in a manger, a twelve-man team, a small act of obedience. Do not despise small beginnings; they are the Kingdom's favorite way to start.",
      "Inaasahan natin na ang kaharian ay darating na may hukbo at ingay. Sabi ni Hesus, dumarating ito na parang binhi at lebadura, tahimik, mabagal at nakatago, pero hindi mapipigilan. Ang pinakamalalaking bagay sa Kaharian ng Diyos ay karaniwang nagsisimula sa mga bagay na hindi pinapansin ng mundo: isang sanggol sa sabsaban, isang pangkat ng labindalawa, isang maliit na pagsunod. Huwag hamakin ang maliliit na simula; iyon ang paboritong paraan ng Kaharian na magsimula."
    ),
    confirm: [
      t("Matthew 6:33: seek first His kingdom and His righteousness, and all these things will be given to you.", "Mateo 6:33: hanapin muna ang Kanyang kaharian at ang Kanyang katuwiran, at idaragdag sa inyo ang lahat ng ito."),
      t("Luke 17:20-21: the kingdom of God is in your midst.", "Lucas 17:20-21: ang kaharian ng Diyos ay nasa gitna ninyo."),
      t("Romans 14:17: the kingdom is righteousness, peace and joy in the Holy Spirit.", "Roma 14:17: ang kaharian ay katuwiran, kapayapaan at kagalakan sa Espiritu Santo."),
      t("Colossians 1:13: He rescued us from the dominion of darkness and brought us into the kingdom of His Son.", "Colosas 1:13: iniligtas Niya tayo sa kapangyarihan ng kadiliman at inilipat sa kaharian ng Kanyang Anak."),
    ],
    heart: [
      t(
        "Ask who is truly on the throne of your plans, your money and your time. Let repentance be a joyful turning back to the rightful King, not a heavy religious duty.",
        "Tanungin kung sino talaga ang nasa trono ng iyong mga plano, pera at oras. Gawing masayang pagbabalik sa tunay na Hari ang pagsisisi, hindi mabigat na tungkuling panrelihiyon."
      ),
      t(
        "Learn to value the Kingdom as the treasure it is. When something competes for first place, remember the man in the field who sold everything with joy.",
        "Matutong pahalagahan ang Kaharian bilang kayamanan na ito talaga. Kapag may nakikipagpaligsahan sa unang pwesto, alalahanin ang taong nasa bukid na ipinagbili ang lahat nang may kagalakan."
      ),
    ],
    questions: [
      t("What area of your life are you still ruling yourself instead of letting the King rule?", "Anong bahagi ng buhay mo ang pinamamahalaan mo pa rin sa halip na hayaang maghari ang Hari?"),
      t("What small seed of obedience has God put in your hand to plant?", "Anong maliit na buto ng pagsunod ang inilagay ng Diyos sa kamay mo para itanim?"),
      t("What are you tempted to value above the Kingdom?", "Ano ang natutukso kang pahalagahan nang higit sa Kaharian?"),
      t("Where could you be \"yeast\" in your workplace or home this week?", "Saan ka maaaring maging \"lebadura\" sa trabaho o tahanan mo ngayong linggo?"),
    ],
    actions: [
      t("Pray slowly, \"Your kingdom come, Your will be done,\" over your day each morning this week.", "Ipanalangin nang dahan-dahan ang \"Dumating nawa ang Iyong kaharian, mangyari nawa ang Iyong kalooban\" tuwing umaga ngayong linggo."),
      t("Choose one priority to rearrange so that seeking God's kingdom comes first.", "Pumili ng isang priyoridad na aayusin muli para mauna ang paghahanap sa kaharian ng Diyos."),
      t("Do one quiet act of Kingdom kindness that no one will see.", "Gumawa ng isang tahimik na kabutihan ng Kaharian na walang makakakita."),
    ],
    prayer: t(
      "King Jesus, Your kingdom has come near, and I want to live under Your rule. Forgive me for the places where I have been my own king. Give me eyes to see the Kingdom as the greatest treasure, and joy to give up whatever stands in its way. Use my small obedience like seed and yeast, quietly and surely. Let Your kingdom come in my home, my work and my country. In Your name, Amen.",
      "Haring Hesus, malapit na ang Iyong kaharian, at nais kong mamuhay sa ilalim ng Iyong paghahari. Patawarin Mo ako sa mga bahagi kung saan ako ang sarili kong hari. Bigyan Mo ako ng mata para makita ang Kaharian bilang pinakadakilang kayamanan, at kagalakang isuko ang anumang humahadlang dito. Gamitin Mo ang maliit kong pagsunod gaya ng binhi at lebadura, tahimik at tiyak. Dumating nawa ang Iyong kaharian sa aking tahanan, trabaho at bansa. Sa Iyong pangalan, Amen."
    ),
  },

  "jesus-is-coming-again": {
    revelation: t(
      "Because Jesus is certainly coming back, the right response is not speculation but faithful, joyful readiness today.",
      "Dahil tiyak na babalik si Hesus, ang tamang tugon ay hindi hula-hula kundi tapat at masayang paghahanda ngayon."
    ),
    mainTruth: t(
      "As the disciples stared into the sky, two angels said, \"This same Jesus, who has been taken from you into heaven, will come back in the same way you have seen Him go\" (Acts 1:11). Nobody knows the day or the hour (Matthew 24:36), so Jesus tells us to \"keep watch\" (Matthew 24:42). The delay is not slowness but mercy: \"He is patient with you, not wanting anyone to perish, but everyone to come to repentance\" (2 Peter 3:9). And we look forward to \"a new heaven and a new earth, where righteousness dwells\" (2 Peter 3:13).",
      "Habang nakatingin sa langit ang mga alagad, sinabi ng dalawang anghel, \"Ang Hesus na ito, na kinuha sa inyo paakyat sa langit, ay babalik sa gayunding paraan na nakita ninyo Siyang umakyat\" (Gawa 1:11). Walang nakaaalam ng araw o oras (Mateo 24:36), kaya sinabi ni Hesus na \"magbantay kayo\" (Mateo 24:42). Ang pagkaantala ay hindi kabagalan kundi awa: \"Matiyaga Siya sa inyo, hindi Niya nais na may mapahamak, kundi lahat ay magsisi\" (2 Pedro 3:9). At inaasam natin ang \"bagong langit at bagong lupa, na tinatahanan ng katuwiran\" (2 Pedro 3:13)."
    ),
    insight: [
      t(
        "Notice what the angels did: they stopped the sky-gazing. Looking up in wonder is right, but standing still is not. Believers have always been tempted in two directions: to obsess over timelines and charts, or to forget that He is coming at all. Jesus gave a third way: stay awake, stay holy, stay busy with the mission until He arrives.",
        "Pansinin ang ginawa ng mga anghel: pinatigil nila ang pagtitig sa langit. Tama ang tumingala nang may pagkamangha, pero hindi tama ang manatiling nakatayo lang. Laging natutukso ang mga mananampalataya sa dalawang direksyon: ang mahumaling sa mga petsa at tsart, o ang makalimutan na darating Siya. Nagbigay si Hesus ng ikatlong daan: manatiling gising, manatiling banal, at manatiling abala sa misyon hanggang sa Kanyang pagdating."
      ),
      t(
        "Good Christians differ on the details of the end times, and that is fine. What all agree on is the center: Jesus will return personally, visibly and in glory, He will judge with perfect justice, and He will make all things new. Hold the details loosely and hold the hope tightly. Peter's goal is practical: \"What kind of people ought you to be?\" (2 Peter 3:11).",
        "Nagkakaiba ang mabubuting Kristiyano sa mga detalye ng mga huling panahon, at ayos lang iyon. Ang pinagkakasunduan ng lahat ay ang sentro: personal, nakikita at maluwalhating babalik si Hesus, hahatol Siya nang may ganap na katarungan, at gagawin Niyang bago ang lahat. Maluwag na hawakan ang mga detalye at mahigpit na hawakan ang pag-asa. Praktikal ang layunin ni Pedro: \"Anong uri ng tao ang dapat ninyong maging?\" (2 Pedro 3:11)."
      ),
    ],
    life: [
      t(
        "Think of a family at the airport waiting for their OFW father who is coming home for good after ten years. For weeks, the house is cleaned, the table is planned, the kids practice what to say. Nobody sits in the corner whining that the plane is late; they prepare because he is truly coming. That is the attitude of those who await Jesus.",
        "Isipin ang isang pamilya sa airport na naghihintay sa amang OFW na uuwi na nang tuluyan matapos ang sampung taon. Ilang linggo bago nito, nilinis ang bahay, pinlano ang hapag, nag-ensayo ang mga bata ng sasabihin. Walang nakaupo sa sulok na nagrereklamong late ang eroplano; naghahanda sila dahil tunay siyang darating. Ganyan ang tindig ng mga naghihintay kay Hesus."
      ),
      t(
        "Ask a simple question each Sunday night: \"If Jesus came this week, what would I wish I had done?\" Perhaps forgive your sibling, speak to your coworker about Christ, return what you owe, or restore your devotion. The return of Jesus is not meant to frighten believers but to wake us up and fill us with hope.",
        "Magtanong ng simpleng tanong tuwing Linggo ng gabi: \"Kung dumating si Hesus ngayong linggo, ano ang nais kong nagawa ko na?\" Baka patawarin ang kapatid, magsalita sa katrabaho tungkol kay Cristo, ibalik ang utang, o ibalik ang debosyon. Ang pagbabalik ni Hesus ay hindi para takutin ang mananampalataya kundi para gisingin tayo at punuin ng pag-asa."
      ),
    ],
    twist: t(
      "We often read the delay as God being late. Peter says the opposite: every extra day is another day of mercy, with His arms still open to someone you love who has not yet believed. The waiting is not wasted time; it is an invitation. Your neighbor still has time because God is patient, and you are the person He may use to tell them.",
      "Madalas nating basahin ang pagkaantala bilang pagiging huli ng Diyos. Kabaligtaran ang sabi ni Pedro: bawat dagdag na araw ay dagdag na araw ng awa, na bukas pa rin ang Kanyang bisig sa taong mahal mo na hindi pa naniniwala. Ang paghihintay ay hindi nasasayang na oras; ito ay paanyaya. May oras pa ang kapitbahay mo dahil matiyaga ang Diyos, at ikaw ang taong maaaring gamitin Niya para sabihin sa kanila."
    ),
    confirm: [
      t("John 14:3: \"I will come back and take you to be with Me.\"", "Juan 14:3: \"Babalik Ako at isasama Ko kayo sa Akin.\""),
      t("1 Thessalonians 4:16-18: the Lord Himself will descend, and we encourage one another with these words.", "1 Tesalonica 4:16-18: Siya mismong Panginoon ay bababa, at nagpapalakasan tayo ng loob sa mga salitang ito."),
      t("Titus 2:11-14: the blessed hope trains us to say no to ungodliness and to be eager to do good.", "Tito 2:11-14: ang pinagpalang pag-asa ay nagsasanay sa ating tumanggi sa kasamaan at maging sabik sa paggawa ng mabuti."),
      t("Revelation 22:20: \"Yes, I am coming soon.\" Amen. Come, Lord Jesus.", "Pahayag 22:20: \"Oo, madali Akong darating.\" Amen. Pumarito Ka, Panginoong Hesus."),
    ],
    heart: [
      t(
        "Let the hope of His return loosen your grip on temporary things and tighten your grip on people and mission. Live as someone who is expecting a Guest, not someone fearing an inspection.",
        "Hayaang paluwagin ng pag-asa sa Kanyang pagbabalik ang kapit mo sa mga pansamantalang bagay at higpitan ang kapit mo sa mga tao at misyon. Mamuhay na gaya ng may inaasahang Panauhin, hindi ng natatakot sa inspeksyon."
      ),
      t(
        "Choose holiness out of love, not fear: you are getting ready for the One you love. And stay generous with the gospel while the door of mercy is still open.",
        "Piliin ang kabanalan dahil sa pag-ibig, hindi takot: naghahanda ka para sa Isang minamahal mo. At manatiling bukas-palad sa ebanghelyo habang bukas pa ang pinto ng awa."
      ),
    ],
    questions: [
      t("Does the thought of Jesus returning stir more joy or more fear in you? Why?", "Mas kagalakan o mas takot ba ang dulot sa iyo ng pag-iisip na babalik si Hesus? Bakit?"),
      t("What has been replacing watchfulness in your life: busyness, entertainment, worry?", "Ano ang pumalit sa pagbabantay sa buhay mo: pagiging abala, libangan, pag-aalala?"),
      t("Who in your life still needs more time to hear the gospel?", "Sino sa buhay mo ang nangangailangan pa ng panahon para marinig ang ebanghelyo?"),
      t("What would you do differently if you knew He was coming next month?", "Ano ang gagawin mo nang iba kung alam mong darating Siya sa susunod na buwan?"),
    ],
    actions: [
      t("Pray \"Come, Lord Jesus\" at the start of your day and ask Him to find you faithful.", "Manalangin ng \"Pumarito Ka, Panginoong Hesus\" sa simula ng araw mo at hilingin na matagpuan ka Niyang tapat."),
      t("Settle one unfinished matter: a conflict, a debt, a promise, or a habit.", "Ayusin ang isang hindi pa tapos na usapin: alitan, utang, pangako, o ugali."),
      t("Tell one person this week why you hope in Jesus.", "Sabihin sa isang tao ngayong linggo kung bakit ka umaasa kay Hesus."),
    ],
    prayer: t(
      "Lord Jesus, You ascended in glory, and You promised to return. Keep me watchful and holy while I wait, not frightened but filled with hope. Forgive me for the times I forgot You are coming. Use Your patience to soften my heart toward the people I love who do not yet know You, and give me boldness to speak. Find me faithful when You appear. Even so, come, Lord Jesus. In Your name, Amen.",
      "Panginoong Hesus, umakyat Ka sa kaluwalhatian, at ipinangako Mong babalik Ka. Panatilihin Mo akong mapagbantay at banal habang naghihintay, hindi natatakot kundi puno ng pag-asa. Patawarin Mo ako sa mga panahong nalimutan kong darating Ka. Gamitin Mo ang Iyong pagtitiis para palambutin ang puso ko sa mga mahal ko na hindi pa nakakakilala sa Iyo, at bigyan Mo ako ng katapangang magsalita. Matagpuan Mo sana akong tapat sa Iyong paglitaw. Oo, pumarito Ka, Panginoong Hesus. Sa Iyong pangalan, Amen."
    ),
  },
};
